    pageChatEl.style.cursor = steerLocked ? 'default' : 'text';
    pageChatInput.placeholder = PAGE_CHAT_PLACEHOLDER_EXPANDED;
    if (pageChatHint) {
      pageChatHint.style.display = 'none';
      pageChatHint.style.opacity = '0';
