export interface GeminiKeyView {
  displayName: string;  // "Gemini #1" — never the key value
  keyId: string;
  status: string;
  health: string;
  dailyRequests: number;
  minuteRequests: number;
  dailyTokens: number;
  minuteTokens: number;
  averageLatencyMs: number;
  cooldownRemainingSeconds: number | null;
  lastError: string | null;
  score: number;
  remainingQuota: number;
}

export interface GeminiClusterSummary {
  totalKeys: number;
  healthyKeys: number;
  coolingDownKeys: number;
  disabledKeys: number;
  currentActiveKey: string;
  averageLatencyMs: number;
  averageSuccessRate: number;
  totalDailyRequests: number;
  totalDailyTokens: number;
  totalDailyEstimatedCostUsd: number;
  averageCacheHitRate: number;
  keys: GeminiKeyView[];
}

export class GeminiClusterDashboard {
  private static instance: GeminiClusterDashboard;

  public static getInstance(): GeminiClusterDashboard {
    if (!GeminiClusterDashboard.instance) {
      GeminiClusterDashboard.instance = new GeminiClusterDashboard();
    }
    return GeminiClusterDashboard.instance;
  }

  public getSummary(): GeminiClusterSummary {
    const pool = GeminiPoolManager.getInstance();
    const monitor = ProviderMonitor.getInstance();
    const allStats = pool.getAllAccountStats();

    const now = Date.now();
    let displayIndex = 1;

    const keys: GeminiKeyView[] = allStats.map(acc => {
      const cooldownSeconds =
        acc.health === "CoolingDown" && acc.cooldownUntil
          ? Math.max(0, Math.round((acc.cooldownUntil - now) / 1000))
          : null;

      return {
        displayName: `Gemini #${displayIndex++}`,
        keyId: acc.keyId,
        status: acc.health === "Healthy" ? "Active" : acc.health,
        health: acc.health,
        dailyRequests: acc.requestsToday,
        minuteRequests: acc.requestsThisMinute,
        dailyTokens: acc.tokensToday,
        minuteTokens: acc.tokensThisMinute,
        averageLatencyMs: acc.averageLatencyMs,
        cooldownRemainingSeconds: cooldownSeconds,
        lastError: acc.lastError,
        score: Math.round(pool.calculateAccountScore(acc as any)),
        remainingQuota: acc.remainingQuota,
      };
    });

    const geminiMonitor = monitor.getStats("gemini");
    const healthy = keys.filter(k => k.health === "Healthy").length;
    const cooling = keys.filter(k => k.health === "CoolingDown").length;
    const disabled = keys.filter(k => k.health === "Disabled").length;

    const avgLatency = keys.length > 0
      ? Math.round(keys.reduce((s, k) => s + k.averageLatencyMs, 0) / keys.length)
      : 0;

    const totalDailyRequests = keys.reduce((s, k) => s + k.dailyRequests, 0);
    const totalDailyTokens = keys.reduce((s, k) => s + k.dailyTokens, 0);

    const activeKey = pool.selectBestAccount();

    return {
      totalKeys: keys.length,
      healthyKeys: healthy,
      coolingDownKeys: cooling,
      disabledKeys: disabled,
      currentActiveKey: activeKey?.keyId ?? "none",
      averageLatencyMs: avgLatency,
      averageSuccessRate: monitor.getSuccessRate("gemini"),
      totalDailyRequests,
      totalDailyTokens,
      totalDailyEstimatedCostUsd: geminiMonitor.estimatedCostUsd,
      averageCacheHitRate: monitor.getCacheHitRate("gemini"),
      keys,
    };
  }
}

import { GeminiPoolManager } from "../../gateway/GeminiPoolManager";
import { ProviderMonitor } from "../monitoring/ProviderMonitor";
import { BudgetAlerts } from "../budget/BudgetAlerts";

export interface RoutingDecision {
  requestId: string;
  selectedProviderId: string;
  reasons: string[];
  confidence: number;  // 0–100
  alternativesConsidered: string[];
  budgetLevel: string;
  timestamp: string;
}

export class RoutingAnalytics {
  private static instance: RoutingAnalytics;
  private decisions: RoutingDecision[] = [];

  public static getInstance(): RoutingAnalytics {
    if (!RoutingAnalytics.instance) {
      RoutingAnalytics.instance = new RoutingAnalytics();
    }
    return RoutingAnalytics.instance;
  }

  public explainSelection(params: {
    requestId: string;
    selectedProviderId: string;
    estimatedCostUsd: number;
    action: string;
  }): RoutingDecision {
    const monitor = ProviderMonitor.getInstance();
    const pool = GeminiPoolManager.getInstance();
    const budgetLevel = BudgetAlerts.getInstance().getCurrentLevel();

    const reasons: string[] = [];
    const providerStats = monitor.getStats(params.selectedProviderId);
    const successRate = monitor.getSuccessRate(params.selectedProviderId);
    const avgLatency = monitor.getAverageLatency(params.selectedProviderId);
    const cacheHitRate = monitor.getCacheHitRate(params.selectedProviderId);

    if (successRate >= 95) reasons.push(`معدل نجاح مرتفع (${successRate}%)`);
    if (avgLatency < 300) reasons.push(`متوسط زمن استجابة ممتاز (${avgLatency}ms)`);
    if (providerStats.status === "Healthy") reasons.push("المزوّد في وضع صحي (Healthy)");
    if (params.estimatedCostUsd < 0.001) reasons.push(`تكلفة منخفضة ($${params.estimatedCostUsd.toFixed(6)})`);
    if (cacheHitRate > 30) reasons.push(`معدل cache مرتفع (${cacheHitRate}%)`);
    if (budgetLevel === "Economy") reasons.push("تم اختياره تلقائياً لتوفير الميزانية (Economy Mode)");

    // Check Gemini pool score if applicable
    if (params.selectedProviderId === "gemini") {
      const selectedGeminiKey = pool.selectBestAccount();
      if (selectedGeminiKey) {
        const score = pool.calculateAccountScore(selectedGeminiKey as any);
        reasons.push(`أعلى نتيجة في مجموعة Gemini (${score.toFixed(0)}/100)`);
      }
    }

    if (reasons.length === 0) reasons.push("تم الاختيار الافتراضي بناءً على ترتيب المزوّدين");

    const confidence = Math.min(99, 70 + reasons.length * 5);
    const alternativesConsidered = ["deepseek_v4_flash", "gemini", "mock"].filter(id => id !== params.selectedProviderId);

    const decision: RoutingDecision = {
      requestId: params.requestId,
      selectedProviderId: params.selectedProviderId,
      reasons,
      confidence,
      alternativesConsidered,
      budgetLevel,
      timestamp: new Date().toISOString(),
    };

    this.decisions.push(decision);
    if (this.decisions.length > 500) this.decisions.shift();

    return decision;
  }

  public getRecentDecisions(limit = 20): RoutingDecision[] {
    return this.decisions.slice(-limit).reverse();
  }
}

export class LayeredTeacher {
  /**
   * Generates prompt instructions for the 5-layer pedagogical teaching framework.
