export type AccountHealth = "Healthy" | "CoolingDown" | "Disabled";

export interface AccountStats {
  keyId: string;
  secretKey: string;
  requestsToday: number;
  requestsThisMinute: number;
  tokensToday: number;
  tokensThisMinute: number;
  health: AccountHealth;
  lastError: string | null;
  cooldownUntil: number | null;
  averageLatencyMs: number;
  remainingQuota: number; // 0 - 100 percentage
  scorePenalties: number;
  totalSuccesses: number;
}

export class GeminiPoolManager {
  private static instance: GeminiPoolManager;
  private accounts: Map<string, AccountStats> = new Map();
  private lastResetDay = new Date().getDate();
  private lastResetMinute = new Date().getMinutes();

  private constructor() {
    this.discoverAccountsFromEnv();
  }

  public static getInstance(): GeminiPoolManager {
    if (!GeminiPoolManager.instance) {
      GeminiPoolManager.instance = new GeminiPoolManager();
    }
    return GeminiPoolManager.instance;
  }

  /**
   * Scans process.env for all GEMINI_KEY_* and GEMINI_API_KEY* entries dynamically.
   */
  public discoverAccountsFromEnv(): void {
    const env = process.env;
    let found = 0;

    for (const [key, value] of Object.entries(env)) {
      if ((key.startsWith("GEMINI_KEY_") || key.startsWith("GEMINI_API_KEY")) && value && value.trim().length > 0) {
        const keyId = key.toLowerCase();
        if (!this.accounts.has(keyId)) {
          this.accounts.set(keyId, {
            keyId,
            secretKey: value.trim(),
            requestsToday: 0,
            requestsThisMinute: 0,
            tokensToday: 0,
            tokensThisMinute: 0,
            health: "Healthy",
            lastError: null,
            cooldownUntil: null,
            averageLatencyMs: 150,
            remainingQuota: 100,
            scorePenalties: 0,
            totalSuccesses: 0,
          });
          found++;
        }
      }
    }

    // Fallback stub account if no env vars present
    if (this.accounts.size === 0) {
      this.accounts.set("gemini_default_sandbox", {
        keyId: "gemini_default_sandbox",
        secretKey: "sandbox_gemini_key",
        requestsToday: 0,
        requestsThisMinute: 0,
        tokensToday: 0,
        tokensThisMinute: 0,
        health: "Healthy",
        lastError: null,
        cooldownUntil: null,
        averageLatencyMs: 100,
        remainingQuota: 100,
        scorePenalties: 0,
        totalSuccesses: 0,
      });
    }
  }

  /**
   * Selects the optimal Gemini API account based on composite score:
   * Score = RemainingQuota * 35% + Health * 25% + Latency * 15% + MinuteUsage * 15% + DailyUsage * 10%
   */
  public selectBestAccount(): AccountStats {
    this.checkAutoReset();
    this.updateCooldownStatuses();

    let bestAccount: AccountStats | null = null;
    let highestScore = -Infinity;

    for (const account of this.accounts.values()) {
      if (account.health === "Disabled") continue;

      if (account.health === "CoolingDown") {
        if (account.cooldownUntil && Date.now() < account.cooldownUntil) {
          continue; // Still cooling down
        } else {
          // Cooldown expired
          account.health = "Healthy";
          account.cooldownUntil = null;
        }
      }

      const score = this.calculateAccountScore(account);
      if (score > highestScore) {
        highestScore = score;
        bestAccount = account;
      }
    }

    if (!bestAccount) {
      // If all accounts cooling down/disabled, pick healthiest or default
      const allAccounts = Array.from(this.accounts.values());
      bestAccount = allAccounts.find(a => a.health !== "Disabled") || allAccounts[0];
    }

    return bestAccount;
  }

  public calculateAccountScore(account: AccountStats): number {
    const quotaScore = account.remainingQuota * 0.35;
    const healthScore = (account.health === "Healthy" ? 100 : account.health === "CoolingDown" ? 20 : 0) * 0.25;
    const latencyScore = Math.max(0, 100 - (account.averageLatencyMs / 20)) * 0.15;
    const minuteUsageScore = Math.max(0, 100 - (account.requestsThisMinute * 5)) * 0.15;
    const dailyUsageScore = Math.max(0, 100 - (account.requestsToday / 50)) * 0.10;

    const total = quotaScore + healthScore + latencyScore + minuteUsageScore + dailyUsageScore - account.scorePenalties;
    return Math.max(0, total);
  }

  public recordSuccess(keyId: string, tokens: number, latencyMs: number): void {
    const account = this.accounts.get(keyId);
    if (!account) return;

    account.requestsToday++;
    account.requestsThisMinute++;
    account.tokensToday += tokens;
    account.tokensThisMinute += tokens;
    account.totalSuccesses++;

    // Exponential moving average latency calculation
    account.averageLatencyMs = Math.round(account.averageLatencyMs * 0.8 + latencyMs * 0.2);

    // Slowly recover quota & penalties
    account.remainingQuota = Math.max(10, account.remainingQuota - 0.05);
    account.scorePenalties = Math.max(0, account.scorePenalties - 1);

    // Safe logging (NEVER logs secret key string)
    const estimatedCostUsd = (tokens / 1000) * 0.00015;
    console.log(
      `[GeminiPoolManager] Account '${account.keyId}' Executed Successfully | Tokens: ${tokens} | Latency: ${latencyMs}ms | Est. Cost: $${estimatedCostUsd.toFixed(6)} | Remaining Quota: ${account.remainingQuota.toFixed(1)}%`
    );
  }

  public recordRateLimit(keyId: string, retryAfterMs = 60000): void {
    const account = this.accounts.get(keyId);
    if (!account) return;

    account.health = "CoolingDown";
    account.cooldownUntil = Date.now() + retryAfterMs;
    account.lastError = `429 Rate Limit (Cooldown ${retryAfterMs / 1000}s)`;
    account.remainingQuota = Math.max(5, account.remainingQuota - 20);

    console.warn(`[GeminiPoolManager] Account '${account.keyId}' hit 429 Rate Limit. Cooling down for ${retryAfterMs / 1000}s.`);
  }

  public recordUnauthorized(keyId: string): void {
    const account = this.accounts.get(keyId);
    if (!account) return;

    account.health = "Disabled";
    account.lastError = "401 Unauthorized / Invalid API Key";
    account.remainingQuota = 0;

    console.error(`[GeminiPoolManager] Account '${account.keyId}' returned 401 Unauthorized. Account permanently DISABLED.`);
  }

  public recordServerError(keyId: string, errorMsg: string): void {
    const account = this.accounts.get(keyId);
    if (!account) return;

    account.scorePenalties += 15;
    account.lastError = `5xx Server Error: ${errorMsg}`;

    console.warn(`[GeminiPoolManager] Account '${account.keyId}' returned 5xx Server Error. Temporary score penalty applied (+15).`);
  }

  public getAllAccountStats(): Omit<AccountStats, "secretKey">[] {
    return Array.from(this.accounts.values()).map(acc => {
      const { secretKey, ...safeStats } = acc;
      return safeStats;
    });
  }

  private updateCooldownStatuses(): void {
    const now = Date.now();
    for (const account of this.accounts.values()) {
      if (account.health === "CoolingDown" && account.cooldownUntil && now >= account.cooldownUntil) {
        account.health = "Healthy";
        account.cooldownUntil = null;
      }
    }
  }

  private checkAutoReset(): void {
    const now = new Date();

    if (now.getDate() !== this.lastResetDay) {
      for (const acc of this.accounts.values()) {
        acc.requestsToday = 0;
        acc.tokensToday = 0;
        acc.remainingQuota = 100;
      }
      this.lastResetDay = now.getDate();
    }

    if (now.getMinutes() !== this.lastResetMinute) {
      for (const acc of this.accounts.values()) {
        acc.requestsThisMinute = 0;
        acc.tokensThisMinute = 0;
      }
      this.lastResetMinute = now.getMinutes();
    }
  }
}

import { BaseProvider } from "./BaseProvider";
import { GenerateOptions, GenerateResult, ProviderCapabilities, StreamChunk, StreamResult } from "../types";

export class DeepSeekV4FlashProvider extends BaseProvider {
  public id = "deepseek_v4_flash";
  public name = "DeepSeek V4 Flash Provider";
  public capabilities: ProviderCapabilities = {
    supportsStreaming: true,
    supportsEmbeddings: true,
    supportsVision: false,
    maxContextTokens: 64000,
  };

  private apiKey: string;
  private baseUrl: string;
  private model: string;

  constructor(options?: { id?: string; apiKey?: string; baseUrl?: string; model?: string }) {
    super();
    if (options?.id) this.id = options.id;
    this.apiKey = options?.apiKey || process.env.DEEPSEEK_API_KEY || "YnaFQDjz3mNWZi0KiPrM-HcslcqyWDB9";
    this.baseUrl = (options?.baseUrl || process.env.DEEPSEEK_BASE_URL || "https://api.deepseek.com/v1").replace(/\/$/, "");
    this.model = options?.model || process.env.DEEPSEEK_MODEL || "deepseek-v4-flash";
  }

  public async generate(options: GenerateOptions): Promise<GenerateResult> {
    const startTime = Date.now();
    const promptText = this.extractPromptText(options.prompt);
    const systemInstruction = typeof options.prompt === "object"
      ? `${options.prompt.identity}\n${options.prompt.teachingStyle}\n${options.prompt.subjectRules}`
      : options.systemPrompt;

    const inputTokens = this.estimateTokens(promptText);

    // If API key is missing or test execution environment
    if (!this.apiKey || this.apiKey === "mock" || process.env.NODE_ENV === "test") {
      return this.generateSimulatedResult(promptText, inputTokens, startTime);
    }

    let retriesLeft = 1;
    let lastError: Error | null = null;

    while (retriesLeft >= 0) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), options.timeoutMs || 15000);

        const response = await fetch(`${this.baseUrl}/chat/completions`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${this.apiKey}`,
          },
          body: JSON.stringify({
            model: this.model,
            messages: [
              ...(systemInstruction ? [{ role: "system", content: systemInstruction }] : []),
              { role: "user", content: promptText },
            ],
            temperature: options.temperature ?? 0.7,
            max_tokens: options.maxTokens ?? 1000,
          }),
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        if (response.status === 429) {
          throw new Error("Rate limit exceeded on DeepSeek V4 Flash API.");
        }

        if (response.status >= 400 && response.status < 500) {
          const errBody = await response.text();
          throw new Error(`DeepSeek API Client Error (${response.status}): ${errBody}`);
        }

        if (!response.ok) {
          throw new Error(`DeepSeek API Server Error (${response.status})`);
        }

        const data = await response.json();
        const choiceText = data.choices?.[0]?.message?.content || "";
        const usageInput = data.usage?.prompt_tokens || inputTokens;
        const usageOutput = data.usage?.completion_tokens || this.estimateTokens(choiceText);
        const totalTokens = usageInput + usageOutput;

        return {
          text: choiceText,
          providerId: this.id,
          providerName: this.name,
          inputTokens: usageInput,
          outputTokens: usageOutput,
          totalTokens,
          latencyMs: Date.now() - startTime,
        };
      } catch (err: any) {
        lastError = err instanceof Error ? err : new Error(String(err));

        if (lastError.message.includes("400") || lastError.message.includes("401") || lastError.message.includes("Rate limit")) {
          break;
        }

        retriesLeft--;
        if (retriesLeft < 0) break;
      }
    }

    console.warn(`[DeepSeekV4FlashProvider] Provider call failed (${lastError?.message}). Throwing error for fallback chain.`);
    throw lastError || new Error("DeepSeek V4 Flash API call failed");
  }

  public async *stream(options: GenerateOptions): AsyncGenerator<StreamChunk, StreamResult, unknown> {
    const result = await this.generate(options);
    const words = result.text.split(" ");
    let fullText = "";

    for (const word of words) {
      const delta = word + " ";
      fullText += delta;
      yield { delta, done: false };
    }

    yield { delta: "", done: true };
    return {
      fullText,
      providerId: this.id,
      inputTokens: result.inputTokens,
      outputTokens: result.outputTokens,
      totalTokens: result.totalTokens,
    };
  }

  private generateSimulatedResult(promptText: string, inputTokens: number, startTime: number): GenerateResult {
    const outputText = `[DeepSeek V4 Flash]: تم تحليل استفسارك بذكاء وتوفير الإجابة التعليمية المناسبة بناءً على المنهج المصري والمستوى الدراسي الحالي. (${promptText.slice(0, 30)}...)`;
    const outputTokens = this.estimateTokens(outputText);

    return {
      text: outputText,
      providerId: this.id,
      providerName: this.name,
      inputTokens,
      outputTokens,
      totalTokens: inputTokens + outputTokens,
      latencyMs: Date.now() - startTime,
    };
  }
}

import { BaseProvider } from "./BaseProvider";
import { GeminiPoolManager } from "../gateway/GeminiPoolManager";
import { GenerateOptions, GenerateResult, ProviderCapabilities, StreamChunk, StreamResult } from "../types";

export class GeminiProvider extends BaseProvider {
  public id = "gemini";
  public name = "Google Gemini Pool Provider";
  public capabilities: ProviderCapabilities = {
    supportsStreaming: true,
    supportsEmbeddings: true,
    supportsVision: true,
    maxContextTokens: 128000,
  };

  private poolManager: GeminiPoolManager;

  constructor() {
    super();
    this.poolManager = GeminiPoolManager.getInstance();
  }

  public async generate(options: GenerateOptions): Promise<GenerateResult> {
    const startTime = Date.now();
    const promptText = this.extractPromptText(options.prompt);
    const inputTokens = this.estimateTokens(promptText);

    // Select optimal Gemini key from multi-account pool
    const selectedAccount = this.poolManager.selectBestAccount();

    // If sandbox / test mode or secret key unavailable
    if (selectedAccount.secretKey.includes("sandbox") || process.env.NODE_ENV === "test") {
      const simulatedText = `[Google Gemini Pool (${selectedAccount.keyId})]: تم توليد الشرح والتحليل التعليمي المتقدم بذكاء فائق للمنهج المصري.`;
      const outputTokens = this.estimateTokens(simulatedText);
      const latency = Date.now() - startTime;

      this.poolManager.recordSuccess(selectedAccount.keyId, inputTokens + outputTokens, latency);

      return {
        text: simulatedText,
        providerId: this.id,
        providerName: this.name,
        inputTokens,
        outputTokens,
        totalTokens: inputTokens + outputTokens,
        latencyMs: latency,
      };
    }

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), options.timeoutMs || 15000);

      const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-goog-api-key": selectedAccount.secretKey,
          },
          body: JSON.stringify({
            contents: [
              {
                parts: [{ text: promptText }],
              },
            ],
          }),
          signal: controller.signal,
        }
      );

      clearTimeout(timeoutId);

      if (response.status === 429) {
        this.poolManager.recordRateLimit(selectedAccount.keyId, 60000);
        throw new Error(`429 Rate Limit on Gemini account ${selectedAccount.keyId}`);
      }

      if (response.status === 401 || response.status === 403) {
        this.poolManager.recordUnauthorized(selectedAccount.keyId);
        throw new Error(`401/403 Unauthorized on Gemini account ${selectedAccount.keyId}`);
      }

      if (response.status >= 500) {
        this.poolManager.recordServerError(selectedAccount.keyId, `Status ${response.status}`);
        throw new Error(`5xx Server Error on Gemini account ${selectedAccount.keyId}`);
      }

      if (!response.ok) {
        throw new Error(`Gemini API Error (${response.status})`);
      }

      const data = await response.json();
      const textResult = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
      const outputTokens = this.estimateTokens(textResult);
      const latency = Date.now() - startTime;

      this.poolManager.recordSuccess(selectedAccount.keyId, inputTokens + outputTokens, latency);

      return {
        text: textResult,
        providerId: this.id,
        providerName: this.name,
        inputTokens,
        outputTokens,
        totalTokens: inputTokens + outputTokens,
        latencyMs: latency,
      };
    } catch (err: any) {
      console.warn(`[GeminiProvider] Key '${selectedAccount.keyId}' failed (${err?.message}). Throwing error for fallback chain.`);
      throw err instanceof Error ? err : new Error(String(err));
    }
  }

  public async *stream(options: GenerateOptions): AsyncGenerator<StreamChunk, StreamResult, unknown> {
    const result = await this.generate(options);
    const words = result.text.split(" ");
    let fullText = "";

    for (const word of words) {
      const delta = word + " ";
      fullText += delta;
      yield { delta, done: false };
    }

    yield { delta: "", done: true };
    return {
      fullText,
      providerId: this.id,
      inputTokens: result.inputTokens,
      outputTokens: result.outputTokens,
      totalTokens: result.totalTokens,
    };
  }
}

