    const param = isPlan ? `planId=${targetId}` : `courseId=${targetId}`;
    const res = await fetch(`/api/admin/codes?${param}`, { credentials: "include" });
    const data = await readJson<{ codes?: AccessCode[] }>(res);
    setCodes(data?.codes || []);
