// ─── Local presentational helpers ──────────────────────────────────────────────

function CourseThumb({ course }: { course: Course }) {
  if (course.thumbnailUrl) {
    return <Image src={course.thumbnailUrl} alt={course.title} width={48} height={48} className="w-12 h-12 rounded-xl object-cover shrink-0" unoptimized />;
  }
  return (
    <div className="w-12 h-12 rounded-xl bg-sky-500/12 text-sky-500 dark:text-sky-300 flex items-center justify-center shrink-0">
      <IconBook className="w-5 h-5" />
    </div>
  );
}

function EmptyState({ icon, title, hint, action }: { icon: React.ReactNode; title: string; hint?: string; action?: React.ReactNode }) {
  return (
    <div className="py-12 px-6 text-center">
      <div className="mx-auto mb-4 w-14 h-14 rounded-2xl border border-[var(--border)] bg-[var(--bg)] text-[var(--ink-muted)] flex items-center justify-center">
        {icon}
      </div>
      <p className="font-bold text-[var(--ink)]">{title}</p>
      {hint && <p className="text-sm text-[var(--ink-muted)] mt-1.5 max-w-sm mx-auto leading-6">{hint}</p>}
      {action && <div className="mt-5 flex justify-center">{action}</div>}
    </div>
  );
}

function CoursePicker({ courses, onSelect, hint, sub }: { courses: Course[]; onSelect: (c: Course) => void; hint: string; sub: (c: Course) => string }) {
  if (courses.length === 0) {
    return (
      <div className={cardPad}>
        <EmptyState icon={<IconBook className="w-7 h-7" />} title="لا توجد كورسات" hint="أنشئ كورساً أولاً." />
      </div>
    );
  }
  return (
    <div>
      <p className="text-sm text-[var(--ink-muted)] mb-4">{hint}</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {courses.map((c) => (
          <button key={c.id} onClick={() => onSelect(c)} className={`${cardPad} text-right hover:border-sky-400/50 transition-colors`}>
            <p className="font-bold text-[var(--ink)] truncate">{c.title}</p>
            <p className="text-sm text-[var(--ink-muted)] mt-0.5">{sub(c)}</p>
          </button>
        ))}
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { logAdminAction } from "@/lib/admin-auth";
import { encryptSecret, normalizeModels, encryptionConfigured } from "@/lib/ai-provider";

async function requireSuperadmin() {
  const session = await getSession();
  if (!session || session.role !== "superadmin") return null;
  return session;
}

/** Update a provider. A present apiKey is encrypted and overwrites the old one. */
export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
    const __logSession = await getSession();
    if (__logSession && __logSession.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: __logSession.id,
          adminName: __logSession.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }

  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  try {
    const { id } = await params;
    const body = (await req.json().catch(() => ({}))) as {
      name?: string;
      baseUrl?: string;
      models?: unknown;
      apiKey?: string;
      isPrimary?: boolean;
      isBackup?: boolean;
      isActive?: boolean;
    };

    const existing = await prisma.aIProvider.findUnique({ where: { id } });
    if (!existing) return NextResponse.json({ error: "المزوّد غير موجود" }, { status: 404 });

    const data: Record<string, unknown> = {};
    if (typeof body.name === "string" && body.name.trim()) data.name = body.name.trim();
    if (typeof body.baseUrl === "string" && body.baseUrl.trim()) data.baseUrl = body.baseUrl.trim();
    if (body.models !== undefined) data.models = normalizeModels(body.models);
    if (typeof body.isActive === "boolean") data.isActive = body.isActive;

    // Key rotation — encrypt and overwrite; plaintext is never stored or returned.
    if (typeof body.apiKey === "string" && body.apiKey) {
      if (!encryptionConfigured()) {
        return NextResponse.json(
          { error: "لا يمكن حفظ المفتاح: لم يتم ضبط CONFIG_ENCRYPTION_KEY في الخادم" },
          { status: 400 }
        );
      }
      data.apiKeyEnc = encryptSecret(body.apiKey);
    }

    // Single primary / single backup, and a provider can't be both at once.
    if (body.isPrimary === true) {
      await prisma.aIProvider.updateMany({ where: { isPrimary: true }, data: { isPrimary: false } });
      data.isPrimary = true;
      data.isBackup = false; // primary can't also be the backup
    } else if (body.isPrimary === false) {
      data.isPrimary = false;
    }
    if (body.isBackup === true) {
      await prisma.aIProvider.updateMany({ where: { isBackup: true }, data: { isBackup: false } });
      data.isBackup = true;
      data.isPrimary = false; // backup can't also be the primary
    } else if (body.isBackup === false) {
      data.isBackup = false;
    }

    await prisma.aIProvider.update({ where: { id }, data });

    await logAdminAction({
      adminId: session.id,
      adminName: session.name,
      action: "EDIT_AI_PROVIDER",
      targetType: "ai_provider",
      targetId: id,
      targetName: existing.name,
      metadata: { keyRotated: !!body.apiKey },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("AI provider PATCH error:", error);
    return NextResponse.json({ error: "تعذر تعديل المزوّد" }, { status: 500 });
  }
}

export async function DELETE(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  try {
    const { id } = await params;
    const existing = await prisma.aIProvider.findUnique({ where: { id }, select: { name: true } });
    if (!existing) return NextResponse.json({ error: "المزوّد غير موجود" }, { status: 404 });

    await prisma.aIProvider.delete({ where: { id } });

    await logAdminAction({
      adminId: session.id,
      adminName: session.name,
      action: "DELETE_AI_PROVIDER",
      targetType: "ai_provider",
      targetId: id,
      targetName: existing.name,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("AI provider DELETE error:", error);
    return NextResponse.json({ error: "تعذر حذف المزوّد" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { logAdminAction } from "@/lib/admin-auth";
import {
  getActiveProviders,
  encryptSecret,
  normalizeModels,
  encryptionConfigured,
} from "@/lib/ai-provider";

async function requireSuperadmin() {
  const session = await getSession();
  if (!session || session.role !== "superadmin") return null;
  return session;
}

/** List providers — NO keys, only hasKey booleans. */
export async function GET() {
  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  const providers = await getActiveProviders();
  return NextResponse.json({ providers, encryptionConfigured: encryptionConfigured() });
}

/** Create a provider. If apiKey is present it's encrypted; the plaintext is dropped. */
export async function POST(req: NextRequest) {
    const __logSession = await getSession();
    if (__logSession && __logSession.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: __logSession.id,
          adminName: __logSession.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }

  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  try {
    const body = (await req.json().catch(() => ({}))) as {
      name?: string;
      slug?: string;
      baseUrl?: string;
      models?: unknown;
      apiKey?: string;
      isPrimary?: boolean;
      isBackup?: boolean;
      isActive?: boolean;
    };

    const name = body.name?.trim() ?? "";
    const slug = body.slug?.trim().toLowerCase().replace(/\s+/g, "-") ?? "";
    const baseUrl = body.baseUrl?.trim() ?? "";
    if (!name || !slug || !baseUrl) {
      return NextResponse.json({ error: "الاسم والمعرّف ورابط الـ API مطلوبة" }, { status: 400 });
    }
    if (body.apiKey && !encryptionConfigured()) {
      return NextResponse.json(
        { error: "لا يمكن حفظ المفتاح: لم يتم ضبط CONFIG_ENCRYPTION_KEY في الخادم" },
        { status: 400 }
      );
    }

    const exists = await prisma.aIProvider.findUnique({ where: { slug } });
    if (exists) return NextResponse.json({ error: "المعرّف مستخدم بالفعل" }, { status: 409 });

    const created = await prisma.aIProvider.create({
      data: {
        name,
        slug,
        baseUrl,
        models: normalizeModels(body.models),
        apiKeyEnc: body.apiKey ? encryptSecret(body.apiKey) : null,
        isActive: body.isActive ?? true,
        // Primary/backup flags are managed via PATCH (single-flag enforcement there).
      },
      select: { id: true, name: true },
    });

    await logAdminAction({
      adminId: session.id,
      adminName: session.name,
      action: "CREATE_AI_PROVIDER",
      targetType: "ai_provider",
      targetId: created.id,
      targetName: created.name,
    });

    return NextResponse.json({ success: true, id: created.id });
  } catch (error) {
    console.error("AI provider create error:", error);
    return NextResponse.json({ error: "تعذر إنشاء المزوّد" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
  try {
  const session = await getSession();
  if (!session || session.role !== "teacher") {
    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
  }

  const teacherId = session.id;

  // Fetch all quiz results for courses taught by this teacher
  const quizResults = await prisma.quizResult.findMany({
    where: {
      quiz: {
        folder: {
          course: {
            teacherId: teacherId,
          },
        },
      },
    },
    select: {
      score: true,
      quiz: {
        select: {
          title: true,
          folder: {
            select: {
              course: {
                select: {
                  subject: true,
                  title: true,
                },
              },
            },
          },
        },
      },
    },
  });

  // Group by subject to build the heatmap data
  type SubjectAgg = { subject: string; sum: number; count: number; minScore: number; maxScore: number };
  const subjectMap = new Map<string, SubjectAgg>();

  for (const q of quizResults) {
    const subject = q.quiz?.folder?.course?.subject?.trim() || "عام";
    let agg = subjectMap.get(subject);
    if (!agg) {
      agg = { subject, sum: 0, count: 0, minScore: 100, maxScore: 0 };
      subjectMap.set(subject, agg);
    }
    agg.sum += q.score;
    agg.count += 1;
    if (q.score < agg.minScore) agg.minScore = q.score;
    if (q.score > agg.maxScore) agg.maxScore = q.score;
  }

  const heatmap = [...subjectMap.values()].map((a) => ({
    subject: a.subject,
    avgScore: Math.round(a.sum / a.count),
    quizCount: a.count,
    minScore: a.minScore === 100 && a.count === 0 ? 0 : a.minScore,
    maxScore: a.maxScore,
  })).sort((a, b) => a.avgScore - b.avgScore);

  return NextResponse.json({ heatmap });
} catch (error) {
    console.error("[admin/analytics/weakness] error:", error);
    return NextResponse.json(
      { error: "حدث خطأ داخلي" },
      { status: 500 }
    );
  }
}

import { logAdminAction } from "@/lib/admin-auth";
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import crypto from "crypto";

const MAX_BULK = 200;

function generateCode(prefix?: string): string {
  const hex = crypto.randomBytes(4).toString("hex").toUpperCase();
  return prefix ? `${prefix.toUpperCase()}-${hex}` : hex;
}

export async function POST(req: NextRequest) {
  try {
    const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
    if (!session || (session.role !== "teacher" && session.role !== "superadmin")) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
    }

    const body = await req.json();
    const { courseId, planId, prefix, format } = body as {
      courseId?: string;
      planId?: string;
      count?: number;
      prefix?: string;
      format?: string;
    };
    const count = Math.min(Math.max(1, Math.floor(Number(body.count) || 1)), MAX_BULK);

    const cleanPrefix = prefix ? String(prefix).trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 10) : undefined;

    // Plan bulk codes
    if (planId) {
      const plan = await prisma.plan.findUnique({
        where: { id: planId },
        select: { id: true, title: true },
      });
      if (!plan) return NextResponse.json({ error: "الخطة غير موجودة" }, { status: 404 });

      const codes: string[] = [];
      const maxAttempts = count * 3;
      let attempts = 0;
      while (codes.length < count && attempts < maxAttempts) {
        attempts++;
        const code = generateCode(cleanPrefix);
        if (!codes.includes(code)) {
          const exists = await prisma.planAccessCode.findUnique({ where: { code }, select: { id: true } });
          if (!exists) codes.push(code);
        }
      }

      if (codes.length < count) {
        return NextResponse.json({ error: `تعذر إنشاء ${count} كود فريد — حاول بعدد أقل أو بادئة مختلفة` }, { status: 409 });
      }

      const created = await prisma.$transaction(
        codes.map((code) => prisma.planAccessCode.create({ data: { code, planId } }))
      );

      if (format === "csv") {
        const csvHeader = "code,planId,planTitle,createdAt";
        const csvRows = created.map(
          (c) => `${c.code},${c.planId},"${plan.title.replace(/"/g, '""')}",${c.createdAt.toISOString()}`
        );
        const csvContent = [csvHeader, ...csvRows].join("\n");
        const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);

        return new NextResponse(csvContent, {
          status: 200,
          headers: {
            "Content-Type": "text/csv; charset=utf-8",
            "Content-Disposition": `attachment; filename="plan-codes-${planId}-${timestamp}.csv"`,
          },
        });
      }

      return NextResponse.json({ codes: created, count: created.length }, { status: 201 });
    }

    // Course bulk codes
    if (!courseId) {
      return NextResponse.json({ error: "courseId أو planId مطلوب" }, { status: 400 });
    }

    const courseWhere = session.role === "superadmin" ? { id: courseId } : { id: courseId, teacherId: session.id };
    const course = await prisma.course.findFirst({
      where: courseWhere,
      select: { id: true, title: true },
    });
    if (!course) {
      return NextResponse.json({ error: "الكورس غير موجود" }, { status: 404 });
    }

    const codes: string[] = [];
    const maxAttempts = count * 3;
    let attempts = 0;
    while (codes.length < count && attempts < maxAttempts) {
      attempts++;
      const code = generateCode(cleanPrefix);
      if (!codes.includes(code)) {
        const exists = await prisma.accessCode.findUnique({ where: { code }, select: { id: true } });
        if (!exists) codes.push(code);
      }
    }

    if (codes.length < count) {
      return NextResponse.json({ error: `تعذر إنشاء ${count} كود فريد — حاول بعدد أقل أو بادئة مختلفة` }, { status: 409 });
    }

    const created = await prisma.$transaction(
      codes.map((code) => prisma.accessCode.create({ data: { code, courseId } }))
    );

    if (format === "csv") {
      const csvHeader = "code,courseId,courseTitle,createdAt";
      const csvRows = created.map(
        (c) => `${c.code},${c.courseId},"${course.title.replace(/"/g, '""')}",${c.createdAt.toISOString()}`
      );
      const csvContent = [csvHeader, ...csvRows].join("\n");
      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);

      return new NextResponse(csvContent, {
        status: 200,
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="codes-${courseId}-${timestamp}.csv"`,
        },
      });
    }

    return NextResponse.json({ codes: created, count: created.length }, { status: 201 });
  } catch (error) {
    console.error("[admin/codes/bulk] error:", error);
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

