import { logAdminAction } from "@/lib/admin-auth";
/* eslint-disable @typescript-eslint/no-explicit-any */
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

// Validation constants
const MIN_QUESTIONS = 1;
const MAX_QUESTIONS = 50;
const MIN_OPTIONS = 2;
const MAX_OPTIONS = 4;
const MAX_QUESTION_LENGTH = 500;
const MAX_OPTION_LENGTH = 200;
const MAX_TITLE_LENGTH = 100;
const MIN_TIME_LIMIT = 1;
const MAX_TIME_LIMIT = 240;

function validateQuizData(title: string, questions: any[]): { valid: boolean; error?: string } {
  // Validate title
  if (!title || typeof title !== "string") {
    return { valid: false, error: "عنوان الاختبار مطلوب" };
  }
  
  if (title.trim().length === 0) {
    return { valid: false, error: "عنوان الاختبار لا يمكن أن يكون فارغاً" };
  }
  
  if (title.length > MAX_TITLE_LENGTH) {
    return { valid: false, error: `عنوان الاختبار لا يمكن أن يزيد عن ${MAX_TITLE_LENGTH} حرف` };
  }

  // Validate questions array
  if (!Array.isArray(questions) || questions.length === 0) {
    return { valid: false, error: "يجب أن يحتوي الاختبار على سؤال واحد على الأقل" };
  }

  if (questions.length > MAX_QUESTIONS) {
    return { valid: false, error: `لا يمكن أن يحتوي الاختبار على أكثر من ${MAX_QUESTIONS} سؤال` };
  }

  // Validate each question
  for (let i = 0; i < questions.length; i++) {
    const q = questions[i];

    if (!q || typeof q !== "object") {
      return { valid: false, error: `السؤال ${i + 1} غير صحيح` };
    }

    if (!q.question || typeof q.question !== "string" || q.question.trim().length === 0) {
      return { valid: false, error: `السؤال ${i + 1} فارغ` };
    }

    if (q.question.length > MAX_QUESTION_LENGTH) {
      return { valid: false, error: `السؤال ${i + 1} طويل جداً (الحد الأقصى ${MAX_QUESTION_LENGTH} حرف)` };
    }

    const options = ["optionA", "optionB", "optionC", "optionD"];
    const filledOptions = options.filter((opt) => q[opt] && q[opt].trim().length > 0);

    if (filledOptions.length < MIN_OPTIONS) {
      return { valid: false, error: `السؤال ${i + 1} يجب أن يحتوي على خيارين على الأقل` };
    }

    for (const opt of filledOptions) {
      if (!q[opt] || typeof q[opt] !== "string") {
        return { valid: false, error: `السؤال ${i + 1} يحتوي على خيار غير صحيح` };
      }

      if (q[opt].trim().length === 0) {
        return { valid: false, error: `السؤال ${i + 1} يحتوي على خيار فارغ` };
      }

      if (q[opt].length > MAX_OPTION_LENGTH) {
        return { valid: false, error: `خيار في السؤال ${i + 1} طويل جداً (الحد الأقصى ${MAX_OPTION_LENGTH} حرف)` };
      }
    }

    if (!q.correctAnswer || typeof q.correctAnswer !== "string") {
      return { valid: false, error: `السؤال ${i + 1} لا يحتوي على إجابة صحيحة` };
    }

    const correctOption = `option${q.correctAnswer}`;
    if (!options.includes(correctOption) || !q[correctOption] || q[correctOption].trim().length === 0) {
      return { valid: false, error: `السؤال ${i + 1} يحتوي على إجابة صحيحة غير موجودة` };
    }
  }

  return { valid: true };
}

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
    if (!session || session.role !== "teacher") {
      return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
    }

    const { id: folderId } = await params;
    const { title, questions, timeLimitMinutes } = await req.json();

    // Validate quiz data
    const validation = validateQuizData(title, questions);
    if (!validation.valid) {
      return NextResponse.json({ error: validation.error }, { status: 400 });
    }

    // Verify folder exists and belongs to teacher
    const folder = await prisma.folder.findFirst({
      where: {
        id: folderId,
        course: { teacherId: session.id },
      },
    });

    if (!folder) {
      return NextResponse.json({ error: "المحاضرة غير موجودة" }, { status: 404 });
    }

    // Validate and normalize time limit
    const parsedLimit = Number(timeLimitMinutes);
    const normalizedLimit =
      Number.isFinite(parsedLimit) && parsedLimit >= MIN_TIME_LIMIT
        ? Math.min(Math.round(parsedLimit), MAX_TIME_LIMIT)
        : 30;

    // Create quiz with validated data
    const quiz = await prisma.quiz.create({
      data: {
        title: title.trim(),
        folderId,
        timeLimitMinutes: normalizedLimit,
        questions: {
          create: questions.map(
            (
              q: {
                question: string;
                optionA: string;
                optionB: string;
                optionC: string;
                optionD: string;
                correctAnswer: string;
              },
              i: number
            ) => ({
              question: q.question.trim(),
              optionA: q.optionA?.trim() || "",
              optionB: q.optionB?.trim() || "",
              optionC: q.optionC?.trim() || "",
              optionD: q.optionD?.trim() || "",
              correctAnswer: q.correctAnswer,
              order: i,
            })
          ),
        },
      },
      include: { questions: true },
    });

    return NextResponse.json({ quiz }, { status: 201 });
  } catch (error) {
    console.error("Failed to create quiz:", error);
    return NextResponse.json({ error: "تعذر إنشاء الاختبار" }, { status: 500 });
  }
}

import { logAdminAction } from "@/lib/admin-auth";
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { validateProviderId, type VideoProvider } from "@/lib/video-provider";
import { parsePublishAt } from "@/lib/publish";
import { getConfigNumber, getConfigNumberClamped } from "@/lib/config";
import { triggerPlanSyncForCourse } from "@/lib/plan-lesson-matcher";

const MAX_TITLE_LENGTH = 100;
const VALID_PROVIDERS: VideoProvider[] = ["vdocipher", "bunny", "youtube"];

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
    if (!session || session.role !== "teacher") {
      return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
    }

    const { id: folderId } = await params;
    const body = (await req.json()) as {
      title?: string;
      videoProvider?: string;
      providerVideoId?: string;
      durationMinutes?: number;
      maxWatchesPerUser?: number;
      publishAt?: string | null;
      // Legacy field — accepted for backwards compat, treated as vdocipher
      vdoCipherId?: string;
    };

    const durationMinutes =
      typeof body.durationMinutes === "number" && body.durationMinutes >= 0
        ? Math.floor(body.durationMinutes)
        : 0;

    // Default watch quota for new videos is superadmin-configurable (was 3).
    const maxWatchesPerUser =
      typeof body.maxWatchesPerUser === "number" && body.maxWatchesPerUser >= 1
        ? Math.floor(body.maxWatchesPerUser)
        : await getConfigNumberClamped("default_max_watches", 1, 99);

    const { title } = body;

    // Resolve provider + id (support legacy vdoCipherId field)
    const videoProvider: VideoProvider = VALID_PROVIDERS.includes(body.videoProvider as VideoProvider)
      ? (body.videoProvider as VideoProvider)
      : "vdocipher";

    const providerVideoId = (body.providerVideoId ?? body.vdoCipherId ?? "").trim();

    if (!title || typeof title !== "string" || !title.trim()) {
      return NextResponse.json({ error: "عنوان الفيديو مطلوب" }, { status: 400 });
    }
    if (title.length > MAX_TITLE_LENGTH) {
      return NextResponse.json(
        { error: `عنوان الفيديو لا يمكن أن يزيد عن ${MAX_TITLE_LENGTH} حرف` },
        { status: 400 }
      );
    }

    const idError = validateProviderId(videoProvider, providerVideoId);
    if (idError) {
      return NextResponse.json({ error: idError }, { status: 400 });
    }

    // Verify folder exists and belongs to teacher's course
    const folder = await prisma.folder.findFirst({
      where: { id: folderId, course: { teacherId: session.id } },
      include: { course: { select: { id: true } } }
    });
    if (!folder) {
      return NextResponse.json({ error: "المحاضرة غير موجودة" }, { status: 404 });
    }

    // Check for duplicate title in same folder
    const existing = await prisma.video.findFirst({ where: { folderId, title: title.trim() } });
    if (existing) {
      return NextResponse.json({ error: "يوجد فيديو بنفس العنوان في هذه المحاضرة" }, { status: 400 });
    }

    const count = await prisma.video.count({ where: { folderId } });

    // Enforce the superadmin-configurable max videos per folder.
    const maxPerFolder = await getConfigNumber("max_videos_per_folder");
    if (maxPerFolder > 0 && count >= maxPerFolder) {
      return NextResponse.json(
        { error: `لا يمكن إضافة أكثر من ${maxPerFolder} فيديو في المحاضرة الواحدة` },
        { status: 400 }
      );
    }

    const publishAt = parsePublishAt(body.publishAt) ?? null;

    const video = await prisma.video.create({
      data: {
        title: title.trim(),
        videoProvider,
        providerVideoId,
        vdoCipherId: videoProvider === "vdocipher" ? providerVideoId : "",
        durationMinutes,
        maxWatchesPerUser,
        publishAt,
        folderId,
        order: count,
      },
    });

    // Fire and forget auto-matcher sync
    triggerPlanSyncForCourse(folder.course.id).catch(console.error);

    return NextResponse.json({ video }, { status: 201 });
  } catch (error) {
    console.error("Failed to create video:", error);
    return NextResponse.json({ error: "تعذر إضافة الفيديو" }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
