/** POST — generate money codes (superadmin only) */
export async function POST(req: NextRequest) {
  const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
  if (!session || session.role !== "superadmin") return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  const body = await req.json() as { amount: number; count?: number; expiresAt?: string; prefix?: string };
  const { amount, count = 1, expiresAt, prefix = "CODEUP" } = body;

  if (!amount || amount <= 0) return NextResponse.json({ error: "المبلغ يجب أن يكون أكبر من صفر" }, { status: 400 });
  if (count < 1 || count > 100) return NextResponse.json({ error: "العدد يجب بين 1 و 100" }, { status: 400 });

  const codes: string[] = [];
  for (let i = 0; i < count; i++) {
    let code: string;
    // Ensure uniqueness
    do { code = generateCode(prefix); } while (await prisma.moneyCode.findUnique({ where: { code }, select: { id: true } }));
    codes.push(code);
  }

  const created = await prisma.moneyCode.createMany({
    data: codes.map(code => ({
      code,
      amount,
      expiresAt: expiresAt ? new Date(expiresAt) : null,
    })),
  });

  return NextResponse.json({ success: true, count: created.count, codes });
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
  const session = await getSession();
  if (!session || (session.role !== "superadmin" && session.role !== "teacher")) {
    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
  }

  const { searchParams } = new URL(req.url);
  const status = searchParams.get("status") || undefined;
  const page = Math.max(1, Number(searchParams.get("page")) || 1);
  const limit = Math.max(1, Math.min(100, Number(searchParams.get("limit")) || 20));

  try {
    const where: any = {};
    if (status) {
      where.status = status;
    }

    if (session.role === "teacher") {
      const teacherLessons = await prisma.planLessonSource.findMany({
        where: { teacherId: session.id },
        select: { planLessonId: true }
      });
      where.planLessonId = { in: teacherLessons.map(t => t.planLessonId) };
    }

    const submissions = await prisma.planProjectSubmission.findMany({
      where,
      include: {
        student: { select: { id: true, name: true, email: true } },
        enrollment: {
          select: {
            progress: {
              select: {
                planLessonId: true,
                chosenSourceId: true,
              }
            }
          }
        }
      },
      orderBy: { submittedAt: "desc" }
    });

    const planLessonIds = submissions.map(s => s.planLessonId);
    const lessons = await prisma.planLesson.findMany({
      where: { id: { in: planLessonIds } },
      select: {
        id: true,
        title: true,
        sources: {
          select: {
            id: true,
            teacherId: true,
          }
        }
      }
    });

    const lessonMap = new Map(lessons.map(l => [l.id, l]));

    // Scoped filtering for teachers
    let filteredSubmissions = submissions.map(sub => {
      const lesson = lessonMap.get(sub.planLessonId);
      return {
        ...sub,
        planLesson: lesson ? {
          title: lesson.title,
          sources: lesson.sources
        } : null
      };
    });

    if (session.role === "teacher") {
      filteredSubmissions = filteredSubmissions.filter(sub => {
        if (!sub.planLesson) return false;
        const progress = sub.enrollment.progress.find((p: any) => p.planLessonId === sub.planLessonId);
        const teacherSources = sub.planLesson.sources.filter((s: any) => s.teacherId === session.id);
        const teacherSourceIds = new Set(teacherSources.map((s: any) => s.id));
        
        if (progress?.chosenSourceId) {
          return teacherSourceIds.has(progress.chosenSourceId);
        }
        return teacherSources.length > 0;
      });
    }

    // In-memory pagination
    const total = filteredSubmissions.length;
    const paginated = filteredSubmissions.slice((page - 1) * limit, page * limit);

    return NextResponse.json({
      submissions: paginated,
      total,
      page,
      limit
    });
  } catch (error) {
    console.error("Failed to fetch submissions:", error);
    return NextResponse.json({ error: "تعذر جلب التقييمات" }, { status: 500 });
  }
}

import { logAdminAction } from "@/lib/admin-auth";
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { slugify, isValidSlug } from "@/lib/slug";

async function uniqueSlug(name: string, teacherId: string): Promise<string> {
  let base = slugify(name);
  if (!isValidSlug(base)) base = "teacher";
  let candidate = base;
  let n = 2;
  // Find a free slug (ignore the teacher's own row).
  while (true) {
    const taken = await prisma.teacherProfile.findFirst({
      where: { slug: candidate, NOT: { teacherId } },
      select: { id: true },
    });
    if (!taken) return candidate;
    candidate = `${base}-${n++}`;
  }
}

const EDITABLE = [
  "displayName", "bio", "photoUrl", "bannerUrl", "navColor", "accentColor", "socials",
  "featuredCourseId", "priceMonthly", "priceTermly", "priceYearly", "discountMonthly",
  "discountTermly", "discountYearly", "courseStartDate", "bookingContactUrl",
  "bookingEnabled", "arabicEnabled", "languagesEnabled",
  "priceMonthly1", "priceMonthly3", "priceMonthly6",
  "originalMonthly3", "originalMonthly6",
  "langSurcharge1", "langSurcharge3", "langSurcharge6",
  "enableMonthly1", "enableMonthly3", "enableMonthly6",
] as const;

export async function GET() {
  try {
    const session = await getSession();
    if (!session || session.role !== "teacher") {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    let profile = await prisma.teacherProfile.findUnique({ where: { teacherId: session.id } });
    if (!profile) {
      profile = await prisma.teacherProfile.create({
        data: { teacherId: session.id, slug: await uniqueSlug(session.name, session.id), displayName: session.name },
      });
    }
    return NextResponse.json({ profile });
  } catch (error) {
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

export async function PUT(req: NextRequest) {
  try {
    const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
    if (!session || session.role !== "teacher") {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const body = (await req.json()) as Record<string, unknown>;
    const data: Record<string, unknown> = {};

    for (const k of EDITABLE) {
      if (k in body) data[k] = body[k];
    }
    if (typeof body.isPublished === "boolean") data.isPublished = body.isPublished;

    if (typeof body.slug === "string" && body.slug.trim()) {
      const s = slugify(body.slug);
      if (!isValidSlug(s)) {
        return NextResponse.json({ error: "الرابط غير صالح أو محجوز" }, { status: 400 });
      }
      const taken = await prisma.teacherProfile.findFirst({
        where: { slug: s, NOT: { teacherId: session.id } },
        select: { id: true },
      });
      if (taken) return NextResponse.json({ error: "الرابط مستخدم بالفعل" }, { status: 409 });
      data.slug = s;
    }

    // Ensure a row exists (create-on-write).
    const existing = await prisma.teacherProfile.findUnique({ where: { teacherId: session.id } });
    const profile = existing
      ? await prisma.teacherProfile.update({ where: { teacherId: session.id }, data })
      : await prisma.teacherProfile.create({
          data: { teacherId: session.id, slug: (data.slug as string) || (await uniqueSlug(session.name, session.id)), ...data },
        });

    return NextResponse.json({ profile });
  } catch (error) {
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

