          targetName: req.method,
        });
      } catch (e) {}
    }
  if (!session || !isAdminRole(session.role)) {
    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
  }
  const body = (await req.json().catch(() => ({}))) as { maxDevices?: number };
  const n = Number(body.maxDevices);
  if (!Number.isFinite(n) || n < MIN_DEVICES || n > MAX_DEVICES) {
    return NextResponse.json({ error: `عدد الأجهزة يجب أن يكون بين ${MIN_DEVICES} و ${MAX_DEVICES}` }, { status: 400 });
  }
  const maxDevices = await setStudentMaxDevices(n);
  return NextResponse.json({ maxDevices });
} catch (error) {
    console.error("[admin/superadmin/settings/max-devices] error:", error);
    return NextResponse.json(
      { error: "حدث خطأ داخلي" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { verifyRoleActionPassword, logAdminAction } from "@/lib/admin-auth";
import {
  getSiteText,
  setSiteText,
  SITE_TEXT_DEFAULTS,
  SITE_TEXT_LABELS,
} from "@/lib/site-text";

async function requireSuperadmin() {
  const session = await getSession();
  if (!session || session.role !== "superadmin") return null;
  return session;
}

export async function GET() {
  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  const text = await getSiteText();
  return NextResponse.json({ text, defaults: SITE_TEXT_DEFAULTS, labels: SITE_TEXT_LABELS });
}

export async function POST(req: NextRequest) {
    const __logSession = await getSession();
    if (__logSession && __logSession.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: __logSession.id,
          adminName: __logSession.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }

  const session = await requireSuperadmin();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  try {
    const body = (await req.json().catch(() => ({}))) as {
      updates?: Record<string, string>;
      actionPassword?: string;
    };

    if (!verifyRoleActionPassword(session.role, body.actionPassword ?? "")) {
      return NextResponse.json({ error: "كلمة مرور المشرف غير صحيحة" }, { status: 401 });
    }
    if (!body.updates || typeof body.updates !== "object") {
      return NextResponse.json({ error: "لا توجد تغييرات" }, { status: 400 });
    }

    const keys = Object.keys(body.updates).filter((k) => k in SITE_TEXT_DEFAULTS);
    for (const k of keys) {
      await setSiteText(k, body.updates[k]);
    }

    await logAdminAction({
      adminId: session.id,
      adminName: session.name,
      action: "EDIT_SITE_TEXT",
      targetType: "system",
      targetId: "site-text",
      targetName: "نصوص الموقع",
      metadata: { keys },
    });

    const text = await getSiteText();
    return NextResponse.json({ success: true, text });
  } catch (error) {
    console.error("Site-text update error:", error);
    return NextResponse.json({ error: "تعذر حفظ النصوص" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { hasPermission } from "@/lib/rbac";
import { logAdminAction, LOG_ACTIONS, verifyRoleActionPassword } from "@/lib/admin-auth";

type Ctx = { params: Promise<{ id: string }> };

// PATCH /api/admin/superadmin/staff-accounts/[id]
// actions: "toggle_active" | "reset_password"
export async function PATCH(req: NextRequest, ctx: Ctx) {
  try {
    const session = await getSession();

    if (session && session.role === "superadmin") {
      try {
        await logAdminAction({
          adminId: session.id,
          adminName: session.name,
          action: "SUPERADMIN_ACTION",
          targetType: "API_ROUTE",
          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
          targetName: req.method,
        });
      } catch (e) {}
    }
    if (!session || !hasPermission(session.role, "manage_staff_accounts")) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
    }

    const { id } = await ctx.params;
    const body = (await req.json()) as {
      action?: string;
      newPassword?: string;
      actionPassword?: string;
    };

    const { action = "", newPassword = "", actionPassword = "" } = body;

    if (!verifyRoleActionPassword(session.role, actionPassword)) {
      return NextResponse.json({ error: "كلمة مرور الإجراء غير صحيحة" }, { status: 403 });
    }

    const target = await prisma.user.findFirst({
      where: { id, role: { in: ["admin", "staff"] }, isDeleted: false },
    });
    if (!target) {
      return NextResponse.json({ error: "الحساب غير موجود" }, { status: 404 });
    }

    if (action === "toggle_active") {
      const nowActive = !target.isActive;
      await prisma.user.update({ where: { id }, data: { isActive: nowActive } });
      await logAdminAction({
        adminId: session.id,
        adminName: session.name,
        action: nowActive
          ? LOG_ACTIONS.UNSUSPEND_STAFF_ACCOUNT
          : LOG_ACTIONS.SUSPEND_STAFF_ACCOUNT,
        targetType: "StaffAccount",
        targetId: id,
        targetName: target.name,
        metadata: { role: target.role, isActive: nowActive },
      });
      return NextResponse.json({ isActive: nowActive });
    }

    if (action === "reset_password") {
      if (!newPassword || newPassword.length < 6) {
        return NextResponse.json({ error: "كلمة المرور يجب أن تكون 6 أحرف على الأقل" }, { status: 400 });
      }
      const hashed = await bcrypt.hash(newPassword, 12);
      await prisma.user.update({ where: { id }, data: { password: hashed } });
      await logAdminAction({
        adminId: session.id,
        adminName: session.name,
        action: LOG_ACTIONS.RESET_STAFF_PASSWORD,
        targetType: "StaffAccount",
        targetId: id,
        targetName: target.name,
        metadata: { role: target.role },
      });
      return NextResponse.json({ ok: true });
    }

    return NextResponse.json({ error: "إجراء غير معروف" }, { status: 400 });
  } catch (err) {
    console.error("PATCH staff-accounts/[id] error:", err);
    return NextResponse.json({ error: "حدث خطأ في الخادم" }, { status: 500 });
  }
}

