}

/** Authenticated deletion only — never via chat message text. */
export async function DELETE() {
  try {
    const session = (await getStudentSession()) ?? (await getSession());
    if (!session) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    await prisma.aIConversation.deleteMany({
      where: { studentId: session.id },
    });

    try {
      const { MemoryManager } = await import("@/ai/memory/MemoryManager");
      MemoryManager.getInstance().clearSession(session.id);
    } catch {
      // Memory manager is optional; DB wipe is the source of truth.
    }

    return NextResponse.json({
      success: true,
      message: "تم مسح المحادثة وحذف السجل بالكامل",
    });
  } catch {
    console.error("[chat/route] delete error");
    return NextResponse.json(
      { error: "حدث خطأ أثناء مسح المحادثة" },
      { status: 500 },
    );
  }
}

async function executeAction(
  studentId: string,
  action: AIAction,
): Promise<{ type: string; status: string; id?: string; error?: string }> {
  try {
    switch (action.type) {
      case "create_grade_request": {
        const p = action.payload as {
          quizId: string;
          reason: string;
          requestedScore?: number;
          evidence?: string;
        };
        if (!p?.quizId || !p?.reason) {
          return { type: action.type, status: "failed", error: "بيانات ناقصة" };
        }

        const result = await prisma.quizResult.findFirst({
          where: { quizId: p.quizId, studentId },
          include: {
            quiz: {
              include: {
                folder: { select: { courseId: true } },
              },
            },
          },
        });

        if (!result) {
          return {
            type: action.type,
            status: "failed",
            error: "لم يتم حل هذا الكويز",
          };
        }

        const req = await prisma.gradeAdjustmentRequest.create({
          data: {
            studentId,
            quizId: p.quizId,
            courseId: result.quiz.folder?.courseId ?? "plan",
            requestedBy: "student",
            currentScore: result.score,
            requestedScore: p.requestedScore ?? null,
            reason: p.reason,
            aiAnalysis:
              "تم إنشاء الطلب بواسطة المساعد الذكي بناءً على شكوى المتعلم",
            evidence: null,
            status: "pending",
          },
        });

        return { type: action.type, status: "created", id: req.id };
      }

      case "create_ticket": {
        const p = action.payload as {
          title: string;
          description: string;
          type: string;
          priority?: string;
          courseId?: string;
        };
        if (!p?.title || !p?.description) {
          return { type: action.type, status: "failed", error: "بيانات ناقصة" };
        }

        if (p.courseId) {
          const { checkCourseEnrollment } = await import("@/lib/authorization");
          const isEnrolled = await checkCourseEnrollment(studentId, p.courseId);
          if (!isEnrolled) {
            return {
              type: action.type,
              status: "failed",
              error: "غير مسجل في هذا الكورس",
            };
          }
        }

        const ticket = await prisma.supportTicket.create({
          data: {
            studentId,
            courseId: p.courseId ?? null,
            title: p.title,
            description: p.description,
            type: p.type || "complaint",
            priority: p.priority || "normal",
            aiHandled: true,
            aiResponse: null,
            status: "open",
          },
        });

        return { type: action.type, status: "created", id: ticket.id };
      }

      case "submit_feedback": {
        const p = action.payload as {
          courseId: string;
          type: string;
          content: string;
          rating?: number;
        };
        if (!p?.courseId || !p?.content) {
          return { type: action.type, status: "failed", error: "بيانات ناقصة" };
        }

        const { checkCourseEnrollment } = await import("@/lib/authorization");
        const isEnrolled = await checkCourseEnrollment(studentId, p.courseId);
        if (!isEnrolled) {
          return {
            type: action.type,
            status: "failed",
            error: "غير مسجل في هذا الكورس",
          };
        }

        const course = await prisma.course.findUnique({
          where: { id: p.courseId },
          select: { teacherId: true },
        });
        if (!course) {
          return {
            type: action.type,
            status: "failed",
            error: "الكورس غير موجود",
          };
        }

        const fb = await prisma.studentFeedback.create({
          data: {
            studentId,
            courseId: p.courseId,
            teacherId: course.teacherId,
            type: p.type || "other",
            content: p.content,
            rating: p.rating ?? null,
            aiAnalyzed: true,
          },
        });

        return { type: action.type, status: "created", id: fb.id };
      }

      case "navigate":
      case "show_insights":
      case "none":
        return { type: action.type, status: "ok" };

      default:
        return { type: "unknown", status: "ignored" };
    }
  } catch {
    console.error("[chat/route] action execution error");
    return {
      type: action.type,
      status: "failed",
      error: "خطأ غير معروف",
    };
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth";

const ROLE_MESSAGES: Record<string, string> = {
  teacher: "حساب المعلم لا يمكنه تفعيل أكواد الكورسات — هذا الإجراء مخصص للمتعلمين فقط.",
  staff:   "حساب الموظف لا يمكنه تفعيل أكواد الكورسات — هذا الإجراء مخصص للمتعلمين فقط.",
};

export async function POST(req: NextRequest) {
  try {
    const session = await getSession();

    if (!session) {
      return NextResponse.json({ error: "يجب تسجيل الدخول أولاً" }, { status: 401 });
    }

    // Teacher and staff are blocked — admins and superadmins are allowed through
    if (session.role === "teacher" || session.role === "staff") {
      return NextResponse.json(
        { error: ROLE_MESSAGES[session.role] },
        { status: 403 }
      );
    }

    const { code } = await req.json();
    if (!code) return NextResponse.json({ error: "الكود مطلوب" }, { status: 400 });

    const clientIp = req.headers.get("x-forwarded-for")?.split(",")[0] || "127.0.0.1";
    const { AccessCodeGuard } = await import("@/services/security/AccessCodeGuard");
    const { ReferralService } = await import("@/services/referral/ReferralService");

    // Enforce exponential rate limiting
    const rateCheck = await AccessCodeGuard.verifyRateLimit(clientIp, session.id);
    if (!rateCheck.allowed) {
      await AccessCodeGuard.logAttempt({ ip: clientIp, userId: session.id, codeAttempted: String(code), success: false });
      return NextResponse.json(
        { error: `تم تجاوز عدد محاولات الكود المسموح بها. يرجى الانتظار ${rateCheck.lockTimeSeconds} ثانية قبل المحاولة مجدداً.` },
        { status: 429 }
      );
    }

    const normalizedCode = String(code).trim().toUpperCase();
    
    // Check Course Access Code
    const accessCode = await prisma.accessCode.findUnique({ where: { code: normalizedCode } });
    if (accessCode) {
      if (accessCode.studentId) {
        await AccessCodeGuard.logAttempt({ ip: clientIp, userId: session.id, codeAttempted: normalizedCode, success: false });
        return NextResponse.json({ error: "هذا الكود مستخدم بالفعل" }, { status: 400 });
      }
      if (!accessCode.isActive) {
        await AccessCodeGuard.logAttempt({ ip: clientIp, userId: session.id, codeAttempted: normalizedCode, success: false });
        return NextResponse.json({ error: "هذا الكود غير فعال" }, { status: 400 });
      }

      try {
        const result = await prisma.$transaction(async (tx) => {
          const alreadyEnrolled = await tx.accessCode.findFirst({
            where: { courseId: accessCode.courseId, studentId: session.id },
          });
          if (alreadyEnrolled) {
            return {
              alreadyEnrolled: true,
              courseId: accessCode.courseId,
              message: "أنت مسجل بالفعل في هذا الكورس",
            };
          }

          const updateResult = await tx.accessCode.updateMany({
            where: { id: accessCode.id, studentId: null, isActive: true },
            data: { studentId: session.id, usedAt: new Date() },
          });

          if (updateResult.count === 0) {
            throw new Error("ALREADY_USED_OR_INACTIVE");
          }

          const course = await tx.course.findUnique({
            where: { id: accessCode.courseId },
            select: { id: true, title: true },
          });

          return {
            alreadyEnrolled: false,
            courseId: accessCode.courseId,
            courseTitle: course?.title,
          };
        });

        if (result.alreadyEnrolled) {
          return NextResponse.json({
            success: true,
            courseId: result.courseId,
            message: result.message,
          });
        }

        // Log successful redemption
        await AccessCodeGuard.logAttempt({ ip: clientIp, userId: session.id, codeAttempted: normalizedCode, success: true });

        // Qualify student referral upon redeeming valid paid course code
        void ReferralService.qualifyAndRewardReferral(session.id, accessCode.id).catch(() => {});

        return NextResponse.json({
          success: true,
          type: "course",
          courseId: result.courseId,
          courseTitle: result.courseTitle,
          message: "تم تفعيل الكود وإضافة الكورس إلى مكتبتك",
        });
      } catch (err: any) {
        await AccessCodeGuard.logAttempt({ ip: clientIp, userId: session.id, codeAttempted: normalizedCode, success: false });
        if (err.message === "ALREADY_USED_OR_INACTIVE") {
          return NextResponse.json({ error: "هذا الكود مستخدم بالفعل أو غير فعال" }, { status: 400 });
        }
        throw err;
      }
    }

    // Check Plan Access Code
    const planCode = await prisma.planAccessCode.findUnique({ where: { code: normalizedCode } });
    if (planCode) {
      if (planCode.usedById) {
        return NextResponse.json({ error: "هذا الكود مستخدم بالفعل" }, { status: 400 });
      }
      if (!planCode.isActive) {
        return NextResponse.json({ error: "هذا الكود غير فعال" }, { status: 400 });
      }

      try {
        const result = await prisma.$transaction(async (tx) => {
          const student = await tx.user.findUnique({
            where: { id: session.id },
            select: { educationalStage: true }
          });

          const plan = await tx.plan.findUnique({ 
            where: { id: planCode.planId }, 
            select: { id: true, title: true, durationDays: true, educationalStage: true } 
          });

          if (!plan) throw new Error("PLAN_NOT_FOUND");

          if (student?.educationalStage && plan.educationalStage && student.educationalStage !== plan.educationalStage) {
            throw new Error("STAGE_MISMATCH");
          }

          const alreadyEnrolled = await tx.planEnrollment.findUnique({
            where: { planId_studentId: { planId: planCode.planId, studentId: session.id } },
          });

          const now = new Date();

          if (alreadyEnrolled) {
            const isExpired = alreadyEnrolled.expiresAt < now;
            if (isExpired) {
              const updateResult = await tx.planAccessCode.updateMany({
                where: { id: planCode.id, usedById: null, isActive: true },
                data: { usedById: session.id, usedAt: now, isActive: false },
              });
              if (updateResult.count === 0) {
                throw new Error("ALREADY_USED_OR_INACTIVE");
              }

              const durationDays = plan.durationDays ?? 365;
              await tx.planEnrollment.update({
                where: { id: alreadyEnrolled.id },
                data: {
                  unlockedAt: now,
                  expiresAt: new Date(now.getTime() + durationDays * 24 * 60 * 60 * 1000),
                  pricePaid: 0,
                }
              });

              return {
                renewed: true,
                planId: planCode.planId,
                planTitle: plan.title,
              };
            }

            return {
              alreadyEnrolled: true,
              planId: planCode.planId,
            };
          }

          const updateResult = await tx.planAccessCode.updateMany({
            where: { id: planCode.id, usedById: null, isActive: true },
            data: { usedById: session.id, usedAt: now, isActive: false },
          });
          if (updateResult.count === 0) {
            throw new Error("ALREADY_USED_OR_INACTIVE");
          }

          const durationDays = plan.durationDays ?? 365;
          await tx.planEnrollment.create({
            data: {
              planId: planCode.planId,
              studentId: session.id,
              pricePaid: 0,
              expiresAt: new Date(now.getTime() + durationDays * 24 * 60 * 60 * 1000),
            }
          });

          return {
            renewed: false,
            planId: planCode.planId,
            planTitle: plan.title,
          };
        });

        if (result.alreadyEnrolled) {
          return NextResponse.json({
            success: true,
            planId: result.planId,
            message: "أنت مسجل بالفعل في هذه الخطة",
          });
        }

        if (result.renewed) {
          return NextResponse.json({
            success: true,
            type: "plan",
            planId: result.planId,
            planTitle: result.planTitle,
            message: "تم تجديد اشتراكك في هذه الخطة بنجاح وتفعيل المحتوى",
          });
        }

        return NextResponse.json({
          success: true,
          type: "plan",
          planId: result.planId,
          planTitle: result.planTitle,
          message: "تم تفعيل الكود وإضافة الخطة إلى مكتبتك",
        });
      } catch (err: any) {
        if (err.message === "PLAN_NOT_FOUND") return NextResponse.json({ error: "الخطة غير موجودة" }, { status: 404 });
        if (err.message === "STAGE_MISMATCH") return NextResponse.json({ error: "هذا الكود مخصص لمرحلة دراسية مختلفة" }, { status: 400 });
        if (err.message === "ALREADY_USED_OR_INACTIVE") return NextResponse.json({ error: "هذا الكود مستخدم بالفعل أو غير فعال" }, { status: 400 });
        throw err;
      }
    }

    // Check Teacher Promo Code
    const teacher = await prisma.user.findFirst({
      where: {
        role: "teacher",
        promoProgramEnabled: true,
        promoCode: normalizedCode,
      },
      select: { id: true, name: true, promoCode: true, promoCodeCreatedAt: true },
    });

    if (teacher && teacher.promoCodeCreatedAt) {
      const now = new Date();
      const isWithin350Days = now.getTime() - teacher.promoCodeCreatedAt.getTime() <= 350 * 24 * 60 * 60 * 1000;

      if (!isWithin350Days) {
        return NextResponse.json({ error: "كود الخصم هذا منتهي الصلاحية" }, { status: 400 });
      }

      // Link student's referredByTeacherId
      await prisma.user.update({
        where: { id: session.id },
        data: { referredByTeacherId: teacher.id },
      });

      // Record initial signup/referral link attribution if not existing
      const existing = await prisma.teacherReferralAttribution.findFirst({
        where: { teacherId: teacher.id, studentId: session.id, purchaseType: "SIGNUP" },
      });

      if (!existing) {
        await prisma.teacherReferralAttribution.create({
          data: {
            teacherId: teacher.id,
            studentId: session.id,
            purchaseType: "SIGNUP",
            amount: 0,
            promoCodeUsed: teacher.promoCode,
          },
        });
      }

      return NextResponse.json({
        success: true,
        type: "teacher_promo",
        teacherName: teacher.name,
        message: `تم ربط حسابك بكود المعلم أ/ ${teacher.name} بنجاح!`,
      });
    }

    return NextResponse.json({ error: "الكود غير صحيح" }, { status: 404 });
  } catch (error) {
    console.error("[codes] error:", error);
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { randomBytes } from "crypto";

import { acquireAdvisoryLock } from "@/lib/distributed-lock";

import { processTeacherAttribution } from "@/lib/referral";

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "يجب تسجيل الدخول أولاً" }, { status: 401 });
  if (session.role === "teacher" || session.role === "staff") {
    return NextResponse.json({ error: "هذا الإجراء مخصص للمتعلمين فقط" }, { status: 403 });
  }

  const { id: courseId } = await params;
  const reqBody = await req.json().catch(() => ({}));
  const promoCodeInput = reqBody.promoCode || reqBody.promo_code;

  const course = await prisma.course.findUnique({
    where: { id: courseId },
    select: { id: true, title: true, teacherId: true, isPaid: true, price: true, discountPercent: true, discountExpiresAt: true },
  });
  if (!course) return NextResponse.json({ error: "الكورس غير موجود" }, { status: 404 });

  // Calculate effective price
  const now = new Date();
  const discountActive =
    course.discountPercent != null &&
    course.discountPercent > 0 &&
    (course.discountExpiresAt == null || course.discountExpiresAt > now);

  const effectivePrice = (() => {
    if (!course.isPaid || !course.price) return 0;
    if (discountActive && course.discountPercent) {
      return +(course.price * (1 - course.discountPercent / 100)).toFixed(2);
    }
    return course.price;
  })();

  if (effectivePrice === 0) {
    return NextResponse.json({ error: "هذا الكورس مجاني — استخدم زر التسجيل المباشر" }, { status: 400 });
  }

  const code = `PAY-${Date.now().toString(36).toUpperCase()}-${randomBytes(3).toString("hex").toUpperCase()}`;

  try {
    const purchaseResult = await prisma.$transaction(async (tx) => {
      // 1. Acquire advisory lock on student wallet
      await acquireAdvisoryLock(`purchase-course-${session.id}`, tx);

      // 2. Check already enrolled inside the transaction
      const existing = await tx.accessCode.findFirst({
        where: { courseId, studentId: session.id },
        select: { id: true },
      });
      if (existing) throw new Error("ALREADY_ENROLLED");

      // 3. Check balance inside the transaction
      const student = await tx.user.findUnique({
        where: { id: session.id },
        select: { balance: true },
      });
      if (!student) throw new Error("USER_NOT_FOUND");

      const currentBalance = student.balance ?? 0;
      if (currentBalance < effectivePrice) throw new Error("INSUFFICIENT_FUNDS");

      // 4. Update balance atomically using decrement
      await tx.user.update({
        where: { id: session.id },
        data: { balance: { decrement: effectivePrice } },
      });

      // 5. Create AccessCode
      await tx.accessCode.create({
        data: { code, courseId, studentId: session.id, isActive: true, usedAt: now },
      });

      // 6. Create BalanceTransaction
      await tx.balanceTransaction.create({
        data: {
          userId: session.id,
          type: "debit_course",
          amount: -effectivePrice,
          note: `شراء كورس: ${course.title}`,
        },
      });

      // 7. Process Teacher Referral Attribution
      await processTeacherAttribution({
        studentId: session.id,
        teacherIdOfContent: course.teacherId,
        amount: effectivePrice,
        purchaseType: "COURSE",
        courseId: course.id,
        promoCodeInput,
        tx,
      });

      return {
        newBalance: +(currentBalance - effectivePrice).toFixed(2),
      };
    });

    return NextResponse.json({
      success: true,
      courseId,
      courseTitle: course.title,
      charged: effectivePrice,
      newBalance: purchaseResult.newBalance,
      message: `تم شراء «${course.title}» بنجاح! خُصم ${effectivePrice} جنيه — رصيدك الآن ${purchaseResult.newBalance} جنيه.`,
    });
  } catch (err: any) {
    if (err.message === "ALREADY_ENROLLED") {
      return NextResponse.json({ error: "أنت مسجّل بالفعل في هذا الكورس" }, { status: 400 });
    }
    if (err.message === "USER_NOT_FOUND") {
      return NextResponse.json({ error: "المستخدم غير موجود" }, { status: 404 });
    }
    if (err.message === "INSUFFICIENT_FUNDS") {
      return NextResponse.json(
        { code: "INSUFFICIENT_FUNDS", error: "رصيدك غير كافٍ لإتمام العملية", effectivePrice },
        { status: 400 }
      );
    }
    throw err;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { acquireAdvisoryLock } from "@/lib/distributed-lock";

import { processTeacherAttribution } from "@/lib/referral";

/**
 * POST /api/folders/[id]/purchase
 * Student purchases access to a specific folder.
 * Deducts balance (or marks as free if folder.price === 0).
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSession();
  if (!session || session.role !== "student")
    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  const { id: folderId } = await params;
  const reqBody = await req.json().catch(() => ({}));
  const promoCodeInput = reqBody.promoCode || reqBody.promo_code;

  try {
    const purchase = await prisma.$transaction(async (tx) => {
      // Acquire transaction-scoped advisory lock to serialize purchases for the user
      await acquireAdvisoryLock(`purchase-folder-${session.id}`, tx);

      const folder = await tx.folder.findUnique({
        where: { id: folderId },
        include: { course: { select: { id: true, teacherId: true, title: true } } },
      });

      if (!folder) throw new Error("NOT_FOUND");

      if (!folder.isPurchasable) throw new Error("NOT_PURCHASABLE");

      // Prevent double purchase
      const existing = await tx.folderPurchase.findUnique({
        where: { studentId_folderId: { studentId: session.id, folderId } },
      });
      if (existing) throw new Error("ALREADY_OWNED");

      const price = folder.price ?? 0;

      if (price > 0) {
        const student = await tx.user.findUnique({
          where: { id: session.id },
          select: { balance: true },
        });
        if (!student || (student.balance ?? 0) < price) {
          throw new Error("INSUFFICIENT_BALANCE");
        }

        // Deduct balance atomically
        await tx.user.update({
          where: { id: session.id },
          data: { balance: { decrement: price } },
        });

        // Add ledger entry
        await tx.balanceTransaction.create({
          data: {
            userId: session.id,
            type: "debit_course",
            amount: -price,
            note: `شراء مجلد: ${folder.name}`,
          },
        });
      }

      // Create purchase record
      const res = await tx.folderPurchase.create({
        data: { studentId: session.id, folderId, price },
      });

      // Process Teacher Referral Attribution
      await processTeacherAttribution({
        studentId: session.id,
        teacherIdOfContent: folder.course.teacherId,
        amount: price,
        purchaseType: "FOLDER",
        folderId,
        courseId: folder.course.id,
        promoCodeInput,
        tx,
      });

      return res;
    });

    return NextResponse.json({ purchase, message: "تم شراء المجلد بنجاح" }, { status: 201 });
  } catch (error: any) {
    if (error.message === "NOT_FOUND") {
      return NextResponse.json({ error: "المجلد غير موجود" }, { status: 404 });
    }
    if (error.message === "NOT_PURCHASABLE") {
      return NextResponse.json(
        { error: "هذا المجلد غير متاح للشراء منفرداً — يمكنك شراء الكورس كاملاً بكود وصول" },
        { status: 403 }
      );
    }
    if (error.message === "ALREADY_OWNED") {
      return NextResponse.json({ error: "لقد اشتريت هذا المجلد بالفعل", alreadyOwned: true });
    }
    if (error.message === "INSUFFICIENT_BALANCE") {
      return NextResponse.json({ error: "رصيدك غير كافٍ" }, { status: 402 });
    }
