import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {

      try {
      const session = await getSession();
      if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });

      const { id: quizId } = await params;
      const quiz = await prisma.quiz.findUnique({
        where: { id: quizId },
        include: {
          questions: { orderBy: { order: "asc" } },
          folder: {
            select: {
              courseId: true,
              course: {
                select: { teacherId: true, title: true, subject: true },
              },
            },
          },
          planLesson: { select: { id: true, planId: true } },
        },
      });

      if (!quiz) return NextResponse.json({ error: "الاختبار غير موجود" }, { status: 404 });

      const canAccessAsTeacher = session.role === "teacher" && (
        quiz.folder?.course?.teacherId === session.id || quiz.planLessonId !== null
      );
      
      let canAccessAsStudent = false;
      if (quiz.folderId && quiz.folder) {
        const hasCourseAccess = await prisma.accessCode.findFirst({
          where: { courseId: quiz.folder.courseId, studentId: session.id, isActive: true },
          select: { id: true },
        });
        if (hasCourseAccess) canAccessAsStudent = true;
      } else if (quiz.planLessonId && quiz.planLesson) {
        const hasPlanAccess = await prisma.planEnrollment.findFirst({
          where: { planId: quiz.planLesson.planId, studentId: session.id, expiresAt: { gt: new Date() } },
          select: { id: true },
        });
        if (hasPlanAccess) canAccessAsStudent = true;
      }

      if (!canAccessAsTeacher && !canAccessAsStudent) {
        return NextResponse.json({ error: "لا يوجد صلاحية للوصول" }, { status: 403 });
      }

      const isStudent = session.role === "student";

      // Check if student already completed this quiz
      if (isStudent) {
        const existingResult = await prisma.quizResult.findUnique({
          where: { studentId_quizId: { studentId: session.id, quizId } },
        });
        if (existingResult) {
          if (!existingResult.allowRetake) {
            return NextResponse.json({
              alreadyCompleted: true,
              result: {
                score: existingResult.score,
                totalQ: existingResult.totalQ,
                completedAt: existingResult.completedAt,
              },
              quiz: { id: quiz.id, title: quiz.title, courseId: quiz.folder?.courseId ?? 'plan', course: quiz.folder?.course },
            });
          }

          // Retake is allowed — check cooldown
          const cooldownHours = (quiz as any).retakeCooldownHours ?? 0;
          if (cooldownHours > 0) {
            const cooldownMs = cooldownHours * 3_600_000;
            const elapsed    = Date.now() - new Date(existingResult.completedAt).getTime();
            if (elapsed < cooldownMs) {
              return NextResponse.json({
                alreadyCompleted: true,
                cooldownRemainingMs: cooldownMs - elapsed,
                result: {
                  score: existingResult.score,
                  totalQ: existingResult.totalQ,
                  completedAt: existingResult.completedAt,
                },
                quiz: { id: quiz.id, title: quiz.title, courseId: quiz.folder?.courseId ?? 'plan', course: quiz.folder?.course },
              });
            }
          }

          // Reset QuizResult for retake
          await prisma.quizResult.update({
            where: { id: existingResult.id },
            data: { startedAt: new Date(), allowRetake: false },
          });
        } else {
          // Create initial QuizResult with startedAt
          await prisma.quizResult.create({
            data: {
              studentId: session.id,
              quizId,
              score: 0,
              totalQ: 0,
              startedAt: new Date(),
              allowRetake: false,
            },
          });
        }
      }

      const questions = isStudent
        ? quiz.questions.map((question: any) => {
            const { correctAnswer: _ca, ...q } = question;
            return q;
          })
        : quiz.questions;

      return NextResponse.json({
        quiz: {
          id: quiz.id,
          title: quiz.title,
          timeLimitMinutes: (quiz as any).timeLimitMinutes,
          questions,
          folderId: quiz.folderId,
          courseId: quiz.folder?.courseId ?? 'plan',
          course: quiz.folder?.course,
        },
        timeLimitMinutes: (quiz as any).timeLimitMinutes,
      });
    } catch (error) {
        console.error("[quizzes/[id]] error:", error);
        return NextResponse.json(
          { error: "حدث خطأ داخلي" },
          { status: 500 }
        );
      }
}

import { NextRequest, NextResponse } from "next/server";
import { getStudentSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

/** GET — current balance + last 20 transactions */
export async function GET() {
  const { getSession } = await import("@/lib/auth");
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });

  const [user, rawTransactions] = await Promise.all([
    prisma.user.findUnique({ where: { id: session.id }, select: { balance: true } }),
    prisma.balanceTransaction.findMany({
      where: { userId: session.id },
      orderBy: { createdAt: "desc" },
      take: 50,
      select: { id: true, type: true, amount: true, note: true, createdAt: true },
    }),
  ]);

  const transactions = rawTransactions.map(tx => {
    const isPending = tx.type.toLowerCase().includes("pending");
    let url: string | null = null;
    let ref: string | null = null;
    
    if (tx.note) {
      const urlMatch = tx.note.match(/\|url:(https?:\/\/[^\s|]+)/);
      if (urlMatch) url = urlMatch[1];
      const refMatch = tx.note.match(/(?:shakeout_ref|sha7nawy_ref):([^\s|]+)/);
      if (refMatch) ref = refMatch[1];
    }

    return {
      id: tx.id,
      type: tx.type,
      amount: tx.amount,
      note: tx.note,
      createdAt: tx.createdAt,
      isPending,
      status: isPending ? "UNPAID" : "PAID",
      paymentUrl: url,
      reference: ref,
    };
  });

  return NextResponse.json(
    { balance: user?.balance ?? 0, transactions },
    { headers: { "Cache-Control": "no-store" } }
  );
}

/** POST — redeem a money code */
export async function POST(req: NextRequest) {
  const { getSession } = await import("@/lib/auth");
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });

  const { code } = await req.json() as { code?: string };
  if (!code?.trim()) return NextResponse.json({ error: "الكود مطلوب" }, { status: 400 });

  const normalized = code.trim().toUpperCase();

  try {
    const creditedAmount = await prisma.$transaction(async (tx) => {
      const moneyCode = await tx.moneyCode.findUnique({ where: { code: normalized } });
      if (!moneyCode) {
        throw new Error("NOT_FOUND");
      }
      if (moneyCode.isUsed) {
        throw new Error("ALREADY_USED");
      }
      if (moneyCode.expiresAt && moneyCode.expiresAt < new Date()) {
        throw new Error("EXPIRED");
      }

      // Mark used conditionally - ensures that if another request updated it between findUnique and now, this updates 0 rows
      const updateResult = await tx.moneyCode.updateMany({
        where: { id: moneyCode.id, isUsed: false },
        data: { isUsed: true, usedById: session.id, usedAt: new Date() },
      });

      if (updateResult.count === 0) {
        throw new Error("ALREADY_USED");
      }

      // Atomically increment user's balance
      await tx.user.update({
        where: { id: session.id },
        data: { balance: { increment: moneyCode.amount } },
      });

      // Create ledger entry
      await tx.balanceTransaction.create({
        data: {
          userId: session.id,
          type: "credit_code",
          amount: moneyCode.amount,
          note: `كود: ${normalized}`,
        },
      });

      return moneyCode.amount;
    });

    return NextResponse.json({
      success: true,
      credited: creditedAmount,
      message: `تم إضافة ${creditedAmount} جنيه إلى رصيدك!`,
    });
  } catch (error: any) {
    if (error.message === "NOT_FOUND") {
      return NextResponse.json({ error: "الكود غير صحيح" }, { status: 404 });
    }
    if (error.message === "ALREADY_USED") {
      return NextResponse.json({ error: "هذا الكود مستخدم بالفعل" }, { status: 400 });
    }
    if (error.message === "EXPIRED") {
      return NextResponse.json({ error: "الكود منتهي الصلاحية" }, { status: 400 });
    }
    console.error("[balance redemption] error:", error);
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getStudentSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
  try {
    const session = await getStudentSession();
    if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });

    const enrollments = await prisma.planEnrollment.findMany({
      where: { studentId: session.id },
      include: {
        plan: {
          include: {
            lessons: true,
            _count: { select: { lessons: true } },
          },
        },
        progress: true,
      },
      orderBy: { createdAt: "desc" },
    });

    const enrolledPlans = enrollments.map((e) => {
      const completedLessons = e.plan.lessons.filter((lesson) => {
        const prog = e.progress.find((p) => p.planLessonId === lesson.id);
        if (!prog) return false;
        if (!prog.watched) return false;
        if (lesson.requiresQuiz && !prog.quizPassed) return false;
        if (lesson.requiresHomework && !prog.homeworkPassed) return false;
        if (lesson.hasProject && !prog.projectPassed) return false;
        return true;
      }).length;

      return {
        id: e.plan.id,
        title: e.plan.title,
        educationalStage: e.plan.educationalStage,
        totalLessons: e.plan._count.lessons,
        completedLessons,
        progressPercent: e.plan._count.lessons > 0 ? Math.round((completedLessons / e.plan._count.lessons) * 100) : 0,
        expiresAt: e.expiresAt,
      };
    });

    return NextResponse.json({ success: true, enrolledPlans });
  } catch (error) {
    console.error("Student Plans API error:", error);
    return NextResponse.json({ error: "حدث خطأ" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getStudentSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET() {
  const { getSession } = await import("@/lib/auth");
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
  // Non-students have no quiz results — return empty gracefully
  if (session.role !== "student") return NextResponse.json({ results: [], total: 0 });

  const results = await prisma.quizResult.findMany({
    where: { studentId: session.id },
    orderBy: { completedAt: "desc" },
    select: {
      id: true,
      score: true,
      totalQ: true,
      startedAt: true,
      completedAt: true,
      allowRetake: true,
      quiz: {
        select: {
          id: true,
          title: true,
          timeLimitMinutes: true,
          folder: {
            select: {
              course: { select: { id: true, title: true, subject: true } },
            },
          },
        },
      },
      // Per-question counts for the detailed table columns
      answers: {
        select: { isCorrect: true, selectedAnswer: true },
      },
    },
  });

  // Shape the response to match the screenshot columns
  const shaped = results.map((r, idx) => {
    const attempted = r.answers.filter(a => a.selectedAnswer !== null).length;
    const correct   = r.answers.filter(a => a.isCorrect).length;
    return {
      serial:      idx + 1,
      id:          r.id,
      quizId:      r.quiz.id,
      quizTitle:   r.quiz.title,
      courseTitle: r.quiz.folder?.course?.title ?? 'خطة دراسية',
      subject:     r.quiz.folder?.course?.subject ?? 'عام',
      courseId:    r.quiz.folder?.course?.id ?? 'plan',
      totalQ:      r.totalQ,
      score:       r.score,
      pct:         Math.round((r.score / Math.max(r.totalQ, 1)) * 100),
      attempted,
      correct,
      hasAnswers:  r.answers.length > 0,
      startedAt:   r.startedAt,
      completedAt: r.completedAt,
      allowRetake: r.allowRetake,
    };
  });

  return NextResponse.json(
    { results: shaped, total: shaped.length },
    { headers: { "Cache-Control": "private, max-age=60, stale-while-revalidate=120" } }
  );
}

