import { NextResponse } from "next/server";
import { getStudentSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

/**
 * Real gamification stats for the signed-in student: points + login streak from
 * the User row, watched/quiz/course counts, last-28-day activity, and a computed
 * achievements list. Replaces the library's client-side guesses.
 */
const EMPTY_STATS = {
  points: 0, streak: 0, watchedVideos: 0, quizzesPassed: 0,
  coursesCount: 0, hours: 0, weekActive: Array(7).fill(false),
  activity: Array(28).fill(0), achievements: [], achievementsUnlocked: 0, weaknesses: [],
};

export async function GET() {
  try {
  const { getSession } = await import("@/lib/auth");
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
  // Non-students (admin, teacher, staff) have no gamification data
  if (session.role !== "student") {
    return NextResponse.json(EMPTY_STATS, {
      headers: { "Cache-Control": "private, max-age=300" },
    });
  }
  const studentId = session.id;

  const user = await prisma.user.findUnique({
    where: { id: studentId },
    select: { name: true, points: true, loginStreak: true, lastLoginDate: true },
  });

  const [watchedRows, quizResults, enrollments, sessions] = await Promise.all([
    prisma.progress.findMany({
      where: { studentId, watched: true },
      select: { video: { select: { durationMinutes: true } } },
    }),
    prisma.quizResult.findMany({
      where: { studentId },
      select: {
        score: true,
        quiz: {
          select: {
            folder: { select: { course: { select: { id: true, title: true, subject: true } } } },
          },
        },
      },
    }),
    prisma.accessCode.findMany({ where: { studentId, isActive: true }, select: { courseId: true } }),
    prisma.videoWatchSession.findMany({
      where: { studentId, startedAt: { gte: new Date(Date.now() - 28 * 86400000) } },
      select: { startedAt: true },
    }),
  ]);

  const watchedVideos = watchedRows.length;
  const minutes = watchedRows.reduce((a, r) => a + (r.video?.durationMinutes ?? 0), 0);
  const hours = Math.round((minutes / 60) * 10) / 10;
  const quizzesPassed = quizResults.filter((q) => q.score >= 50).length;
  const quizzesFull = quizResults.filter((q) => q.score >= 100).length;

  // Weakness view: average quiz score per subject, surfacing the subjects that
  // most need review. Pure aggregation over the student's own quiz results; the
  // link points to the course (within the subject) where they scored lowest.
  type CourseAgg = { id: string; title: string; sum: number; n: number };
  type SubjectAgg = { subject: string; sum: number; n: number; courses: Map<string, CourseAgg> };
  const subjectMap = new Map<string, SubjectAgg>();
  for (const q of quizResults) {
    const course = q.quiz?.folder?.course;
    if (!course) continue;
    const subject = course.subject?.trim() || "عام";
    let agg = subjectMap.get(subject);
    if (!agg) { agg = { subject, sum: 0, n: 0, courses: new Map() }; subjectMap.set(subject, agg); }
    agg.sum += q.score;
    agg.n += 1;
    let c = agg.courses.get(course.id);
    if (!c) { c = { id: course.id, title: course.title, sum: 0, n: 0 }; agg.courses.set(course.id, c); }
    c.sum += q.score;
    c.n += 1;
  }
  const weaknesses = [...subjectMap.values()]
    .map((a) => {
      const avgScore = Math.round(a.sum / a.n);
      const course = [...a.courses.values()].sort((x, y) => x.sum / x.n - y.sum / y.n)[0];
      return { subject: a.subject, avgScore, quizCount: a.n, course: { id: course.id, title: course.title } };
    })
    .filter((w) => w.avgScore < 75) // only surface subjects that genuinely need work
    .sort((a, b) => a.avgScore - b.avgScore)
    .slice(0, 3);
  const coursesCount = new Set(enrollments.map((e) => e.courseId)).size;
  const points = user?.points ?? 0;

  // Effective streak: only counts if the last login was today or yesterday.
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  let streak = 0;
  if (user?.lastLoginDate) {
    const last = new Date(user.lastLoginDate);
    const lastDay = new Date(last.getFullYear(), last.getMonth(), last.getDate()).getTime();
    if (lastDay === today || lastDay === today - 86400000) streak = user.loginStreak;
  }

  // Last-28-day activity counts (for the heatmap), oldest → newest.
  const activity = Array.from({ length: 28 }, () => 0);
  for (const s of sessions) {
    const d = new Date(s.startedAt);
    const day = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
    const idx = 27 - Math.floor((today - day) / 86400000);
    if (idx >= 0 && idx < 28) activity[idx]++;
  }
  // Streak run (consecutive login days ending at lastLoginDate).
  let streakStart = Infinity;
  let lastDay = -Infinity;
  if (streak > 0 && user?.lastLoginDate) {
    const last = new Date(user.lastLoginDate);
    lastDay = new Date(last.getFullYear(), last.getMonth(), last.getDate()).getTime();
    streakStart = lastDay - (streak - 1) * 86400000;
  }

  // Days the student "entered" (logged in) also count as light activity, so the
  // grid isn't empty for someone who shows up daily but hasn't watched yet.
  for (let i = 0; i < 28; i++) {
    const day = today - (27 - i) * 86400000;
    if (day >= streakStart && day <= lastDay) activity[i] = Math.max(activity[i], 1);
  }

  // Which of the last 7 days the streak covers (oldest → today), so the card's
  // dots match the 🔥 number.
  const last7 = Array.from({ length: 7 }, (_, i) => today - (6 - i) * 86400000);
  const weekActive = last7.map((d) => d >= streakStart && d <= lastDay);

  const achievements = [
    { id: "first-steps", title: "بداية الرحلة", description: "اشترك في أول كورس", icon: "rocket", unlocked: coursesCount >= 1 },
    { id: "fast-learner", title: "متعلم سريع", description: "أكمل 5 دروس", icon: "bolt", unlocked: watchedVideos >= 5 },
    { id: "streak-7", title: "مواظب", description: "7 أيام متتالية", icon: "flame", unlocked: streak >= 7 },
    { id: "quiz-star", title: "نجم الاختبارات", description: "درجة كاملة في اختبار", icon: "star", unlocked: quizzesFull >= 1 },
    { id: "dedicated", title: "مثابر", description: "أكمل 10 دروس", icon: "medal", unlocked: watchedVideos >= 10 },
    { id: "expert", title: "خبير", description: "أكمل 20 درساً", icon: "trophy", unlocked: watchedVideos >= 20 },
  ];

  return NextResponse.json(
    {
      points,
      streak,
      watchedVideos,
      quizzesPassed,
      coursesCount,
      hours,
      weekActive,
      activity,
      achievements,
      achievementsUnlocked: achievements.filter((a) => a.unlocked).length,
      weaknesses,
    },
    {
      headers: {
        // Cache stats for 5 minutes in the browser. The 4 parallel DB queries in
        // this route are now shared across all callers (library page, StreakFlame,
        // notification panel) via a single browser cache entry.
        "Cache-Control": "private, max-age=300, stale-while-revalidate=600",
      },
    }
  );
} catch (error) {
    console.error("[student/stats] error:", error);
    return NextResponse.json(
      { error: "حدث خطأ داخلي" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getStudentSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

/**
 * Returns all wrong answers grouped by subject/quiz,
 * with full question details so the UI can build a personal practice exam.
 */
export async function GET() {
  const { getSession } = await import("@/lib/auth");
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
  if (session.role !== "student") return NextResponse.json({ total: 0, bySubject: {}, questions: [] });

  const wrongAnswers = await prisma.quizAnswer.findMany({
    where: { studentId: session.id, isCorrect: false },
    orderBy: { createdAt: "desc" },
    select: {
      id: true,
      questionId: true,
      question: true,
      optionA: true,
      optionB: true,
      optionC: true,
      optionD: true,
      correctAnswer: true,
      selectedAnswer: true,
      createdAt: true,
      result: {
        select: {
          quiz: {
            select: {
              id: true,
              title: true,
              folder: {
                select: {
                  course: { select: { id: true, title: true, subject: true } },
                },
              },
            },
          },
        },
      },
    },
  });

  // Deduplicate: keep only the LATEST wrong answer per questionId
  const seen = new Set<string>();
  const unique = wrongAnswers.filter(a => {
    if (seen.has(a.questionId)) return false;
    seen.add(a.questionId);
    return true;
  });

  // Group by subject for the filter UI
  const bySubject: Record<string, typeof unique> = {};
  for (const a of unique) {
    const subj = a.result.quiz.folder?.course?.subject ?? "عام";
    if (!bySubject[subj]) bySubject[subj] = [];
    bySubject[subj].push(a);
  }

  return NextResponse.json(
    { total: unique.length, bySubject, questions: unique },
    { headers: { "Cache-Control": "private, max-age=60" } }
  );
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function POST(req: NextRequest) {
  try {
    const session = await getSession();
    if (!session) {
      return NextResponse.json({ error: "يجب تسجيل الدخول أولاً لشراء الاشتراك بالرصيد" }, { status: 401 });
    }

    const { teacherId, planType, language: requestedLang } = await req.json().catch(() => ({}));

    if (!teacherId || typeof teacherId !== "string") {
      return NextResponse.json({ error: "معرف الأستاذ مطلوب" }, { status: 400 });
    }

    const validPlanTypes = ["monthly", "termly", "yearly", "1month", "3months", "6months"];
    if (!planType || !validPlanTypes.includes(planType)) {
      return NextResponse.json({ error: "نوع الباقة غير صحيح" }, { status: 400 });
    }

    const profile = await prisma.teacherProfile.findUnique({
      where: { teacherId },
    });

    if (!profile) {
      return NextResponse.json({ error: "لم يتم العثور على الأستاذ" }, { status: 400 });
    }

    if (profile.bookingEnabled === false) {
      return NextResponse.json({ error: "عفواً، الحجز مغلق حالياً مع هذا الأستاذ" }, { status: 403 });
    }

    const isLanguages = requestedLang === "languages";
    if (isLanguages && profile.languagesEnabled === false) {
      return NextResponse.json({ error: "هذا المعلم متاح للحجز باللغة العربية فقط" }, { status: 400 });
    }
    if (!isLanguages && profile.arabicEnabled === false) {
      return NextResponse.json({ error: "هذا المعلم متاح للحجز لغات فقط" }, { status: 400 });
    }

    // Map 1month, 3months, 6months (and legacy types) to prices
    let numAmount: number | null = null;
    let durationDays = 30;
    let label = "اشتراك شهري";

    if (planType === "1month" || planType === "monthly") {
      if (profile.enableMonthly1 === false) {
        return NextResponse.json({ error: "خطة شهر واحد غير مفعّلة لدى المعلم" }, { status: 400 });
      }
      const base = profile.priceMonthly1 ?? profile.priceMonthly ?? 200;
      const surcharge = isLanguages ? (profile.langSurcharge1 ?? 50) : 0;
      numAmount = base + surcharge;
      durationDays = 30;
      label = isLanguages ? "اشتراك 1 شهر (لغات)" : "اشتراك 1 شهر (عربي)";
    } else if (planType === "3months" || planType === "termly") {
      if (profile.enableMonthly3 === false) {
        return NextResponse.json({ error: "خطة 3 شهور غير مفعّلة لدى المعلم" }, { status: 400 });
      }
      const base = profile.priceMonthly3 ?? profile.priceTermly ?? 500;
      const surcharge = isLanguages ? (profile.langSurcharge3 ?? 150) : 0;
      numAmount = base + surcharge;
      durationDays = 90;
      label = isLanguages ? "اشتراك 3 شهور (لغات)" : "اشتراك 3 شهور (عربي)";
    } else if (planType === "6months" || planType === "yearly") {
      if (profile.enableMonthly6 === false) {
        return NextResponse.json({ error: "خطة 6 شهور غير مفعّلة لدى المعلم" }, { status: 400 });
      }
      const base = profile.priceMonthly6 ?? profile.priceYearly ?? 1000;
      const surcharge = isLanguages ? (profile.langSurcharge6 ?? 300) : 0;
      numAmount = base + surcharge;
      durationDays = 180;
      label = isLanguages ? "اشتراك 6 شهور (لغات)" : "اشتراك 6 شهور (عربي)";
    }

    if (numAmount == null) {
      return NextResponse.json({ error: "هذه الباقة غير متوفرة" }, { status: 400 });
    }

    const teacherName = profile.displayName || profile.slug;

    const user = await prisma.user.findUnique({
      where: { id: session.id },
      select: { id: true, balance: true },
    });

    if (!user) {
      return NextResponse.json({ error: "المستخدم غير موجود" }, { status: 404 });
    }

    if (user.balance < numAmount) {
      return NextResponse.json(
        {
          error: `رصيدك الحالي (${user.balance} جنيه) لا يكفي لشراء الاشتراك (${numAmount} جنيه). يرجى شحن رصيدك أولاً.`,
        },
        { status: 400 }
      );
    }

    const userDetails = await prisma.user.findUnique({
      where: { id: session.id },
      select: { name: true, phone: true, parentPhone: true, educationalStage: true },
    });

    const expiresAt = new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000);

    const updatedUser = await prisma.$transaction(async (tx) => {
      const updated = await tx.user.update({
        where: { id: session.id },
        data: { balance: { decrement: numAmount } },
      });

      await tx.balanceTransaction.create({
        data: {
          userId: session.id,
          type: "debit_purchase",
          amount: -numAmount,
          note: `حجز اشتراك (${label}) - أستاذ ${teacherName || "المعلم"}`,
        },
      });

      await tx.teacherSubscription.upsert({
        where: {
          studentId_teacherId_planType: {
            studentId: session.id,
            teacherId: teacherId,
            planType: planType,
          },
        },
        create: {
          studentId: session.id,
          teacherId: teacherId,
          planType: planType,
          planLabel: label,
          language: isLanguages ? "languages" : "arabic",
          amount: numAmount,
          educationalStage: userDetails?.educationalStage,
          studentName: userDetails?.name,
          studentPhone: userDetails?.phone,
          parentPhone: userDetails?.parentPhone,
          status: "active",
          expiresAt: expiresAt,
        },
        update: {
          planLabel: label,
          language: isLanguages ? "languages" : "arabic",
          amount: numAmount,
          educationalStage: userDetails?.educationalStage,
          studentName: userDetails?.name,
          studentPhone: userDetails?.phone,
          parentPhone: userDetails?.parentPhone,
          status: "active",
          expiresAt: expiresAt,
        },
      });

      return updated;
    });

    return NextResponse.json({
      success: true,
      message: `تم الشراء وحجز الاشتراك بنجاح! خُصم ${numAmount} جنيه من رصيدك. رصيدك الحالي: ${updatedUser.balance} جنيه.`,
      newBalance: updatedUser.balance,
    });
  } catch (error: any) {
    console.error("[subscribe-balance] error:", error);
    return NextResponse.json({ error: "حدث خطأ أثناء خصم الرصيد" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
  try {
    const session = await getSession();
    if (!session || (session.role !== "teacher" && session.role !== "admin" && session.role !== "superadmin")) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const stage = searchParams.get("stage");
    const plan = searchParams.get("plan");
    const query = searchParams.get("q");

    const teacherId = session.id;

    const where: any = { teacherId };

    if (stage) where.educationalStage = stage;
    if (plan) where.planType = plan;
    if (query) {
      where.OR = [
        { studentName: { contains: query, mode: "insensitive" } },
        { studentPhone: { contains: query, mode: "insensitive" } },
        { parentPhone: { contains: query, mode: "insensitive" } },
        { student: { name: { contains: query, mode: "insensitive" } } },
        { student: { email: { contains: query, mode: "insensitive" } } },
      ];
    }

    const subscriptions = await prisma.teacherSubscription.findMany({
      where,
      orderBy: { createdAt: "desc" },
      include: {
        student: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true,
            parentPhone: true,
            educationalStage: true,
            createdAt: true,
          },
        },
      },
    });

    return NextResponse.json({ subscriptions });
  } catch (error) {
    console.error("[teacher/subscriptions GET] error:", error);
    return NextResponse.json({ error: "حدث خطأ أثناء جلب المشتركين" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await getSession();
    if (!session || (session.role !== "teacher" && session.role !== "admin" && session.role !== "superadmin")) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const { studentEmailOrPhone, planType, planLabel, amount, educationalStage } = await req.json();

    if (!studentEmailOrPhone || !planType) {
      return NextResponse.json({ error: "بيانات الطالب ونوع الباقة مطلوبة" }, { status: 400 });
    }

    // Find student by email or phone
    const student = await prisma.user.findFirst({
      where: {
        OR: [
          { email: studentEmailOrPhone.trim() },
          { phone: studentEmailOrPhone.trim() },
        ],
      },
    });

    if (!student) {
      return NextResponse.json({ error: "لم يتم العثور على طالب بهذا البريد أو الهاتف" }, { status: 404 });
    }

    const labelMap: Record<string, string> = {
      "1month": "اشتراك 1 شهر",
      "3months": "اشتراك 3 شهور",
      "6months": "اشتراك 6 شهور",
      monthly: "اشتراك شهري",
      termly: "اشتراك ترم كامل",
      yearly: "اشتراك سنوي",
    };

    const sub = await prisma.teacherSubscription.upsert({
      where: {
        studentId_teacherId_planType: {
          studentId: student.id,
          teacherId: session.id,
          planType,
        },
      },
      create: {
        studentId: student.id,
        teacherId: session.id,
        planType,
        planLabel: planLabel || labelMap[planType] || "اشتراك معلم",
        amount: Number(amount) || 0,
        educationalStage: educationalStage || student.educationalStage,
        studentName: student.name,
        studentPhone: student.phone,
        parentPhone: student.parentPhone,
        status: "active",
      },
      update: {
        planLabel: planLabel || labelMap[planType] || "اشتراك معلم",
        amount: Number(amount) || 0,
        educationalStage: educationalStage || student.educationalStage,
        studentName: student.name,
        studentPhone: student.phone,
        parentPhone: student.parentPhone,
        status: "active",
      },
    });

    return NextResponse.json({ success: true, subscription: sub });
  } catch (error) {
    console.error("[teacher/subscriptions POST] error:", error);
    return NextResponse.json({ error: "حدث خطأ أثناء إضافة الطالب" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { acquireAdvisoryLock } from "@/lib/distributed-lock";

import { processTeacherAttribution } from "@/lib/referral";

/**
 * POST /api/videos/[id]/purchase
 * Student purchases access to a single video/lesson.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSession();
  if (!session || session.role !== "student")
    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });

  const { id: videoId } = await params;
  const reqBody = await req.json().catch(() => ({}));
  const promoCodeInput = reqBody.promoCode || reqBody.promo_code;

  try {
    const purchase = await prisma.$transaction(async (tx) => {
      // Acquire transaction-scoped advisory lock to serialize purchases for the user
      await acquireAdvisoryLock(`purchase-video-${session.id}`, tx);

      const video = await tx.video.findUnique({
        where: { id: videoId },
        include: { folder: { include: { course: { select: { id: true, teacherId: true, title: true } } } } },
      });

      if (!video) throw new Error("NOT_FOUND");

      // Prevent double purchase inside the transaction
      const existing = await tx.videoPurchase.findUnique({
        where: { studentId_videoId: { studentId: session.id, videoId } },
      });
      if (existing) throw new Error("ALREADY_OWNED");

      const price = video.price ?? 0;

      if (price > 0) {
        const student = await tx.user.findUnique({
          where: { id: session.id },
          select: { balance: true },
        });
        if (!student || (student.balance ?? 0) < price) {
          throw new Error("INSUFFICIENT_BALANCE");
        }

        // Deduct balance atomically
        await tx.user.update({
          where: { id: session.id },
          data: { balance: { decrement: price } },
        });

        // Add ledger entry
        await tx.balanceTransaction.create({
          data: {
            userId: session.id,
            type: "debit_course",
            amount: -price,
            note: `شراء درس: ${video.title}`,
          },
        });
      }

      // Create purchase record
      const res = await tx.videoPurchase.create({
        data: { studentId: session.id, videoId, price },
      });

      // Process Teacher Referral Attribution
      await processTeacherAttribution({
        studentId: session.id,
        teacherIdOfContent: video.folder.course.teacherId,
        amount: price,
        purchaseType: "VIDEO",
        videoId,
        folderId: video.folder.id,
        courseId: video.folder.course.id,
        promoCodeInput,
        tx,
      });

      return res;
    });

    return NextResponse.json({ purchase, message: "تم شراء الدرس بنجاح" }, { status: 201 });
  } catch (error: any) {
    if (error.message === "NOT_FOUND") {
      return NextResponse.json({ error: "الدرس غير موجود" }, { status: 404 });
    }
    if (error.message === "ALREADY_OWNED") {
      return NextResponse.json({ error: "لقد اشتريت هذا الدرس بالفعل", alreadyOwned: true });
    }
    if (error.message === "INSUFFICIENT_BALANCE") {
      return NextResponse.json({ error: "رصيدك غير كافٍ" }, { status: 402 });
    }
    console.error("[video purchase] error:", error);
    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
  }
}

/** GET /api/videos/[id]/purchase — check if student owns this video */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await getSession();
  if (!session) return NextResponse.json({ owned: false });

  const { id: videoId } = await params;
  const purchase = await prisma.videoPurchase.findUnique({
    where: { studentId_videoId: { studentId: session.id, videoId } },
  });
  return NextResponse.json({ owned: !!purchase });
}

