	search: "\u0627\u0628\u062d\u062b \u0628\u0627\u0633\u0645 \u0627\u0644\u0643\u0648\u0631\u0633 \u0623\u0648 \u0627\u0644\u0645\u0627\u062f\u0629",
	searchButton: "\u0628\u062d\u062b",
	filters: "\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0628\u062d\u062b",
	all: "\u0627\u0644\u0643\u0644",
	subject: "\u0627\u0644\u0645\u0627\u062f\u0629",
	teacher: "\u0627\u0644\u0645\u062f\u0631\u0633",
	stage: "\u0627\u0644\u0645\u0631\u062d\u0644\u0629",
	results: "\u0643\u0648\u0631\u0633 \u0645\u062a\u0627\u062d",
	lecture: "\u0645\u062d\u0627\u0636\u0631\u0629",
	quiz: "\u0627\u062e\u062a\u0628\u0627\u0631",
	free: "\u0645\u062c\u0627\u0646\u064a",
	currency: "\u062c\u0646\u064a\u0647",
	access: "\u0645\u0636\u0627\u0641 \u0644\u0645\u0643\u062a\u0628\u062a\u0643",
	view: "\u0634\u0648\u0641 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644",
	empty: "\u0645\u0641\u064a\u0634 \u0643\u0648\u0631\u0633\u0627\u062a \u0645\u0637\u0627\u0628\u0642\u0629",
	emptyText: "\u063a\u064a\u0651\u0631 \u0643\u0644\u0645\u0629 \u0627\u0644\u0628\u062d\u062b \u0623\u0648 \u0627\u0645\u0633\u062d \u0628\u0639\u0636 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a.",
	unavailable: "\u0645\u0634 \u0642\u0627\u062f\u0631\u064a\u0646 \u0646\u062d\u0645\u0644 \u0627\u0644\u0643\u0648\u0631\u0633\u0627\u062a \u062f\u0644\u0648\u0642\u062a\u064a. \u062c\u0631\u0628 \u062a\u0627\u0646\u064a \u0628\u0639\u062f \u0634\u0648\u064a\u0629.",
	clear: "\u0645\u0633\u062d \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a",
} as const;

const STAGES: Record<string, string> = {
	sec_1: "\u0623\u0648\u0644\u0649 \u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0627",
	sec_2: "\u062b\u0627\u0646\u064a\u0629 \u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0627",
};

type SearchValue = string | string[] | undefined;
type CourseSearch = Record<string, SearchValue>;
type CatalogCourse = {
	id: string;
	slug: string | null;
	title: string;
	description: string | null;
	subject: string;
	educationalStage: string;
	thumbnailUrl: string | null;
	isPaid: boolean;
	price: number | null;
	teacher: { id: string; name: string; teacherProfile: { displayName: string | null; photoUrl: string | null } | null };
	folders: Array<{ _count: { videos: number; quizzes: number } }>;
};

function one(value: SearchValue) {
	return (Array.isArray(value) ? value[0] ?? "" : value ?? "").trim();
}

function safeImage(value: string | null) {
	if (!value) return null;
	return /^https?:\/\//i.test(value) || value.startsWith("data:image/") || value.startsWith("/") ? value : null;
}

function formatPounds(value: number) {
	return new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 }).format(value);
}

function hrefWith(current: { q: string; subject: string; teacher: string; stage: string }, patch: Partial<typeof current>) {
	const next = { ...current, ...patch };
	const params = new URLSearchParams();
	if (next.q) params.set("q", next.q);
	if (next.subject) params.set("subject", next.subject);
	if (next.teacher) params.set("teacher", next.teacher);
	if (next.stage) params.set("stage", next.stage);
	return params.size ? `/courses?${params.toString()}` : "/courses";
}

export default async function CoursesPage({ searchParams }: { searchParams: Promise<CourseSearch> }) {
	const raw = await searchParams;
	const selected = { q: one(raw.q), subject: one(raw.subject), teacher: one(raw.teacher), stage: one(raw.stage) };
	const session = await getSession();
	let unavailable = false;
	let courses: CatalogCourse[] = [];
	let teacherOptions: Array<{ id: string; name: string }> = [];
	let allSubjects: string[] = [];
	let allStages: string[] = [];

	try {
		const [courseRows, teacherRows, optionRows] = await Promise.all([
			prisma.course.findMany({
				where: {
					teacher: { isDeleted: false },
					...(selected.subject ? { subject: selected.subject } : {}),
					...(selected.teacher ? { teacherId: selected.teacher } : {}),
					...(selected.stage ? { educationalStage: selected.stage } : {}),
					...(selected.q ? { OR: [
						{ title: { contains: selected.q, mode: "insensitive" as const } },
						{ subject: { contains: selected.q, mode: "insensitive" as const } },
						{ description: { contains: selected.q, mode: "insensitive" as const } },
					] } : {}),
				},
				orderBy: { createdAt: "desc" },
				take: 100,
				include: {
					teacher: { select: { id: true, name: true, teacherProfile: { select: { displayName: true, photoUrl: true } } } },
					folders: { select: { _count: { select: { videos: true, quizzes: true } } } },
				},
			}),
			prisma.user.findMany({
				where: { role: "teacher", isDeleted: false, courses: { some: {} } },
				orderBy: { name: "asc" },
				select: { id: true, name: true, teacherProfile: { select: { displayName: true } } },
			}),
			prisma.course.findMany({
				where: { teacher: { isDeleted: false } },
				select: { subject: true, educationalStage: true },
			}),
		]);
		courses = courseRows as CatalogCourse[];
		teacherOptions = teacherRows.map((teacher) => ({ id: teacher.id, name: teacher.teacherProfile?.displayName ?? teacher.name }));
		allSubjects = Array.from(new Set(optionRows.map((item) => item.subject).filter(Boolean))).sort();
		allStages = Array.from(new Set(optionRows.map((item) => item.educationalStage).filter(Boolean))).sort();
	} catch {
		unavailable = true;
	}

	const access = new Set<string>();
	if (!unavailable && session?.role === "student" && courses.length) {
		try {
			const rows = await prisma.accessCode.findMany({
				where: { studentId: session.id, courseId: { in: courses.map((course) => course.id) } },
				select: { courseId: true },
			});
			rows.forEach((row) => access.add(row.courseId));
		} catch {
			// Personal access badges are optional; the public catalogue still renders.
		}
	}

	const hasFilters = Boolean(selected.q || selected.subject || selected.teacher || selected.stage);

	return (
		<div className="c-pub c-catalog" dir="rtl">
			<PublicHeader signedIn={Boolean(session)} />
			<main className="c-catalog__inner">
				<header className="c-catalog__hero">
					<div><span className="c-catalog__kicker">Code-UP</span><h1>{COPY.title}</h1><p>{COPY.lead}</p></div>
					<form className="c-catalog__search" action="/courses" method="get" role="search">
						<span aria-hidden="true"><IconSearch /></span>
						<input name="q" type="search" defaultValue={selected.q} placeholder={COPY.search} aria-label={COPY.search} />
						{selected.subject ? <input type="hidden" name="subject" value={selected.subject} /> : null}
						{selected.teacher ? <input type="hidden" name="teacher" value={selected.teacher} /> : null}
						{selected.stage ? <input type="hidden" name="stage" value={selected.stage} /> : null}
						<button type="submit">{COPY.searchButton}</button>
					</form>
				</header>

				{unavailable ? <Band tone="warning" text={COPY.unavailable} /> : null}
				{!unavailable ? (
					<section className="c-catalog__filters" aria-labelledby="catalog-filters">
						<div className="c-catalog__filters-head"><h2 id="catalog-filters">{COPY.filters}</h2>{hasFilters ? <Link href="/courses">{COPY.clear}</Link> : null}</div>
						<FilterRow label={COPY.subject} allLabel={COPY.all} allHref={hrefWith(selected, { subject: "" })} allActive={!selected.subject} items={allSubjects.map((subject) => ({ key: subject, label: subject, href: hrefWith(selected, { subject }), active: selected.subject === subject }))} />
						<FilterRow label={COPY.teacher} allLabel={COPY.all} allHref={hrefWith(selected, { teacher: "" })} allActive={!selected.teacher} items={teacherOptions.map((teacher) => ({ key: teacher.id, label: teacher.name, href: hrefWith(selected, { teacher: teacher.id }), active: selected.teacher === teacher.id }))} />
						<FilterRow label={COPY.stage} allLabel={COPY.all} allHref={hrefWith(selected, { stage: "" })} allActive={!selected.stage} items={allStages.map((stage) => ({ key: stage, label: STAGES[stage] ?? stage, href: hrefWith(selected, { stage }), active: selected.stage === stage }))} />
					</section>
				) : null}

				{!unavailable ? (
					<section className="c-catalog__results">
						<div className="c-catalog__results-head"><h2>{COPY.title}</h2><span dir="ltr">{courses.length} <bdi>{COPY.results}</bdi></span></div>
						{courses.length === 0 ? (
							<div className="c-card"><Empty icon={<IconBook />} title={COPY.empty} text={COPY.emptyText} action={hasFilters ? <LinkButton href="/courses" label={COPY.clear} inline /> : undefined} /></div>
						) : (
							<ul className="c-catalog-grid">
								{courses.map((course) => {
									const videos = course.folders.reduce((sum, folder) => sum + folder._count.videos, 0);
									const quizzes = course.folders.reduce((sum, folder) => sum + folder._count.quizzes, 0);
									const teacherName = course.teacher.teacherProfile?.displayName ?? course.teacher.name;
									const thumb = safeImage(course.thumbnailUrl);
									const hasAccess = access.has(course.id);
									return (
										<li key={course.id}><Link className="c-catalog-card" href={`/courses/${course.slug ?? course.id}`}>
											{thumb ? <img className="c-catalog-card__thumb" src={thumb} alt="" /> : <span className="c-catalog-card__thumb c-catalog-card__thumb--empty" aria-hidden="true"><IconBook size={34} /></span>}
											<div className="c-catalog-card__body">
												<div className="c-catalog-card__badges"><Badge label={course.subject} tone="blue" />{hasAccess ? <Badge label={COPY.access} tone="green" /> : null}</div>
												<h3>{course.title}</h3>
												<p className="c-catalog-card__teacher"><IconUsers size={16} /> {teacherName}</p>
												{course.description ? <p className="c-catalog-card__desc">{course.description}</p> : null}
												<div className="c-catalog-card__meta"><span>{STAGES[course.educationalStage] ?? course.educationalStage}</span><span>{videos} {COPY.lecture}</span>{quizzes ? <span>{quizzes} {COPY.quiz}</span> : null}</div>
												<div className="c-catalog-card__foot"><strong dir="ltr">{!course.isPaid || !course.price ? COPY.free : `${formatPounds(course.price)} ${COPY.currency}`}</strong><span>{hasAccess ? COPY.access : COPY.view}</span></div>
											</div>
										</Link></li>
									);
								})}
							</ul>
						)}
					</section>
				) : null}
			</main>
			<SiteFooter />
		</div>
	);
}

function FilterRow({ label, allLabel, allHref, allActive, items }: { label: string; allLabel: string; allHref: string; allActive: boolean; items: Array<{ key: string; label: string; href: string; active: boolean }> }) {
	if (!items.length) return null;
	return (
		<div className="c-filter-row"><strong>{label}</strong><div><Link href={allHref} data-active={allActive}>{allLabel}</Link>{items.map((item) => <Link key={item.key} href={item.href} data-active={item.active}>{item.label}</Link>)}</div></div>
	);
}

"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { AuthShell } from "@/components/auth/AuthShell";

type Step = "phone" | "reset" | "done";

export default function ForgotPasswordPage() {
  const router = useRouter();
  const [step, setStep] = useState<Step>("phone");
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState("");
  const [devCode, setDevCode] = useState<string | null>(null);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [isBypassed, setIsBypassed] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [sentChannel, setSentChannel] = useState<"whatsapp" | "sms" | null>(null);
  const [success, setSuccess] = useState("");

  useEffect(() => {
    if (cooldown <= 0) return;
    const timer = setInterval(() => {
      setCooldown((c) => c - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [cooldown]);

  const formatPhone = (p: string) => {
    const digits = p.replace(/\D/g, "");
    if (digits.startsWith("20") && digits.length === 12) return `+${digits}`;
    if (digits.startsWith("0") && digits.length === 11) return `+20${digits.slice(1)}`;
    if (digits.length === 9) return `+20${digits}`;
    if (p.startsWith("+")) return p;
    return p;
  };

  const handleSendCode = async (e?: React.FormEvent, forceSms?: boolean) => {
    if (e) e.preventDefault();
    setError("");
    setSuccess("");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/forgot-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: formatPhone(phone), forceChannel: forceSms ? "sms" : undefined }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(data.error || "حدث خطأ");
        return;
      }

      if (data?.bypass) {
        setIsBypassed(true);
        setDevCode("123456");
        setCode("123456");
        setSentChannel("sms");
        setStep("reset");
        return;
      }

      setIsBypassed(false);
      setDevCode(null);
      setSentChannel(data?.channel === "whatsapp" ? "whatsapp" : "sms");
      setSuccess(
        data?.channel === "whatsapp"
          ? "تم إرسال رمز التحقق إلى حساب WhatsApp الخاص بك. يرجى التحقق من تطبيق واتساب."
          : "تم إرسال رمز التحقق عبر الرسائل النصية (SMS). يرجى التحقق من الرسائل النصية على هاتفك."
      );
      setStep("reset");
      setCooldown(60);
    } catch (err: any) {
      console.error("forgot-password sendCode error:", err);
      const errCode = err?.code ? ` [${err.code}]` : "";
      setError((err?.message || "تعذر إرسال كود التحقق. حاول مرة أخرى.") + errCode);
    } finally {
      setLoading(false);
    }
  };

  const handleReset = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (newPassword !== confirmPassword) {
      setError("كلمتا المرور غير متطابقتين");
      return;
    }
    if (newPassword.length < 6) {
      setError("كلمة المرور يجب أن تكون 6 أحرف على الأقل");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/auth/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          phone: formatPhone(phone),
          verificationCode: code,
          newPassword,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(data.error || "حدث خطأ");
        return;
      }
      setStep("done");
    } catch {
      setError("تعذر الاتصال بالخادم");
    } finally {
      setLoading(false);
    }
  };

  if (step === "done") {
    return (
      <AuthShell
        title="تم تغيير كلمة المرور"
        subtitle="يمكنك الآن تسجيل الدخول بكلمة المرور الجديدة"
        footer={null}
      >
        <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur rounded-2xl border border-slate-200/80 dark:border-slate-700/80 shadow-xl p-6 sm:p-8 text-center space-y-5">
          <div className="w-16 h-16 mx-auto rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center text-3xl">
            ✅
          </div>
          <p className="text-gray-700 dark:text-gray-300 text-sm">
            تم تغيير كلمة المرور بنجاح. سجّل الدخول الآن باستخدام رقمك وكلمة المرور الجديدة.
          </p>
          <button
            onClick={() => router.push("/login")}
            className="w-full py-3.5 bg-sky-600 hover:bg-sky-700 text-white font-bold rounded-xl transition-all shadow-md"
          >
            الذهاب إلى تسجيل الدخول
          </button>
        </div>
      </AuthShell>
    );
  }

  if (step === "reset") {
    return (
      <AuthShell
        title="إعادة تعيين كلمة المرور"
        subtitle={`أدخل الكود المُرسَل إلى ${phone}`}
        footer={
          <button
            onClick={() => { setStep("phone"); setDevCode(null); setCode(""); setError(""); }}
            className="text-sky-600 dark:text-sky-400 font-semibold hover:underline"
          >
            تغيير الرقم
          </button>
        }
      >
        <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur rounded-2xl border border-slate-200/80 dark:border-slate-700/80 shadow-xl p-6 sm:p-8">
          {devCode && (
            <div className="mb-5 p-3 rounded-xl border border-amber-200 bg-amber-50 dark:border-amber-700 dark:bg-amber-900/30 text-center">
              <p className="text-xs text-amber-700 dark:text-amber-300 font-medium mb-1">وضع التطوير — الكود:</p>
              <p className="text-2xl font-mono font-black tracking-[0.3em] text-amber-800 dark:text-amber-200 select-all">
                {devCode}
              </p>
            </div>
          )}

          {success && (
            <div className="mb-5 p-3 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-700 text-sm dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300">
              {success}
            </div>
          )}

          {error && (
            <div className="mb-5 p-3 rounded-xl border border-red-200 bg-red-50 text-red-700 text-sm dark:border-red-800 dark:bg-red-950/40 dark:text-red-300">
              {error}
            </div>
          )}

          <form onSubmit={handleReset} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                كود التحقق
              </label>
              <input
                type="text"
                required
                dir="ltr"
                value={code}
                onChange={(e) => setCode(e.target.value)}
                maxLength={6}
                placeholder="123456"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500 text-center font-mono tracking-widest text-lg"
              />
            </div>

            <div className="text-center text-xs text-slate-500 dark:text-slate-400 mt-2">
              تحتاج مساعدة؟ تواصل مع الدعم:{" "}
              <a
                href="tel:+201282287267"
                className="text-sky-600 dark:text-sky-400 font-semibold hover:underline"
              >
                01282287267
              </a>
            </div>

            {sentChannel === "whatsapp" && (
              <div className="text-xs text-slate-500 dark:text-slate-400">
                <button
                  type="button"
                  onClick={() => handleSendCode(undefined, true)}
                  disabled={loading}
                  className="text-sky-600 dark:text-sky-400 underline font-semibold hover:text-sky-800 dark:hover:text-sky-300 cursor-pointer"
                >
                  لم أستلم الرمز على واتساب؟ الإرسال عبر SMS بدلاً من ذلك
                </button>
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                كلمة المرور الجديدة
              </label>
              <input
                type="password"
                required
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="6 أحرف على الأقل"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                تأكيد كلمة المرور
              </label>
              <input
                type="password"
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="أعد كتابة كلمة المرور"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3.5 bg-sky-600 hover:bg-sky-700 disabled:opacity-60 text-white font-bold rounded-xl transition-all shadow-md"
            >
              {loading ? "جارٍ التغيير..." : "تغيير كلمة المرور"}
            </button>
          </form>
        </div>
      </AuthShell>
    );
  }

  return (
    <AuthShell
      title="نسيت كلمة المرور؟"
      subtitle="أدخل رقم هاتفك المسجّل وسنرسل لك كود التحقق"
      footer={
        <>
          تذكّرت كلمة المرور؟{" "}
          <Link href="/login" className="text-sky-600 dark:text-sky-400 font-semibold hover:underline">
            تسجيل الدخول
          </Link>
        </>
      }
    >
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur rounded-2xl border border-slate-200/80 dark:border-slate-700/80 shadow-xl p-6 sm:p-8">
        {error && (
          <div className="mb-5 p-3 rounded-xl border border-red-200 bg-red-50 text-red-700 text-sm dark:border-red-800 dark:bg-red-950/40 dark:text-red-300">
            {error}
          </div>
        )}

        <div id="recaptcha-container"></div>

        <form onSubmit={handleSendCode} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
              رقم المتعلم
            </label>
            <input
              type="tel"
              required
              dir="ltr"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500 text-left"
              placeholder="01XXXXXXXXX"
            />
          </div>

          <button
            type="submit"
            disabled={loading || cooldown > 0}
            className="w-full py-3.5 bg-sky-600 hover:bg-sky-700 disabled:opacity-60 text-white font-bold rounded-xl transition-all shadow-md"
          >
            {loading ? "جارٍ الإرسال..." : cooldown > 0 ? `إعادة الإرسال خلال ${cooldown}ث` : "إرسال كود التحقق"}
          </button>
        </form>
      </div>
    </AuthShell>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useToast } from "@/components/ui/Toast";

// ─── Types ───────────────────────────────────────────────────────────────────

type HWQuestion = {
  id: string;
  question: string;
  imageUrl?: string | null;
  optionA: string;
  optionB: string;
  optionC: string;
  optionD: string;
  order: number;
};

type HWSubmission = {
  id: string;
  status: string;
  score?: number | null;
  totalQ?: number | null;
  submittedOutput?: string | null;
  fileUrl?: string | null;
  fileName?: string | null;
  review?: { verdict?: string | null; note?: string | null } | null;
};

export type HomeworkItem = {
  id: string;
  title: string;
  description?: string | null;
  type: "link" | "exam" | "terminal" | "upload";
  linkUrl?: string | null;
  expectedOutput?: string | null;
  codeTemplate?: string | null;
  codeLanguage?: string | null;
  allowedFileTypes?: string | null;
  dueAt?: string | null;
  timeLimitMinutes: number;
  isPublished: boolean;
  courseTitle?: string;
  lessonTitle?: string;
  questions?: HWQuestion[];
  mySubmission?: HWSubmission | null;
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function statusBadge(sub?: HWSubmission | null) {
  if (!sub) return { label: "لم يُرسل", color: "bg-slate-500/15 text-slate-400" };
  switch (sub.status) {
    case "passed":          return { label: "✅ ناجح",       color: "bg-emerald-500/15 text-emerald-400" };
    case "failed":          return { label: "❌ راسب",        color: "bg-red-500/15 text-red-400" };
    case "review_requested":return { label: "🔍 قيد المراجعة", color: "bg-amber-500/15 text-amber-400" };
    case "pending":         return { label: "⏳ معلق",        color: "bg-blue-500/15 text-blue-400" };
    default:                return { label: sub.status,      color: "bg-slate-500/15 text-slate-400" };
  }
}

const TYPE_LABELS: Record<string, string> = {
  link: "🔗 رابط",
  exam: "📝 اختبار",
  terminal: "💻 كود",
  upload: "📎 رفع ملف",
};

// ─── TerminalForm ────────────────────────────────────────────────────────────

function TerminalForm({ hw, onSuccess }: { hw: HomeworkItem; onSuccess: (sub: HWSubmission) => void }) {
  const [code, setCode] = useState(hw.codeTemplate ?? "");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ status: string; explanation?: string } | null>(null);
  const { error: toastError } = useToast();

  const submit = async () => {
    if (!output.trim()) { toastError("أدخل ناتج الكود أولاً"); return; }
    setLoading(true);
    try {
      const res = await fetch(`/api/homework/${hw.id}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ submittedOutput: output }),
      });
      const data = await res.json();
      if (res.ok) {
        setResult({ status: data.status });
        onSuccess(data.submission);
      } else {
        toastError(data.error || "تعذر إرسال الإجابة");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4 mt-4">
      {hw.description && <p className="text-sm text-slate-400">{hw.description}</p>}
      {hw.codeTemplate && (
        <div>
          <p className="text-xs font-semibold text-slate-400 mb-1">💡 الكود البدئي ({hw.codeLanguage}):</p>
          <pre className="bg-slate-900 border border-slate-700 rounded-xl p-4 text-sm text-emerald-300 font-mono overflow-x-auto whitespace-pre-wrap">{hw.codeTemplate}</pre>
        </div>
      )}
      <div>
        <label className="text-xs font-semibold text-slate-400 block mb-1">📋 الكود الذي كتبته (اختياري):</label>
        <textarea
          value={code}
          onChange={e => setCode(e.target.value)}
          rows={6}
          className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-sm text-white font-mono focus:outline-none focus:border-sky-500 transition-colors resize-y"
          placeholder={`# أكتب الكود هنا...`}
          dir="ltr"
        />
      </div>
      <div>
        <label className="text-xs font-semibold text-slate-400 block mb-1">⚡ ناتج الكود (الـ output):</label>
        <textarea
          value={output}
          onChange={e => setOutput(e.target.value)}
          rows={4}
          className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-sm text-emerald-300 font-mono focus:outline-none focus:border-emerald-500 transition-colors resize-y"
          placeholder="الصق ناتج الكود هنا..."
          dir="ltr"
        />
      </div>
      {result && (
        <div className={`rounded-xl p-3 text-sm font-bold ${result.status === "passed" ? "bg-emerald-500/15 text-emerald-400 border border-emerald-500/30" : result.status === "review_requested" ? "bg-amber-500/15 text-amber-400 border border-amber-500/30" : "bg-red-500/15 text-red-400 border border-red-500/30"}`}>
          {result.status === "passed" ? "✅ أحسنت! الإجابة صحيحة" : result.status === "review_requested" ? "🔍 تم الإرسال — في انتظار مراجعة المعلم" : "❌ الإجابة غير صحيحة، حاول مرة أخرى"}
        </div>
      )}
      <button
        onClick={submit}
        disabled={loading || !output.trim()}
        className="w-full py-3 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-sm transition-colors disabled:opacity-50"
      >
        {loading ? "⏳ جارٍ الإرسال..." : "🚀 إرسال الإجابة"}
      </button>
    </div>
  );
}

// ─── ExamForm ────────────────────────────────────────────────────────────────

function ExamForm({ hw, onSuccess }: { hw: HomeworkItem; onSuccess: (sub: HWSubmission) => void }) {
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState<HWSubmission | null>(null);
  const { error: toastError } = useToast();

  const questions = hw.questions ?? [];
  const allAnswered = questions.every(q => answers[q.id]);

  const submit = async () => {
    if (!allAnswered) { toastError("أجب على جميع الأسئلة أولاً"); return; }
    setLoading(true);
    try {
      const res = await fetch(`/api/homework/${hw.id}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ answers }),
      });
      const data = await res.json();
      if (res.ok) { setSubmitted(data.submission); onSuccess(data.submission); }
      else toastError(data.error || "تعذر إرسال الإجابة");
    } finally { setLoading(false); }
  };

  if (submitted) {
    const badge = statusBadge(submitted);
    return (
      <div className="mt-4 rounded-xl p-4 border border-slate-700 bg-slate-800/50 text-center space-y-2">
        <span className={`inline-flex px-3 py-1 rounded-full text-sm font-bold ${badge.color}`}>{badge.label}</span>
        {submitted.score != null && <p className="text-white font-bold text-lg">{submitted.score}%</p>}
      </div>
    );
  }

  return (
    <div className="space-y-5 mt-4">
      {hw.description && <p className="text-sm text-slate-400">{hw.description}</p>}
      {questions.map((q, qi) => (
        <div key={q.id} className="rounded-xl border border-slate-700 p-4 space-y-3">
          <p className="text-sm font-semibold text-white">{qi + 1}. {q.question}</p>
          {q.imageUrl && <img src={q.imageUrl} alt="" className="rounded-lg max-h-60 object-contain" />}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {(["A","B","C","D"] as const).map(opt => (
              <button
                key={opt}
                onClick={() => setAnswers(a => ({ ...a, [q.id]: opt }))}
                className={`text-right px-3 py-2.5 rounded-xl text-sm border transition-colors ${answers[q.id] === opt ? "bg-sky-600 border-sky-500 text-white font-bold" : "border-slate-700 text-slate-300 hover:border-sky-600"}`}
              >
                ({opt}) {q[`option${opt}` as "optionA" | "optionB" | "optionC" | "optionD"]}
              </button>
            ))}
          </div>
        </div>
      ))}
      <button
        onClick={submit}
        disabled={loading || !allAnswered}
        className="w-full py-3 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-sm transition-colors disabled:opacity-50"
      >
        {loading ? "⏳ جارٍ الإرسال..." : "✅ تسليم الاختبار"}
      </button>
    </div>
  );
}

// ─── UploadForm ───────────────────────────────────────────────────────────────

function UploadForm({ hw, onSuccess }: { hw: HomeworkItem; onSuccess: (sub: HWSubmission) => void }) {
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [submitted, setSubmitted] = useState<HWSubmission | null>(null);
  const { error: toastError, success: toastSuccess } = useToast();

  const doSubmit = async () => {
    if (!file) { toastError("اختر ملفاً أولاً"); return; }
    setUploading(true);
    try {
      // Step 1: upload file
      const fd = new FormData();
      fd.append("file", file);
      const upRes = await fetch(`/api/homework/${hw.id}/upload`, { method: "POST", body: fd });
      const upData = await upRes.json();
      if (!upRes.ok) { toastError(upData.error || "فشل رفع الملف"); return; }

      // Step 2: create submission
      const subRes = await fetch(`/api/homework/${hw.id}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ fileUrl: upData.fileUrl, fileName: upData.fileName }),
      });
      const subData = await subRes.json();
      if (subRes.ok) {
        setSubmitted(subData.submission);
        onSuccess(subData.submission);
        toastSuccess("تم رفع الملف وإرسال الواجب بنجاح!");
      } else {
        toastError(subData.error || "تعذر إرسال الواجب");
      }
    } finally { setUploading(false); }
  };

  if (submitted) {
    return (
      <div className="mt-4 rounded-xl p-4 border border-slate-700 bg-slate-800/50 text-center">
        <p className="text-sm text-emerald-400 font-bold">📎 تم رفع الملف بنجاح — في انتظار مراجعة المعلم</p>
        <p className="text-xs text-slate-500 mt-1">{submitted.fileName}</p>
      </div>
    );
  }

  return (
    <div className="space-y-4 mt-4">
      {hw.description && <p className="text-sm text-slate-400">{hw.description}</p>}
      {hw.allowedFileTypes && (
        <p className="text-xs text-slate-500">الأنواع المسموحة: <span className="text-sky-400 font-mono">{hw.allowedFileTypes}</span></p>
      )}
      <label className="flex flex-col items-center justify-center gap-3 border-2 border-dashed border-slate-600 hover:border-sky-500 rounded-xl p-8 cursor-pointer transition-colors group">
        <span className="text-3xl">📎</span>
        <span className="text-sm text-slate-400 group-hover:text-white transition-colors">
          {file ? file.name : "اضغط لاختيار ملف أو اسحب وأفلت هنا"}
        </span>
        {file && <span className="text-xs text-slate-500">{(file.size / 1024).toFixed(1)} KB</span>}
        <input
          type="file"
          className="hidden"
          accept={hw.allowedFileTypes ? hw.allowedFileTypes.split(",").map(e => `.${e.trim()}`).join(",") : undefined}
          onChange={e => setFile(e.target.files?.[0] ?? null)}
        />
      </label>
      <button
        onClick={doSubmit}
        disabled={uploading || !file}
        className="w-full py-3 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-sm transition-colors disabled:opacity-50"
      >
        {uploading ? "⏳ جارٍ الرفع..." : "📤 رفع وإرسال"}
      </button>
    </div>
  );
}

// ─── HomeworkCard ────────────────────────────────────────────────────────────

function HomeworkCard({ hw: initHw }: { hw: HomeworkItem }) {
  const [hw, setHw] = useState(initHw);
  const [open, setOpen] = useState(false);

  const badge = statusBadge(hw.mySubmission);
  const isDone = ["passed", "failed", "pending", "review_requested"].includes(hw.mySubmission?.status ?? "");

  const handleSuccess = (sub: HWSubmission) => {
    setHw(prev => ({ ...prev, mySubmission: sub }));
  };

  return (
    <div className="rounded-2xl border border-slate-700/60 bg-slate-800/50 backdrop-blur overflow-hidden transition-all hover:border-slate-600">
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center justify-between gap-3 p-5 text-right hover:bg-slate-700/20 transition-colors"
      >
        <div className="flex items-center gap-3 min-w-0">
          <span className="text-xl shrink-0">{TYPE_LABELS[hw.type]?.split(" ")[0] ?? "📋"}</span>
          <div className="min-w-0">
            <p className="font-bold text-white truncate">{hw.title}</p>
            <p className="text-xs text-slate-500 mt-0.5 truncate">
              {hw.courseTitle && <span>{hw.courseTitle}</span>}
              {hw.lessonTitle && <span> · {hw.lessonTitle}</span>}
              {hw.dueAt && <span> · يُسلَّم {new Date(hw.dueAt).toLocaleDateString("ar-EG")}</span>}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${badge.color}`}>{badge.label}</span>
          <span className="text-xs text-slate-400 px-2 py-1 rounded-lg bg-slate-700/50">{TYPE_LABELS[hw.type]}</span>
          <svg className={`w-4 h-4 text-slate-400 transition-transform ${open ? "rotate-180" : ""}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}><polyline points="18 15 12 9 6 15" /></svg>
        </div>
      </button>

      {open && (
        <div className="border-t border-slate-700/60 px-5 pb-5">
          {isDone ? (
            <div className="mt-4 rounded-xl p-4 border border-slate-700 bg-slate-900/40 space-y-2">
              <p className="text-sm font-bold text-slate-300">تفاصيل تسليمك:</p>
              <span className={`inline-flex px-3 py-1 rounded-full text-sm font-bold ${badge.color}`}>{badge.label}</span>
              {hw.mySubmission?.score != null && (
                <p className="text-white font-bold">{hw.mySubmission.score}% ({hw.mySubmission.totalQ} سؤال)</p>
              )}
              {hw.mySubmission?.status === "review_requested" && (
                <p className="text-xs text-amber-400">🕐 إجابتك قيد المراجعة من المعلم. ستُعلَم بالنتيجة قريباً.</p>
              )}
              {hw.mySubmission?.review?.note && (
                <p className="text-xs text-slate-400">ملاحظة المعلم: {hw.mySubmission.review.note}</p>
              )}
            </div>
          ) : hw.type === "link" ? (
            <div className="mt-4">
              {hw.description && <p className="text-sm text-slate-400 mb-3">{hw.description}</p>}
              <a
                href={hw.linkUrl ?? "#"}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-sm transition-colors"
              >
                🔗 فتح الواجب
              </a>
            </div>
          ) : hw.type === "exam" ? (
            <ExamForm hw={hw} onSuccess={handleSuccess} />
          ) : hw.type === "terminal" ? (
            <TerminalForm hw={hw} onSuccess={handleSuccess} />
          ) : hw.type === "upload" ? (
            <UploadForm hw={hw} onSuccess={handleSuccess} />
          ) : null}
        </div>
      )}
    </div>
  );
}

// ─── Main Hub ────────────────────────────────────────────────────────────────

type FilterStatus = "all" | "pending" | "done" | "review_requested";

export function TeacherHomeworkHubClient({
  teacherName,
  homeworks,
}: {
  teacherName: string;
  homeworks: HomeworkItem[];
}) {
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState<FilterStatus>("all");
  const [filterCourse, setFilterCourse] = useState("all");
  const [filterType, setFilterType] = useState("all");

  const courses = useMemo(() => {
    const set = new Set(homeworks.map(h => h.courseTitle ?? "").filter(Boolean));
    return Array.from(set);
  }, [homeworks]);

  const filtered = useMemo(() => {
    return homeworks.filter(hw => {
      if (filterCourse !== "all" && hw.courseTitle !== filterCourse) return false;
      if (filterType !== "all" && hw.type !== filterType) return false;
      if (filterStatus === "pending" && hw.mySubmission) return false;
      if (filterStatus === "done" && !["passed","failed","pending"].includes(hw.mySubmission?.status ?? "")) return false;
      if (filterStatus === "review_requested" && hw.mySubmission?.status !== "review_requested") return false;
      if (search && !hw.title.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [homeworks, filterCourse, filterType, filterStatus, search]);

  const filterBtn = (val: FilterStatus, label: string, active: FilterStatus) => (
    <button
      onClick={() => setFilterStatus(val)}
      className={`px-4 py-2 rounded-xl text-sm font-bold transition-colors ${filterStatus === val ? "bg-sky-600 text-white" : "bg-slate-800 text-slate-400 hover:text-white"}`}
    >
      {label}
    </button>
  );

  return (
    <div className="min-h-screen bg-[#0d1117] text-white" dir="rtl">
      {/* Header */}
      <div className="border-b border-slate-800 bg-slate-900/80 backdrop-blur sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center justify-between gap-4">
          <div>
            <h1 className="text-xl font-black text-white">📚 واجبات {teacherName}</h1>
            <p className="text-xs text-slate-500 mt-0.5">{homeworks.length} واجب متاح لك</p>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-slate-500 font-mono">homework.code-up.tech</span>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 py-6 space-y-5">
        {/* Filters */}
        <div className="space-y-3">
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="🔍 ابحث عن واجب..."
            className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2.5 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:border-sky-500 transition-colors"
          />
          <div className="flex flex-wrap gap-2">
            {filterBtn("all", "الكل", filterStatus)}
            {filterBtn("pending", "لم يُرسل", filterStatus)}
            {filterBtn("done", "مكتمل", filterStatus)}
            {filterBtn("review_requested", "قيد المراجعة", filterStatus)}
          </div>
          <div className="flex flex-wrap gap-2">
            <select
              value={filterCourse}
              onChange={e => setFilterCourse(e.target.value)}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-sky-500"
            >
              <option value="all">كل الكورسات</option>
              {courses.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <select
              value={filterType}
              onChange={e => setFilterType(e.target.value)}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-sky-500"
            >
              <option value="all">كل الأنواع</option>
              <option value="exam">📝 اختبار</option>
              <option value="terminal">💻 كود</option>
              <option value="upload">📎 رفع ملف</option>
              <option value="link">🔗 رابط</option>
            </select>
          </div>
        </div>

        {/* Cards */}
        {filtered.length === 0 ? (
          <div className="text-center py-20">
            <p className="text-4xl mb-3">📭</p>
            <p className="text-slate-400">لا توجد واجبات تطابق الفلتر المختار</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map(hw => (
              <HomeworkCard key={hw.id} hw={hw} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { cookies } from "next/headers";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { TeacherHomeworkHubClient, type HomeworkItem } from "./TeacherHomeworkHubClient";

interface Props {
  params: Promise<{ teacherSlug: string }>;
}

/**
 * Server-rendered Homework Hub for a specific teacher.
 * URL: /homeworks/teacher/[teacherSlug]
 * (or homework.code-up.tech/[teacherSlug] after proxy rewrite)
 *
 * Access control: only show homeworks for content the student has purchased.
 */
export default async function TeacherHomeworkHubPage({ params }: Props) {
  const { teacherSlug } = await params;

  // ── Identify teacher ──────────────────────────────────────────────────────
  const teacherProfile = await prisma.teacherProfile.findUnique({
    where: { slug: teacherSlug },
    include: { teacher: { select: { id: true, name: true } } },
  });

  if (!teacherProfile) {
    return (
      <div className="min-h-screen bg-[#0d1117] flex items-center justify-center" dir="rtl">
        <div className="text-center space-y-3">
          <p className="text-5xl">😕</p>
          <p className="text-white text-xl font-bold">المعلم غير موجود</p>
          <p className="text-slate-400 text-sm">تحقق من الرابط وحاول مرة أخرى</p>
        </div>
      </div>
    );
  }

  const teacherId = teacherProfile.teacherId;
  const teacherName = teacherProfile.teacher.name;

  // ── Identify student from session cookie ─────────────────────────────────
  // We do a lightweight session check (same pattern as getSession but server-side)
  let studentId: string | null = null;
  try {
    const { getSession } = await import("@/lib/auth");
    const session = await getSession();
    if (session?.role === "student") studentId = session.id;
  } catch { /* not logged in */ }

  // ── Fetch published homeworks by this teacher ─────────────────────────────
  const rawHomeworks = await prisma.homework.findMany({
    where: { teacherId, isPublished: true },
    include: {
      questions: {
        orderBy: { order: "asc" },
        select: {
          id: true, question: true, imageUrl: true,
          optionA: true, optionB: true, optionC: true, optionD: true,
          order: true,
          // NOTE: correctAnswer intentionally excluded for students
        },
      },
      video: {
        include: {
          folder: {
            include: {
              course: { select: { id: true, title: true } },
            },
          },
        },
      },
    },
    orderBy: { createdAt: "desc" },
  });

  // ── Access control: determine which homeworks the student can see ──────────
  let accessibleHomeworkIds: Set<string> = new Set();

  if (!studentId) {
    // Not logged in — show no homeworks
    accessibleHomeworkIds = new Set();
  } else {
    // Get all course-level access codes the student has used
    const studentCodes = await prisma.accessCode.findMany({
      where: { studentId, isActive: true },
      select: { courseId: true, folderId: true, videoId: true, accessType: true },
    });

    const termCourseIds = new Set(
      studentCodes
        .filter(c => c.accessType === "TERM" || !c.accessType || (!c.folderId && !c.videoId))
        .map(c => c.courseId)
    );
    const folderAccessIds = new Set(
      studentCodes.filter(c => c.accessType === "FOLDER" && c.folderId).map(c => c.folderId!)
    );
    const videoAccessIds = new Set(
      studentCodes.filter(c => c.accessType === "VIDEO" && c.videoId).map(c => c.videoId!)
    );

    // Also check FolderPurchase, VideoPurchase, and Free Courses
    const [folderPurchases, videoPurchases, freeCourses] = await Promise.all([
      prisma.folderPurchase.findMany({ where: { studentId }, select: { folderId: true } }),
      prisma.videoPurchase.findMany({ where: { studentId }, select: { videoId: true } }),
      prisma.course.findMany({ where: { teacherId, isPaid: false }, select: { id: true } }),
    ]);
    folderPurchases.forEach(fp => folderAccessIds.add(fp.folderId));
    videoPurchases.forEach(vp => videoAccessIds.add(vp.videoId));

    const freeCourseIds = new Set(freeCourses.map(c => c.id));

    for (const hw of rawHomeworks) {
      // Free course check
      if (hw.courseId && freeCourseIds.has(hw.courseId)) {
        accessibleHomeworkIds.add(hw.id);
        continue;
      }
      if (hw.video?.folder?.courseId && freeCourseIds.has(hw.video.folder.courseId)) {
        accessibleHomeworkIds.add(hw.id);
        continue;
      }

      if (!hw.video) {
        // Course-level homework: accessible if student has TERM access to the course
        // or if homework has no courseId restriction
        if (!hw.courseId) { accessibleHomeworkIds.add(hw.id); continue; }
        if (termCourseIds.has(hw.courseId)) { accessibleHomeworkIds.add(hw.id); continue; }
      } else {
        const video = hw.video;
        const folderId = video.folderId;
        const courseId = video.folder.courseId;

        if (termCourseIds.has(courseId)) { accessibleHomeworkIds.add(hw.id); continue; }
        if (folderAccessIds.has(folderId)) { accessibleHomeworkIds.add(hw.id); continue; }
        if (videoAccessIds.has(video.id)) { accessibleHomeworkIds.add(hw.id); continue; }
      }
    }
  }

  // ── Fetch student's existing submissions ──────────────────────────────────
  const submissions = studentId
    ? await prisma.homeworkSubmission.findMany({
        where: {
          studentId,
          homeworkId: { in: Array.from(accessibleHomeworkIds) },
        },
        include: { review: { select: { verdict: true, note: true } } },
      })
    : [];

  const subMap = new Map(submissions.map(s => [s.homeworkId, s]));

  // ── Build serializable homework list ──────────────────────────────────────
  const homeworks: HomeworkItem[] = rawHomeworks
    .filter(hw => accessibleHomeworkIds.has(hw.id))
    .map(hw => {
      const sub = subMap.get(hw.id);
      return {
        id:              hw.id,
        title:           hw.title,
        description:     hw.description,
        type:            hw.type as HomeworkItem["type"],
        linkUrl:         hw.linkUrl,
        codeTemplate:    hw.codeTemplate,
        codeLanguage:    hw.codeLanguage,
        allowedFileTypes:hw.allowedFileTypes,
        dueAt:           hw.dueAt?.toISOString() ?? null,
        timeLimitMinutes:hw.timeLimitMinutes,
        isPublished:     hw.isPublished,
        courseTitle:     hw.video?.folder?.course?.title ?? undefined,
        lessonTitle:     hw.video?.title ?? undefined,
        questions:       hw.type === "exam" ? (hw.questions as HomeworkItem["questions"]) : undefined,
        mySubmission:    sub
          ? {
              id:             sub.id,
              status:         sub.status,
              score:          sub.score,
              totalQ:         sub.totalQ,
              submittedOutput:sub.submittedOutput,
              fileUrl:        sub.fileUrl,
              fileName:       sub.fileName,
              review:         sub.review ?? null,
            }
          : null,
      };
    });

  return (
    <>
      {!studentId && (
        <div className="bg-amber-600 text-white text-center text-sm py-2 px-4 font-bold">
          ⚠️ سجّل دخول أولاً لرؤية واجباتك ومتابعة تسليماتك
        </div>
      )}
      <TeacherHomeworkHubClient teacherName={teacherName} homeworks={homeworks} />
    </>
  );
}

