              ) : (
                <span className="inline-flex items-center gap-1"
                  style={{ padding: "6px 13px", borderRadius: 9, background: "var(--gold-soft)", color: "var(--gold-2)", fontSize: 13, fontWeight: 700 }}>
                  وضع المراقبة
                </span>
              )}
