                        <span className="inline-flex items-center justify-center shrink-0 font-black" style={{ width: 38, height: 38, borderRadius: "50%", background: badge.bg, color: badge.color, fontSize: 15, fontFamily: "var(--font-head)" }}>
                          {["١","٢","٣"][i] ?? i + 1}
