                })}
                {(activeTab === "points" ? topStudents : topStreakers).length === 0 && (
                  <div className="text-center py-10" style={{ color: "var(--ink-3)", fontSize: 15 }}>لا يوجد طلاب في لوحة الشرف حتى الآن.</div>
