"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Navbar } from "@/components/ui/Navbar";
import { Footer } from "@/components/ui/Footer";
import { useToast } from "@/components/ui/Toast";

type PlanLessonPreview = {
  id: string;
  title: string;
  order: number;
  requiresQuiz: boolean;
  requiresHomework: boolean;
  hasProject: boolean;
};

type PlanPreview = {
  id: string;
  title: string;
  educationalStage: string;
  description?: string | null;
  price: number;
  discountPrice: number | null;
  discountExpiresAt: string | null;
  effectivePrice: number;
  totalLessons: number;
  lessons: PlanLessonPreview[];
  hasAccess: boolean;
};

const STAGE_LABELS: Record<string, string> = {
  sec_1: "أولى بكالوريا",
  sec_2: "ثانية بكالوريا",
};

export default function PlanProductPage() {
  const router = useRouter();
  const { success: toastSuccess, error: toastError } = useToast();
  const params = useParams<{ id: string }>();
  const planId = params.id;

  const [plan, setPlan] = useState<PlanPreview | null>(null);
  const [loading, setLoading] = useState(true);
  const [fetchError, setFetchError] = useState("");
  const [user, setUser] = useState<{ name: string; role: string; phone?: string | null } | null>(null);
  const [userLoading, setUserLoading] = useState(true);
  const [code, setCode] = useState("");
  const [applying, setApplying] = useState(false);
  const [purchasing, setPurchasing] = useState(false);
  const [payMode, setPayMode] = useState<"balance" | "wallet" | "whatsapp" | "code">("wallet");
  const [walletPhone, setWalletPhone] = useState("");
  const [selectedWalletMethod, setSelectedWalletMethod] = useState<"vf_cash" | "or_cash" | "et_cash">("vf_cash");
  const [walletLoading, setWalletLoading] = useState(false);
  const [walletMsg, setWalletMsg] = useState("");
  const [walletModal, setWalletModal] = useState<{ reference: string; instructions: string; methodLabel: string; amount: number } | null>(null);

  useEffect(() => {
    fetch("/api/auth/me")
      .then(async (r) => { const raw = await r.text(); return raw ? JSON.parse(raw) : {}; })
      .then((d) => setUser(d.user ? { name: d.user.name, role: d.user.role, phone: d.user.phone ?? null } : null))
      .catch(() => setUser(null))
      .finally(() => setUserLoading(false));
  }, []);

  const loadPreview = async () => {
    if (!planId) return;
    setLoading(true);
    setFetchError("");
    try {
      const res = await fetch(`/api/plans/${planId}`);
      if (res.ok) {
        const data = await res.json();
        if (data.plan?.hasAccess) {
          router.replace(`/plans/${planId}/learn`);
          return;
        }
        setPlan(data.plan);
      } else if (res.status === 404) {
        setPlan(null);
      } else {
        setFetchError("حدث خطأ أثناء تحميل الخطة، حاول مرة أخرى");
      }
    } catch {
      setFetchError("تعذر الاتصال بالخادم، تحقق من الإنترنت وحاول مرة أخرى");
    }
    setLoading(false);
  };

  useEffect(() => {
    loadPreview();
  }, [planId]);

  const purchasePlan = async () => {
    if (!user) { router.push(`/login?redirect_url=/plans/${planId}`); return; }
    setPurchasing(true);
    try {
      const res = await fetch(`/api/plans/${planId}/purchase`, { method: "POST", credentials: "include" });
      const data = await res.json().catch(() => ({}));
      if (res.ok) {
        toastSuccess(data.message || "تم الشراء بنجاح!");
        router.push("/library");
      } else if (data.code === "INSUFFICIENT_FUNDS") {
        // Not enough balance → send the student to the Payment page to top up,
        // then they get returned here automatically after a successful payment.
        const price = typeof data.effectivePrice === "number" ? data.effectivePrice : 0;
        router.push(`/payment?amount=${price}&return=${encodeURIComponent(`/plans/${planId}`)}&context=${encodeURIComponent(`شراء خطة — ${price} جنيه`)}`);
      } else {
        toastError(data.error || "تعذر إتمام الشراء");
      }
    } catch {
      toastError("حدث خطأ أثناء الشراء");
    } finally {
      setPurchasing(false);
    }
  };

  const applyCode = async () => {
    if (!code.trim()) return;
    if (!user) { router.push("/login"); return; }
    setApplying(true);
    const res = await fetch("/api/codes", {
      method: "POST", credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ code: code.trim().toUpperCase() }),
    });
    const data = await res.json();
    setApplying(false);
    if (res.ok) {
      toastSuccess(data.message || "تم تفعيل الكود بنجاح! جارٍ الدخول...");
      router.push("/library");
    } else if (res.status === 401) {
      router.push("/login");
    } else {
      toastError(data.error || "كود غير صحيح أو منتهي الصلاحية");
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col min-h-screen bg-gray-50 dark:bg-gray-950">
        <Navbar user={user} />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-gray-400 text-lg">جارٍ التحميل...</div>
        </main>
        <Footer />
      </div>
    );
  }

  if (fetchError) {
    return (
      <div className="flex flex-col min-h-screen bg-gray-50 dark:bg-gray-950">
        <Navbar user={user} />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center space-y-4">
            <p className="text-2xl font-bold text-gray-900 dark:text-white">⚠️</p>
            <p className="text-base text-gray-700 dark:text-gray-300">{fetchError}</p>
            <div className="flex gap-3 justify-center">
              <button onClick={loadPreview} className="px-5 py-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-medium">إعادة المحاولة</button>
              <button onClick={() => router.push("/plans")} className="px-5 py-2.5 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-xl hover:bg-gray-100 dark:hover:bg-gray-800 font-medium">العودة للخطط</button>
            </div>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  if (!plan) {
    return (
      <div className="flex flex-col min-h-screen bg-gray-50 dark:bg-gray-950">
        <Navbar user={user} />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <p className="text-2xl font-bold text-gray-900 dark:text-white mb-3">الخطة غير موجودة</p>
            <button onClick={() => router.push("/plans")} className="px-5 py-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700">العودة للخطط</button>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  return (
    <div className="flex flex-col min-h-screen bg-gray-50 dark:bg-gray-950" dir="rtl">
      <Navbar user={user} />

      {/* Hero */}
      <div className="relative bg-gradient-to-br from-indigo-900 via-indigo-800 to-purple-900 text-white overflow-hidden">
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-14 md:py-20">
          <div className="max-w-2xl">
            <div className="flex flex-wrap gap-2 mb-4">
              <span className="text-xs px-3 py-1 rounded-full bg-white/10 border border-white/15">
                {STAGE_LABELS[plan.educationalStage] || plan.educationalStage}
              </span>
              <span className="text-xs px-3 py-1 rounded-full bg-purple-500/20 border border-purple-400/30 text-purple-200 font-bold">
                خطة دراسية
              </span>
            </div>
            <h1 className="text-3xl md:text-4xl font-black leading-tight mb-4">{plan.title}</h1>
            {plan.description && (() => {
              let points: string[] = [];
              try {
                if (plan.description.startsWith('[') && plan.description.endsWith(']')) {
                  points = JSON.parse(plan.description);
                } else {
                  points = plan.description.split('\n').filter(Boolean);
                }
              } catch {
                points = plan.description.split('\n').filter(Boolean);
              }
              if (points.length === 1 && points[0] === plan.description) {
                return <p className="text-white/80 text-base leading-relaxed mb-6">{plan.description}</p>;
              }
              return (
                <ul className="list-disc list-inside space-y-2 text-white/90 text-sm md:text-base mb-6 text-right max-w-xl">
                  {points.map((p, i) => (
                    <li key={i} className="leading-relaxed">{p}</li>
                  ))}
                </ul>
              );
            })()}
            <div className="flex flex-wrap gap-4 text-sm text-white/70">
              <span>📚 {plan.totalLessons} درس متسلسل</span>
              <span>✅ متابعة مستمرة</span>
              <span>🤖 تقييم بالذكاء الاصطناعي</span>
            </div>
          </div>
        </div>
      </div>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-10">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          
          {/* Left: content overview */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm overflow-hidden">
              <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700">
                <h2 className="text-lg font-bold text-gray-900 dark:text-white">مسار الخطة</h2>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">{plan.totalLessons} درس</p>
              </div>
              <ul className="divide-y divide-gray-100 dark:divide-gray-700">
                {plan.lessons.map((lesson, idx) => (
                  <li key={lesson.id} className="px-6 py-4 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-full bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm shrink-0">
                        {idx + 1}
                      </div>
                      <div>
                        <p className="font-semibold text-gray-900 dark:text-white text-sm">{lesson.title}</p>
                        <div className="flex gap-2 mt-1">
                          {lesson.requiresQuiz && <span className="text-[10px] text-orange-600 bg-orange-100 px-1.5 rounded">اختبار</span>}
                          {lesson.requiresHomework && <span className="text-[10px] text-blue-600 bg-blue-100 px-1.5 rounded">واجب</span>}
                          {lesson.hasProject && <span className="text-[10px] text-purple-600 bg-purple-100 px-1.5 rounded">مشروع AI</span>}
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </div>

          {/* Right: pricing card */}
          <div className="lg:sticky lg:top-24 h-fit">
            <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-lg overflow-hidden">
              <div className="p-6 space-y-5">
                {/* Price display */}
                {plan.effectivePrice === 0 ? (
                  <div className="flex items-center gap-2">
                    <span className="text-3xl font-black text-emerald-600 dark:text-emerald-400">مجاني</span>
                  </div>
                ) : plan.discountPrice !== null ? (
                  <div className="space-y-1">
                    <div className="flex items-end gap-3">
                      <span className="text-3xl font-black text-gray-900 dark:text-white">{plan.effectivePrice} جنيه</span>
                      <span className="text-lg text-gray-400 line-through mb-0.5">{plan.price} جنيه</span>
                    </div>
                  </div>
                ) : (
                  <div>
                    <span className="text-3xl font-black text-gray-900 dark:text-white">{plan.price} جنيه</span>
                  </div>
                )}

                {/* CTA */}
                {plan.hasAccess ? (
                  <button
                    onClick={() => router.push(`/plans/${plan.id}/learn`)}
                    className="w-full py-3 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-base transition-colors"
                  >
                    متابعة الخطة ←
                  </button>
                ) : plan.effectivePrice === 0 ? (
                  <div className="space-y-3">
                    <button
                      onClick={purchasePlan}
                      disabled={purchasing || userLoading}
                      className="w-full py-3 rounded-xl text-white font-bold text-base transition-all disabled:opacity-60 flex items-center justify-center gap-2.5 shadow-lg bg-indigo-600 hover:bg-indigo-700"
                    >
                      {purchasing ? "جارٍ التثبيت..." : "تثبيت الخطة مجانًا"}
                    </button>
                    {!userLoading && !user && (
                      <p className="text-xs text-center text-gray-500 dark:text-gray-400">
                        يلزم <button onClick={() => router.push(`/login?redirect_url=/plans/${planId}`)} className="text-indigo-600 underline">تسجيل الدخول</button> أولاً
                      </p>
                    )}
                  </div>
                ) : (
                  /* Paid plan — wallet / balance / whatsapp / code choices */
                  <div className="space-y-3">
                    {/* Pay mode toggle */}
                    <div className="grid grid-cols-2 gap-1.5 p-1 rounded-xl" style={{ background: "var(--surface-2)", border: "1px solid var(--border)" }}>
                      <button onClick={() => setPayMode("wallet")}
                        className="rounded-lg text-xs font-bold border-none cursor-pointer transition-colors py-2"
                        style={{ background: payMode === "wallet" ? "var(--brand)" : "transparent", color: payMode === "wallet" ? "#fff" : "var(--ink-3)" }}>
                        📱 محفظة إلكترونية
                      </button>
                      <button onClick={() => setPayMode("balance")}
                        className="rounded-lg text-xs font-bold border-none cursor-pointer transition-colors py-2"
                        style={{ background: payMode === "balance" ? "var(--gold-2)" : "transparent", color: payMode === "balance" ? "#fff" : "var(--ink-3)" }}>
                        💰 شراء بالرصيد
                      </button>
                      <button onClick={() => setPayMode("whatsapp")}
                        className="rounded-lg text-xs font-bold border-none cursor-pointer transition-colors py-2"
                        style={{ background: payMode === "whatsapp" ? "#25D366" : "transparent", color: payMode === "whatsapp" ? "#fff" : "var(--ink-3)" }}>
                        💬 طُرق أخرى (واتسآب)
                      </button>
                      <button onClick={() => setPayMode("code")}
                        className="rounded-lg text-xs font-bold border-none cursor-pointer transition-colors py-2"
                        style={{ background: payMode === "code" ? "var(--ink-2)" : "transparent", color: payMode === "code" ? "#fff" : "var(--ink-3)" }}>
                        🔑 كود تفعيل
                      </button>
                    </div>

                    {/* Mode 1: Mobile Wallet via Sha7nawy — redirects to the unified Payment page */}
                    {payMode === "wallet" && (
                      <div className="p-3.5 rounded-xl space-y-3" style={{ background: "var(--surface-2)", border: "1px solid var(--border)" }}>
                        <p className="text-xs text-center leading-relaxed" style={{ color: "var(--ink-2)" }}>
                          سيتم تحويلك لصفحة الدفع الموحّدة لاختيار طريقة الدفع المناسبة (فوري، كروت البنك، فودافون كاش، اتصالات كاش، أورانج كاش) وإتمام العملية بأمان.
                        </p>
                        <button onClick={() => {
                          if (!user) { router.push(`/login?redirect_url=/plans/${planId}`); return; }
                          router.push(`/payment?amount=${plan.effectivePrice}&return=${encodeURIComponent(`/plans/${planId}`)}&context=${encodeURIComponent(`شراء خطة — ${plan.effectivePrice} جنيه`)}`);
                        }} disabled={userLoading}
                          className="w-full py-2.5 rounded-xl text-white font-bold text-sm cursor-pointer border-none transition-all disabled:opacity-50 disabled:cursor-not-allowed hover:opacity-90 shadow-md"
                          style={{ background: "linear-gradient(135deg, var(--brand), var(--brand-strong))" }}>
                          الدفع عبر المحفظة 📱
                        </button>
                      </div>
                    )}

                    {/* Mode 2: Balance Purchase */}
                    {payMode === "balance" && (
                      <>
                        <button onClick={purchasePlan} disabled={purchasing || userLoading}
                          className="w-full py-3 rounded-xl text-white font-bold text-base flex items-center justify-center gap-2 transition-all disabled:opacity-60 hover:opacity-90"
                          style={{ background: "linear-gradient(135deg,var(--gold-2),#9a6a1c)" }}>
                          {purchasing ? "جارٍ الشراء..." : `شراء بـ ${plan.effectivePrice} جنيه`}
                        </button>
                        {!user && <p className="text-xs text-center text-gray-500"><button onClick={() => router.push(`/login?redirect_url=/plans/${planId}`)} className="text-indigo-600 underline">سجّل الدخول</button> أولاً</p>}
                      </>
                    )}

                    {/* Mode 3: WhatsApp Assistance */}
                    {payMode === "whatsapp" && (
                      <div className="space-y-2 text-center">
                        <p className="text-xs text-gray-500 font-medium">تواصل معنا لشراء الخطة عبر InstaPay، التحويل البنكي، أو الكاش:</p>
                        <a href={`https://wa.me/${(process.env.NEXT_PUBLIC_PAYMENT_ACCESS_PASSWORD || "+201285353604").replace(/\D/g, "")}?text=${encodeURIComponent(`مرحباً، أريد الاشتراك في خطة "${plan.title}" بسعر ${plan.effectivePrice} جنيه. اسم الطالب: ${user?.name || "غير مسجل"}`)}`}
                          target="_blank" rel="noopener noreferrer"
                          className="flex items-center justify-center gap-2 w-full py-3 rounded-xl text-white font-bold text-sm transition-colors hover:opacity-90 no-underline"
                          style={{ background: "#25D366" }}>
                          💬 تواصل للشراء عبر واتسآب
                        </a>
                      </div>
                    )}

                    {/* Mode 4: Access Code */}
                    {payMode === "code" && (
                      <div className="space-y-2">
                        <p className="text-sm font-medium text-gray-600 text-center">أدخل كود الاشتراك الخاص بالخطة:</p>
                        <div className="flex gap-2">
                          <input type="text" value={code} onChange={e => setCode(e.target.value.toUpperCase())}
                            onKeyDown={e => e.key === "Enter" && applyCode()} placeholder="كود الوصول" maxLength={16} dir="ltr"
                            className="flex-1 rounded-xl px-3 py-2.5 text-center font-mono text-sm tracking-widest focus:outline-none border border-gray-200" />
                          <button onClick={applyCode} disabled={applying || !code.trim()}
                            className="rounded-xl px-4 py-2.5 text-white font-bold text-sm bg-indigo-600 hover:bg-indigo-700 transition-colors disabled:opacity-50">
                            {applying ? "..." : "تفعيل"}
                          </button>
                        </div>
                        {!user && <p className="text-xs text-center text-gray-500"><button onClick={() => router.push("/login")} className="text-indigo-600 underline">سجّل الدخول</button> أولاً</p>}
                      </div>
                    )}
                  </div>
                )}

                {/* Sha7nawy Instruction Modal */}
                {walletModal && (
                  <div className="fixed inset-0 z-[var(--z-modal)] flex items-center justify-center p-4" style={{ background: "rgba(0,0,0,.6)" }} onClick={() => setWalletModal(null)}>
                    <div className="w-full max-w-md rounded-2xl p-6 text-center space-y-4 shadow-2xl" style={{ background: "var(--surface)", border: "1px solid var(--border)" }} onClick={e => e.stopPropagation()}>
                      <div className="text-4xl">📲</div>
                      <h3 className="text-lg font-bold" style={{ color: "var(--ink)" }}>تم إرسال طلب الخصم بنجاح!</h3>
                      <p className="text-xs text-gray-500 font-mono">رقم المرجع: {walletModal.reference}</p>
                      
                      <div className="p-4 rounded-xl space-y-2 text-right text-sm" style={{ background: "var(--surface-2)", border: "1px solid var(--border)" }}>
                        <p className="font-bold text-center" style={{ color: "var(--brand)" }}>تعليمات إتمام العملية:</p>
                        <p className="text-xs leading-relaxed" style={{ color: "var(--ink-2)" }}>{walletModal.instructions}</p>
                      </div>

                      <div className="pt-2 space-y-2">
                        <button onClick={async () => {
                          setWalletLoading(true);
                          try {
                            const res = await fetch("/api/payments/sha7nawy/confirm", {
                              method: "POST", credentials: "include",
                              headers: { "Content-Type": "application/json" },
                              body: JSON.stringify({ ref_code: walletModal.reference }),
                            });
                            const d = await res.json().catch(() => ({}));
                            setWalletLoading(false);
                            if (res.ok && d.success) {
                              setWalletModal(null);
                              toastSuccess("تم تأكيد السحب وشحن حسابك بنجاح!");
                            } else {
                              setWalletMsg(`⚠️ ${d.error || "العملية معلقة بانتظار موافقة العميل من المحفظة"}`);
                            }
                          } catch {
                            setWalletLoading(false);
                            setWalletMsg("❌ تعذر الاتصال بسيرفر التأكيد");
                          }
                        }} disabled={walletLoading}
                          className="w-full py-3 rounded-xl text-white font-bold text-sm cursor-pointer border-none transition-all hover:opacity-90 shadow-md"
                          style={{ background: "linear-gradient(135deg, var(--brand), var(--brand-strong))" }}>
                          {walletLoading ? "جارٍ التحقق والتأكيد..." : "تأكيد واستعلام حالة الدفع 🔄"}
                        </button>

                        <button onClick={() => setWalletModal(null)}
                          className="w-full py-2.5 rounded-xl text-xs font-bold border cursor-pointer transition-colors"
                          style={{ background: "var(--surface-2)", border: "1px solid var(--border)", color: "var(--ink-2)" }}>
                          إغلاق النافذة
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

        </div>
      </main>
      <Footer />
    </div>
  );
}

"use client";
import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence, MotionConfig } from "framer-motion";
import Link from "next/link";
import { Navbar } from "@/components/ui/Navbar";
import { Footer } from "@/components/ui/Footer";
import { SkeletonCard } from "@/components/ui/Skeleton";

const STAGES = [
  { value: "all", label: "الكل" },
  { value: "sec_1", label: "أولى بكالوريا" },
  { value: "sec_2", label: "ثانية بكالوريا" },
];

const STAGE_LABELS: Record<string, string> = {
  sec_1: "أولى بكالوريا",
  sec_2: "ثانية بكالوريا",
};

const DEFAULT_PLAN_FEATURES = [
  "تغطية منهجية متكاملة لجميع دروس الشهر",
  "مشاريع وتطبيقات عمليّة لتثبيت الشرح",
  "كويزات تقييمية وتدريبات واختبارات دورية",
  "مساعد ذكي متكامل للإجابة على التساؤلات 24/7",
  "متابعة دقيقة لمستوى التقدم والدرجات",
];

const parseDescription = (desc?: string): string[] => {
  if (!desc) return DEFAULT_PLAN_FEATURES;
  try {
    if (desc.startsWith("[") && desc.endsWith("]")) {
      const parsed = JSON.parse(desc);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch {}
  const split = desc.split("\n").map((s) => s.trim()).filter(Boolean);
  return split.length > 0 ? split : DEFAULT_PLAN_FEATURES;
};

const EASE: [number, number, number, number] = [0.16, 1, 0.3, 1];

export default function PlansPage() {
  const [plans, setPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedStage, setSelectedStage] = useState<string>("all");
  const [user, setUser] = useState<{ name: string; role: string; educationalStage?: string | null } | null>(null);

  useEffect(() => {
    fetch("/api/auth/me")
      .then(async (r) => {
        const raw = await r.text();
        return raw ? JSON.parse(raw) : {};
      })
      .then((d) => {
        if (d.user) {
          setUser({ name: d.user.name, role: d.user.role, educationalStage: d.user.educationalStage });
          if (d.user.educationalStage) {
            setSelectedStage(d.user.educationalStage);
          }
        }
      })
      .catch(() => setUser(null));
  }, []);

  const fetchPlans = useCallback(async (stage: string) => {
    setLoading(true);
    setError("");

    try {
      const url = `/api/plans${stage && stage !== "all" ? `?stage=${stage}` : "?stage=all"}`;
      const res = await fetch(url);
      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        throw new Error(data.error || "فشل تحميل الخطط الدراسية");
      }

      setPlans(data.plans || []);
    } catch (err) {
      console.error("Fetch plans error:", err);
      setPlans([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => fetchPlans(selectedStage), 150);
    return () => window.clearTimeout(t);
  }, [selectedStage, fetchPlans]);

  const hasNoPlans = !loading && plans.length === 0;

  return (
    <MotionConfig reducedMotion="user">
      <div className="flex flex-col min-h-screen" style={{ background: "var(--bg)" }} dir="rtl">
        <Navbar user={user} />
        
        {!hasNoPlans && (
          <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-10 md:py-12">
            {/* Header */}
            <motion.div
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.55, ease: EASE }}
              className="mb-8 md:mb-10 text-center"
            >
              <span
                className="inline-block px-3 py-1 mb-3 text-xs font-bold rounded-full"
                style={{ color: "#14B8A6", background: "rgba(20,184,166,0.1)", border: "1px solid rgba(20,184,166,0.25)" }}
              >
                الخيار الأشمل والأنسب للتفوق
              </span>
              <h1 className="text-balance text-3xl md:text-4xl lg:text-5xl font-black tracking-tight mb-3" style={{ color: "var(--ink)", fontFamily: "var(--font-head)" }}>
                الخطط الدراسية المنفذة بالمنصة
              </h1>
              <p className="text-base max-w-2xl mx-auto leading-relaxed" style={{ color: "var(--ink-2)" }}>
                مسارات تعليمية متكاملة مصممة خصيصًا لتغطية المنهج بالشرح، التطبيقات العملية، الاختبارات التقييمية، ومتابعة الذكاء الاصطناعي المستمرة.
              </p>
            </motion.div>

            {/* ── Sticky Grade Filter Tabs ── */}
            <div className="sticky top-[60px] sm:top-[74px] z-[var(--z-dropdown)] mb-8 flex items-center justify-center">
              <div className="flex flex-wrap gap-2 justify-center p-1.5 rounded-2xl max-w-4xl"
                style={{ background: "var(--surface)", border: "1px solid var(--border)", boxShadow: "var(--shadow-sm)" }}>
                {STAGES.map((st) => {
                  const isActive = selectedStage === st.value;
                  return (
                    <button
                      key={st.value}
                      onClick={() => setSelectedStage(st.value)}
                      className="px-4 py-2 text-xs font-bold rounded-xl transition-all border-none cursor-pointer"
                      style={{
                        background: isActive ? "#14B8A6" : "transparent",
                        color: isActive ? "#0B0F19" : "var(--ink-2)",
                        fontWeight: isActive ? 800 : 600,
                        boxShadow: isActive ? "0 4px 14px -4px rgba(20,184,166,0.4)" : "none",
                        fontFamily: "var(--font-body)",
                      }}
                    >
                      {st.label}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Results Summary */}
            {!loading && plans.length > 0 && (
              <div className="mb-6 flex items-center justify-between gap-3 px-2">
                <p className="text-sm" style={{ color: "var(--ink-2)" }}>
                  الخطط المتاحة: <span className="font-bold" style={{ color: "var(--ink)" }}>{plans.length.toLocaleString("ar-EG")}</span> خطة
                </p>
                {selectedStage !== "all" && (
                  <button
                    onClick={() => setSelectedStage("all")}
                    className="text-xs font-bold border-none bg-transparent cursor-pointer hover:underline"
                    style={{ color: "#14B8A6" }}
                  >
                    عرض جميع المراحل الدراسية
                  </button>
                )}
              </div>
            )}

            {error && (
              <div className="mb-6 flex flex-col sm:flex-row items-center justify-between gap-3 rounded-2xl px-5 py-4 text-sm"
                style={{ border: "1px solid var(--danger)", background: "var(--danger-soft)", color: "var(--danger)" }}>
                <span>{error}</span>
                <button
                  onClick={() => fetchPlans(selectedStage)}
                  className="shrink-0 rounded-lg px-4 py-2 text-xs font-bold text-white border-none cursor-pointer hover:opacity-90"
                  style={{ background: "var(--danger)" }}
                >
                  إعادة المحاولة
                </button>
              </div>
            )}

            {/* Plans Grid */}
            {loading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {Array.from({ length: 3 }).map((_, i) => (
                  <SkeletonCard key={i} />
                ))}
              </div>
            ) : (
              <motion.div layout className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <AnimatePresence mode="popLayout" initial={false}>
                  {plans.map((plan, i) => {
                    const points = parseDescription(plan.description);
                    const isFeatured = i === 0;

                    return (
                      <motion.div
                        key={plan.id}
                        layout
                        initial={{ opacity: 0, y: 16, scale: 0.97 }}
                        animate={{
                          opacity: 1,
                          y: 0,
                          scale: 1,
                          transition: { duration: 0.32, ease: EASE, delay: Math.min(i * 0.04, 0.32) },
                        }}
                        exit={{ opacity: 0, scale: 0.96, transition: { duration: 0.16 } }}
                        className="h-full"
                      >
                        <div
                          className="relative flex flex-col h-full rounded-2xl p-6 md:p-8 transition-all duration-300 text-right"
                          style={{
                            background: "var(--surface)",
                            border: isFeatured ? "1px solid rgba(20,184,166,0.5)" : "1px solid var(--border)",
                            boxShadow: isFeatured ? "0 0 30px -5px rgba(20,184,166,0.2)" : "var(--shadow-sm)",
                          }}
                          onMouseEnter={e => { if (!isFeatured) (e.currentTarget as HTMLElement).style.boxShadow = "var(--shadow-lg)"; }}
                          onMouseLeave={e => { if (!isFeatured) (e.currentTarget as HTMLElement).style.boxShadow = "var(--shadow-sm)"; }}
                        >
                          {isFeatured && (
                            <span className="absolute -top-3 left-6 px-3 py-1 text-[10px] font-black tracking-widest rounded-full uppercase"
                              style={{ color: "#14B8A6", background: "rgba(20,184,166,0.1)", border: "1px solid rgba(20,184,166,0.3)" }}>
                              مستحسنة ومتكاملة ⭐
                            </span>
                          )}

                          {/* Plan Stage & Month Badges */}
                          <div className="flex flex-wrap items-center gap-2 mb-4">
                            <span className="px-2.5 py-1 text-[11px] font-bold rounded-lg"
                              style={{ background: "rgba(20,184,166,0.1)", color: "#14B8A6", border: "1px solid rgba(20,184,166,0.25)" }}>
                              {STAGE_LABELS[plan.educationalStage] || plan.educationalStage}
                            </span>
                            <span className="px-2.5 py-1 text-[11px] font-bold rounded-lg"
                              style={{ background: "var(--gold-soft)", color: "var(--gold-2)", border: "1px solid var(--gold-2)" }}>
                              الشهر {plan.monthIndex || 1}
                            </span>
                            <span className="px-2.5 py-1 text-[11px] font-bold rounded-lg"
                              style={{ background: "rgba(16,185,129,0.1)", color: "#10B981", border: "1px solid rgba(16,185,129,0.25)" }}>
                              {plan._count?.lessons || 10} درساً
                            </span>
                          </div>

                          {/* Plan Title */}
                          <div className="mb-4">
                            <h3 className="text-xl font-bold leading-snug mb-2" style={{ color: "var(--ink)" }}>{plan.title}</h3>
                          </div>

                          {/* Price Area */}
                          <div className="flex items-baseline gap-1 mb-6 pb-5" style={{ borderBottom: "1px solid var(--border)" }}>
                            {plan.effectivePrice === 0 ? (
                              <span className="text-3xl font-black" style={{ color: "#10B981" }}>مجاناً بالكامل</span>
                            ) : (
                              <>
                                <span className="text-3xl font-black tracking-tight" style={{ color: "var(--ink)" }}>{plan.effectivePrice}</span>
                                <span className="text-sm font-bold" style={{ color: "var(--ink-2)" }}>جنيه مصري</span>
                                <span className="text-xs font-bold mr-1" style={{ color: "var(--ink-3)" }}>/ {plan.durationDays || 30} يوم</span>
                              </>
                            )}
                          </div>

                          {/* Roadmap Timeline */}
                          <div className="mb-4 flex items-center gap-2 text-xs font-bold" style={{ color: "var(--ink-2)" }}>
                            <span className="px-2 py-1 rounded-lg" style={{ background: "rgba(20,184,166,0.1)", color: "#14B8A6" }}>المرحلة 1: أساسيات</span>
                            <span style={{ color: "var(--ink-3)" }}>➔</span>
                            <span className="px-2 py-1 rounded-lg" style={{ background: "rgba(245,158,11,0.1)", color: "#F59E0B" }}>المرحلة 2: التطبيقات</span>
                          </div>

                          {/* Features */}
                          <div className="space-y-4 flex-1 mb-8">
                            <p className="text-[11px] font-bold uppercase tracking-widest" style={{ color: "var(--ink-3)" }}>مواصفات الخطة الدراسية:</p>
                            <ul className="space-y-3">
                              {points.map((pt: string, idx: number) => (
                                <li key={idx} className="flex gap-2.5 items-start text-xs leading-relaxed" style={{ color: "var(--ink-2)" }}>
                                  <span className="font-black shrink-0 mt-0.5" style={{ color: "#10B981" }}>✓</span>
                                  <span>{pt}</span>
                                </li>
                              ))}
                            </ul>
                          </div>

                          {/* Action Button */}
                          <div className="mt-auto">
                            <Link
                              href={plan.hasAccess ? `/plans/${plan.id}/learn` : `/plans/${plan.id}`}
                              className="w-full py-3.5 px-4 rounded-xl text-xs font-bold transition-all text-center block no-underline"
                              style={plan.hasAccess ? {
                                background: "linear-gradient(135deg, #10B981, #14B8A6)",
                                color: "#fff",
                                boxShadow: "0 4px 14px -4px rgba(16,185,129,0.4)",
                              } : plan.effectivePrice === 0 ? {
                                background: "#10B981",
                                color: "#fff",
                                boxShadow: "0 4px 14px -4px rgba(16,185,129,0.4)",
                              } : {
                                background: "var(--ink)",
                                color: "var(--bg)",
                                fontWeight: 800,
                                boxShadow: "var(--shadow)",
                              }}
                            >
                              {plan.hasAccess ? "متابعة التعلم في الخطة ➔" : "عرض تفاصيل الخطة والاشتراك ➔"}
                            </Link>
                          </div>
                        </div>
                      </motion.div>
                    );
                  })}
                </AnimatePresence>
              </motion.div>
            )}
          </main>
        )}

        {/* ── Empty State — Human, Clean & Intentional ── */}
        {hasNoPlans && (
          <main className="flex-1 max-w-2xl mx-auto w-full px-4 py-16 text-center flex flex-col items-center justify-center">
            <motion.div
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4 }}
              className="p-8 md:p-10 rounded-3xl text-center max-w-md w-full bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 shadow-sm"
            >
              {/* Friendly Icon Badge */}
              <div className="w-16 h-16 rounded-2xl bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-2xl mx-auto mb-5 border border-emerald-100 dark:border-emerald-900/30">
                📚
              </div>

              <h2 className="text-xl md:text-2xl font-bold mb-2 text-gray-900 dark:text-white">
                لا تتوفر خطط دراسية جديدة حالياً
              </h2>
              <p className="text-sm text-gray-600 dark:text-gray-400 mb-6 leading-relaxed">
                يعمل فريق معلمينا الخبراء على تجهيز المسارات والخطط الدراسية للمرحلة المحددة. يمكنك تصفح جميع الكورسات المتاحة الآن أو العودة لاحقاً.
              </p>

              <div className="flex flex-col sm:flex-row items-center justify-center gap-3">
                <Link
                  href="/courses"
                  className="w-full sm:w-auto px-6 py-2.5 rounded-xl text-xs font-extrabold text-white bg-emerald-600 hover:bg-emerald-700 transition-colors no-underline shadow-sm"
                >
                  تصفح جميع الكورسات ➔
                </Link>
                {selectedStage !== "all" && (
                  <button
                    type="button"
                    onClick={() => setSelectedStage("all")}
                    className="w-full sm:w-auto px-5 py-2.5 rounded-xl text-xs font-bold text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 border-none cursor-pointer transition-colors"
                  >
                    عرض كل المراحل
                  </button>
                )}
              </div>
            </motion.div>
          </main>
        )}

        <Footer />
      </div>
    </MotionConfig>
  );
}

"use client";

import { useMemo, useState, useRef, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { AuthShell } from "@/components/auth/AuthShell";
import { EDUCATIONAL_STAGES } from "@/types";
import { useRecaptcha } from "@/lib/use-recaptcha";

export default function SignupPage() {
  const router = useRouter();
  // Read referral code from ?ref= query param
  const [refCode] = useState<string>(() => {
    if (typeof window === "undefined") return "";
    return new URLSearchParams(window.location.search).get("ref") ?? "";
  });
  const [form, setForm] = useState({
    name: "",
    phone: "",
    parentPhone: "",
    age: "",
    educationalStage: "",
    password: "",
    confirmPassword: "",
    verificationCode: "",
    promoCode: "",
  });
  const [sendingCode, setSendingCode] = useState(false);
  const [signingUp, setSigningUp] = useState(false);
  const [codeSent, setCodeSent] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [codeMethod, setCodeMethod] = useState<"sms" | "verify" | "dev">("sms");
  const [isBypassed, setIsBypassed] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [sentChannel, setSentChannel] = useState<"whatsapp" | "sms" | null>(null);
  const { execute: executeRecaptcha } = useRecaptcha();

  useEffect(() => {
    if (cooldown <= 0) return;
    const timer = setInterval(() => {
      setCooldown((c) => c - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [cooldown]);

  const canSendCode = useMemo(() => form.phone.trim().length >= 9, [form.phone]);

  // sanitize phone for sending: always return E.164 (+20...) when possible
  const formatForSend = (p: string) => {
    const raw = String(p || "");
    const digits = raw.replace(/\D/g, "");
    // already in international with country code
    if (digits.startsWith("20") && digits.length === 12) return `+${digits}`;
    // local 01XXXXXXXXX -> +20XXXXXXXXXX
    if (digits.startsWith("0") && digits.length === 11) return `+20${digits.slice(1)}`;
    // if user provided 9-digit (without leading 0), assume local and add +20
    if (digits.length === 9) return `+20${digits}`;
    // if it already includes leading + and looks valid
    if (raw.startsWith("+")) return raw;
    return raw;
  };

  const sendCode = async (forceSms?: boolean) => {
    if (!canSendCode) {
      setError("أدخل رقم المتعلم أولاً");
      return;
    }

    setSendingCode(true);
    setError("");
    setSuccess("");

    try {
      // Get a reCAPTCHA token for the send_code action.
      const recaptchaToken = await executeRecaptcha("send_code");

      const response = await fetch("/api/auth/phone/send-code", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: formatForSend(form.phone), forceChannel: forceSms ? "sms" : undefined, recaptchaToken }),
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        setError(data.error || "فشل إرسال الكود");
        return;
      }

      if (data?.bypass) {
        setIsBypassed(true);
        setCodeSent(true);
        setCodeMethod("dev");
        setSentChannel("sms");
        setForm((s) => ({ ...s, verificationCode: "123456" }));
        setSuccess("وضع التطوير مفعّل: تم تخطي التحقق من رقم الهاتف (DEV).");
        return;
      }

      setIsBypassed(false);
      setCodeSent(true);
      setSentChannel(data?.channel === "whatsapp" ? "whatsapp" : "sms");
      setSuccess(
        data?.channel === "whatsapp"
          ? "تم إرسال رمز التحقق إلى حساب WhatsApp الخاص بك. يرجى التحقق من تطبيق واتساب."
          : "تم إرسال رمز التحقق عبر الرسائل النصية (SMS). يرجى التحقق من الرسائل النصية على هاتفك."
      );
      setCooldown(60);
    } catch (err: any) {
      console.error("sendCode error:", err);
      const errCode = err?.code ? ` [${err.code}]` : "";
      setError((err?.message || "تعذر إرسال كود التحقق. حاول مرة أخرى.") + errCode);
    } finally {
      setSendingCode(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSigningUp(true);
    setError("");
    setSuccess("");

    if (form.password !== form.confirmPassword) {
      setError("كلمتا المرور غير متطابقتين");
      setSigningUp(false);
      return;
    }

    if (!codeSent) {
      setError("يجب إرسال رمز التحقق أولاً");
      setSigningUp(false);
      return;
    }

    try {
      const response = await fetch("/api/auth/signup", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          phone: formatForSend(form.phone),
          parentPhone: formatForSend(form.parentPhone),
          age: form.age,
          educationalStage: form.educationalStage,
          password: form.password,
          verificationCode: form.verificationCode,
          referralCode: refCode || undefined,
          promoCode: form.promoCode ? form.promoCode.trim() : undefined,
        }),
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        setError(data.error || "تعذر إنشاء الحساب");
        return;
      }

      router.push("/");
      router.refresh();
    } catch (err) {
      console.error("Signup submit error:", err);
      setError("حدث خطأ في الاتصال بالخادم.");
    } finally {
      setSigningUp(false);
    }
  };

  return (
    <AuthShell
      title="إنشاء حساب جديد"
      subtitle="سجل بيانات المتعلم كاملة لبدء التعلم فورًا"
      maxWidth="2xl"
      footer={
        <>
          لديك حساب بالفعل؟{" "}
          <Link href="/login" className="text-sky-600 dark:text-sky-400 font-semibold hover:underline">
            تسجيل الدخول
          </Link>
        </>
      }
    >
      <div className="space-y-5">
        {error && (
          <div className="mb-5 p-3 rounded-xl border border-red-200 bg-red-50 text-red-700 text-sm dark:border-red-800 dark:bg-red-950/40 dark:text-red-300">
            {error}
          </div>
        )}
        {success && (
          <div className="mb-5 p-3 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-700 text-sm dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300">
            {success}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="rounded-2xl border border-white/10 bg-slate-950/10 p-4 sm:p-5 dark:bg-white/5">
            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">اسم المتعلم</label>
                <input
                  type="text"
                  required
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                  placeholder="أحمد محمد"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">العمر</label>
                <input
                  type="number"
                  min={6}
                  max={25}
                  required
                  value={form.age}
                  onChange={(e) => setForm({ ...form, age: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                  placeholder="15"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">رقم المتعلم</label>
                <input
                  type="tel"
                  dir="ltr"
                  required
                  value={form.phone}
                  onChange={(e) => setForm({ ...form, phone: e.target.value.replace(/[^\d+]/g, "") })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500 text-left"
                  placeholder="01XXXXXXXXX"
                />
                <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">اكتب الرقم المصري بصيغة 01XXXXXXXXX أو +20XXXXXXXXXX</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">رقم ولي الأمر</label>
                <input
                  type="tel"
                  dir="ltr"
                  required
                  value={form.parentPhone}
                  onChange={(e) => setForm({ ...form, parentPhone: e.target.value.replace(/[^\d+]/g, "") })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500 text-left"
                  placeholder="01XXXXXXXXX"
                />
                <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">لا تستخدم نفس الرقم للمتعلم وولي الأمر</p>
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">كود خصم المعلم (اختياري)</label>
                <input
                  type="text"
                  value={form.promoCode}
                  onChange={(e) => setForm({ ...form, promoCode: e.target.value.toUpperCase() })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500 font-mono"
                  placeholder="إذا كان لديك كود إحالة من معلمك (مثال: 123)"
                />
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">الصف التدريبي</label>
                <select
                  required
                  value={form.educationalStage}
                  onChange={(e) => setForm({ ...form, educationalStage: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                >
                  <option value="">— اختر الصف التدريبي —</option>
                  {EDUCATIONAL_STAGES.map((stage) => (
                    <option key={stage.value} value={stage.value}>
                      {stage.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">كلمة المرور</label>
                <input
                  type="password"
                  required
                  minLength={8}
                  value={form.password}
                  onChange={(e) => setForm({ ...form, password: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                  placeholder="8 أحرف أو أكثر"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">تأكيد كلمة المرور</label>
                <input
                  type="password"
                  required
                  minLength={8}
                  value={form.confirmPassword}
                  onChange={(e) => setForm({ ...form, confirmPassword: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                  placeholder="أعد كتابة كلمة المرور"
                />
              </div>

              <div className="md:col-span-2 rounded-xl border border-sky-200/60 bg-sky-50/70 p-4 text-sm text-sky-900 dark:border-sky-900/60 dark:bg-sky-950/30 dark:text-sky-200">
                {codeMethod === "verify" && "سيتم إرسال الرمز عبر Twilio Verify. أفضل خيار للإنتاج."}
                {codeMethod === "dev" && "وضع التطوير مفعّل: الكود محفوظ محليًا لتجربة التسجيل بدون SMS."}
                {!codeSent && codeMethod !== "dev" && codeMethod !== "verify" && "سيتم إرسال كود التحقق عبر WhatsApp كقناة أساسية، أو عبر SMS كقناة احتياطية."}
                {codeSent && sentChannel === "whatsapp" && "تم إرسال الرمز عبر WhatsApp إلى رقم المتعلم."}
                {codeSent && sentChannel === "sms" && "تم إرسال الرمز عبر SMS مباشرة إلى رقم المتعلم."}
                {codeSent && sentChannel === "whatsapp" && (
                  <div className="mt-2 pt-2 border-t border-sky-200/40 dark:border-sky-900/40">
                    <button
                      type="button"
                      onClick={() => sendCode(true)}
                      disabled={sendingCode}
                      className="text-xs text-sky-700 dark:text-sky-300 underline font-semibold hover:text-sky-900 dark:hover:text-white cursor-pointer"
                    >
                      لم أستلم الرمز على واتساب؟ الإرسال عبر SMS بدلاً من ذلك
                    </button>
                  </div>
                )}
              </div>

              <div id="recaptcha-container"></div>

              <div className="md:col-span-2 grid sm:grid-cols-[1fr_auto] gap-3 items-end">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">رمز التحقق</label>
                  <input
                    type="text"
                    required
                    value={form.verificationCode}
                    onChange={(e) => setForm({ ...form, verificationCode: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-sky-500"
                    placeholder="أدخل الكود المرسل"
                  />
                </div>
                <button
                  type="button"
                  onClick={() => sendCode()}
                  disabled={sendingCode || !canSendCode || cooldown > 0}
                  className="h-12 px-5 rounded-xl bg-slate-900 text-white hover:bg-slate-700 disabled:opacity-50 dark:bg-white dark:text-slate-950 dark:hover:bg-slate-200"
                >
                  {sendingCode ? "جارٍ الإرسال..." : cooldown > 0 ? `إعادة الإرسال خلال ${cooldown}ث` : codeSent ? "إعادة إرسال الكود" : "إرسال كود التحقق"}
                </button>
              </div>
              {codeSent && (
                <div className="md:col-span-2 text-center text-xs text-slate-500 dark:text-slate-400 mt-1">
                  تحتاج مساعدة؟ تواصل مع الدعم:{" "}
                  <a
                    href="tel:+201282287267"
                    className="text-sky-600 dark:text-sky-400 font-semibold hover:underline"
                  >
                    01282287267
                  </a>
                </div>
              )}
            </div>
          </div>

          <button
            type="submit"
            disabled={signingUp}
            className="w-full py-3.5 bg-gradient-to-l from-sky-600 to-blue-700 hover:from-sky-700 hover:to-blue-800 disabled:opacity-60 text-white font-bold rounded-2xl transition-all shadow-lg shadow-sky-950/20"
          >
            {signingUp ? "جاري إنشاء الحساب..." : "إنشاء الحساب"}
          </button>
          <p className="text-center text-xs text-slate-500 dark:text-slate-400 mt-4">
            بإنشائك للحساب فإنك توافق على{" "}
            <Link href="/terms" className="text-sky-600 dark:text-sky-400 hover:underline">
              شروط الاستخدام
            </Link>{" "}
            و{" "}
            <Link href="/privacy" className="text-sky-600 dark:text-sky-400 hover:underline">
              سياسة الخصوصية
            </Link>
          </p>
        </form>
      </div>
    </AuthShell>
  );
}

