"use client";

import { useCallback, useEffect, useState } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface Submission {
  id: string;
  studentId: string;
  student: { id: string; name: string; email: string };
  submittedOutput?: string | null;
  fileUrl?: string | null;
  fileName?: string | null;
  status: string;
  completedAt: string;
  review?: { verdict?: string | null; note?: string | null } | null;
}

interface HwWithSubs {
  id: string;
  title: string;
  type: string;
  expectedOutput?: string | null;
  reviewQueueCount?: number;
  submissions?: Submission[];
}

// ─── LiveReviewPanel ──────────────────────────────────────────────────────────

export function LiveReviewPanel({ notify }: { notify: (t: "success" | "error", m: string) => void }) {
  const [homeworks, setHomeworks] = useState<HwWithSubs[]>([]);
  const [selected, setSelected] = useState<HwWithSubs | null>(null);
  const [subs, setSubs] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(false);
  const [verdicting, setVerdicting] = useState<string | null>(null);
  const [noteMap, setNoteMap] = useState<Record<string, string>>({});

  const fetchHomeworks = useCallback(async () => {
    const res = await fetch("/api/admin/homework", { credentials: "include" });
    const data = await res.json();
    const filtered = (data.homeworks || []).filter((h: HwWithSubs) => (h.reviewQueueCount ?? 0) > 0 || h.type === "terminal");
    setHomeworks(data.homeworks || []);
  }, []);

  useEffect(() => { void fetchHomeworks(); }, [fetchHomeworks]);

  const loadReview = async (hw: HwWithSubs) => {
    setSelected(hw);
    setLoading(true);
    try {
      const res = await fetch(`/api/homework/${hw.id}/review`, { credentials: "include" });
      const data = await res.json();
      setSubs(data.submissions || []);
    } finally { setLoading(false); }
  };

  const verdict = async (sub: Submission, v: "passed" | "failed") => {
    setVerdicting(sub.id);
    try {
      const res = await fetch(`/api/homework/${selected!.id}/review`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ submissionId: sub.id, verdict: v, note: noteMap[sub.id] || "" }),
      });
      const data = await res.json();
      if (res.ok) {
        notify("success", v === "passed" ? "تم قبول الإجابة ✅" : "تم رفض الإجابة ❌");
        setSubs(s => s.filter(x => x.id !== sub.id));
      } else {
        notify("error", data.error || "تعذر حفظ الحكم");
      }
    } finally { setVerdicting(null); }
  };

  const pendingTotal = homeworks.reduce((s, h) => s + (h.reviewQueueCount ?? 0), 0);

  const input = "w-full px-3 py-2 rounded-xl border border-[var(--border)] bg-[var(--bg)] text-[var(--ink)] text-sm focus:outline-none focus:border-sky-400/60 transition-all";

  return (
    <div className="space-y-5">
      <div className="flex items-center gap-3">
        <h2 className="text-lg font-black text-[var(--ink)]">🔍 مراجعة الإجابات المعلقة</h2>
        {pendingTotal > 0 && (
          <span className="bg-amber-500/15 text-amber-500 text-xs font-bold px-2.5 py-1 rounded-full">
            {pendingTotal} في الانتظار
          </span>
        )}
      </div>

      {!selected ? (
        <div className="space-y-3">
          {homeworks.length === 0 ? (
            <div className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-12 text-center">
              <p className="text-4xl mb-3">✅</p>
              <p className="text-[var(--ink-muted)]">لا توجد إجابات تحتاج مراجعة</p>
            </div>
          ) : (
            homeworks.map(hw => (
              <button
                key={hw.id}
                onClick={() => loadReview(hw)}
                className="w-full bg-[var(--surface)] border border-[var(--border)] hover:border-sky-400/50 rounded-2xl p-4 flex items-center justify-between gap-3 text-right transition-colors"
              >
                <div>
                  <p className="font-bold text-[var(--ink)]">{hw.title}</p>
                  <p className="text-xs text-[var(--ink-muted)] mt-0.5">{hw.type === "terminal" ? "💻 كود" : hw.type}</p>
                </div>
                <span className={`text-xs font-bold px-2.5 py-1 rounded-full shrink-0 ${(hw.reviewQueueCount ?? 0) > 0 ? "bg-amber-500/15 text-amber-500" : "bg-slate-500/15 text-[var(--ink-muted)]"}`}>
                  {hw.reviewQueueCount ?? 0} معلق
                </span>
              </button>
            ))
          )}
        </div>
      ) : (
        <div className="space-y-4">
          <button onClick={() => setSelected(null)} className="text-sm text-sky-500 hover:underline flex items-center gap-1">
            ← العودة لقائمة الواجبات
          </button>
          <h3 className="font-bold text-[var(--ink)]">{selected.title} — الإجابات المعلقة</h3>

          {selected.expectedOutput && (
            <div className="bg-[var(--surface)] border border-[var(--border)] rounded-xl p-4">
              <p className="text-xs font-bold text-[var(--ink-muted)] mb-1">الناتج المتوقع (المرجع):</p>
              <pre className="text-sm text-emerald-400 font-mono whitespace-pre-wrap">{selected.expectedOutput}</pre>
            </div>
          )}

          {loading ? (
            <div className="text-center py-8 text-[var(--ink-muted)]">جارٍ التحميل...</div>
          ) : subs.length === 0 ? (
            <div className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-12 text-center">
              <p className="text-4xl mb-2">✅</p>
              <p className="text-[var(--ink-muted)]">لا توجد إجابات معلقة لهذا الواجب</p>
            </div>
          ) : (
            subs.map(sub => (
              <div key={sub.id} className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-5 space-y-3">
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <p className="font-bold text-[var(--ink)]">{sub.student.name}</p>
                    <p className="text-xs text-[var(--ink-muted)]">{sub.student.email}</p>
                  </div>
                  <span className="text-xs text-amber-500 bg-amber-500/10 px-2.5 py-1 rounded-full font-bold">
                    {sub.status === "review_requested" ? "🔍 طلب مراجعة" : "⏳ معلق"}
                  </span>
                </div>

                {sub.submittedOutput && (
                  <div>
                    <p className="text-xs font-bold text-[var(--ink-muted)] mb-1">ناتج الطالب:</p>
                    <pre className="bg-[var(--bg)] border border-[var(--border)] rounded-xl p-3 text-sm text-white font-mono whitespace-pre-wrap overflow-x-auto">{sub.submittedOutput}</pre>
                  </div>
                )}
                {sub.fileUrl && (
                  <div>
                    <p className="text-xs font-bold text-[var(--ink-muted)] mb-1">ملف مرفق:</p>
                    <a
                      href={`/api/homework/${selected.id}/file?studentId=${sub.studentId}&fileName=${encodeURIComponent(sub.fileUrl.split("/").pop() || "")}`}
                      target="_blank"
                      rel="noreferrer"
                      className="text-sm text-sky-500 font-mono hover:underline flex items-center gap-1"
                    >
                      📎 {sub.fileName || "تحميل الملف"}
                    </a>
                  </div>
                )}

                <div>
                  <label className="text-xs font-bold text-[var(--ink-muted)] block mb-1">ملاحظة للطالب (اختياري):</label>
                  <input
                    type="text"
                    className={input}
                    placeholder="مثال: الكود صحيح لكن ابدأ بـ print"
                    value={noteMap[sub.id] || ""}
                    onChange={e => setNoteMap(m => ({ ...m, [sub.id]: e.target.value }))}
                  />
                </div>

                <div className="flex gap-2">
                  <button
                    onClick={() => verdict(sub, "passed")}
                    disabled={verdicting === sub.id}
                    className="flex-1 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-sm font-bold transition-colors disabled:opacity-50"
                  >
                    ✅ قبول
                  </button>
                  <button
                    onClick={() => verdict(sub, "failed")}
                    disabled={verdicting === sub.id}
                    className="flex-1 py-2.5 rounded-xl bg-red-600 hover:bg-red-500 text-white text-sm font-bold transition-colors disabled:opacity-50"
                  >
                    ❌ رفض
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

// ─── HomeworkManagerSection ───────────────────────────────────────────────────

interface Course { id: string; title: string }
interface Folder { id: string; name: string; videos?: Array<{ id: string; title: string }> }

export function HomeworkManagerSection({
  courses,
  folders: initialFolders,
  selectedCourse,
  onSelectCourse,
  notify,
}: {
  courses: Course[];
  folders: Folder[];
  selectedCourse: Course | null;
  onSelectCourse: (c: Course) => void;
  notify: (t: "success" | "error", m: string) => void;
}) {
  const [homeworks, setHomeworks] = useState<any[]>([]);
  const [loadingHw, setLoadingHw] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [courseFolders, setCourseFolders] = useState<Folder[]>(initialFolders || []);
  const [loadingFolders, setLoadingFolders] = useState(false);

  const [form, setForm] = useState({
    title: "",
    description: "",
    type: "exam" as "link" | "exam" | "terminal" | "upload",
    linkUrl: "",
    courseId: selectedCourse?.id || "",
    videoId: "",
    dueAt: "",
    timeLimitMinutes: 30,
    isPublished: false,
    // terminal
    expectedOutput: "",
    codeTemplate: "",
    codeLanguage: "python",
    // upload
    allowedFileTypes: "pdf,py,js,zip",
    // exam
    questions: [{ question: "", imageUrl: "", optionA: "", optionB: "", optionC: "", optionD: "", correctAnswer: "A" }],
  });

  const input = "w-full px-3.5 py-2.5 rounded-xl border border-[var(--border)] bg-[var(--bg)] text-[var(--ink)] text-sm focus:outline-none focus:border-sky-400/60 transition-all";
  const label = "block text-xs font-semibold text-[var(--ink-muted)] mb-1.5";
  const btn = "inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-sky-500 hover:bg-sky-400 text-white text-sm font-bold transition-colors disabled:opacity-50";

  // Keep form.courseId updated if selectedCourse changes
  useEffect(() => {
    if (selectedCourse?.id) {
      setForm(f => ({ ...f, courseId: selectedCourse.id }));
    }
  }, [selectedCourse]);

  // Fetch folders for the currently selected courseId in the form
  useEffect(() => {
    if (!form.courseId) {
      setCourseFolders([]);
      return;
    }
    let isMounted = true;
    setLoadingFolders(true);
    fetch(`/api/admin/courses/${form.courseId}/folders`, { credentials: "include" })
      .then(res => res.json())
      .then(data => {
        if (isMounted) setCourseFolders(data.folders || []);
      })
      .catch(() => {
        if (isMounted) setCourseFolders([]);
      })
      .finally(() => {
        if (isMounted) setLoadingFolders(false);
      });
    return () => { isMounted = false; };
  }, [form.courseId]);

  const fetchHomeworks = useCallback(async () => {
    setLoadingHw(true);
    try {
      const res = await fetch("/api/admin/homework", { credentials: "include" });
      const data = await res.json();
      setHomeworks(data.homeworks || []);
    } finally { setLoadingHw(false); }
  }, []);

  useEffect(() => { void fetchHomeworks(); }, [fetchHomeworks]);

  const allVideos = courseFolders.flatMap(f => (f.videos ?? []).map(v => ({ ...v, folderName: f.name })));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      const payload: Record<string, unknown> = {
        title: form.title,
        description: form.description || undefined,
        type: form.type,
        courseId: form.courseId || selectedCourse?.id || undefined,
        videoId: form.videoId || undefined,
        dueAt: form.dueAt || undefined,
        timeLimitMinutes: form.timeLimitMinutes,
        isPublished: form.isPublished,
      };
      if (form.type === "link") payload.linkUrl = form.linkUrl;
      if (form.type === "terminal") {
        payload.expectedOutput = form.expectedOutput;
        payload.codeTemplate = form.codeTemplate || undefined;
        payload.codeLanguage = form.codeLanguage;
      }
      if (form.type === "upload") payload.allowedFileTypes = form.allowedFileTypes || undefined;
      if (form.type === "exam") payload.questions = form.questions;

      const res = await fetch("/api/admin/homework", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (res.ok) {
        notify("success", "تم إنشاء الواجب بنجاح ✅");
        setShowForm(false);
        void fetchHomeworks();
        setForm(f => ({ ...f, title: "", description: "", linkUrl: "", videoId: "", expectedOutput: "", codeTemplate: "", questions: [{ question: "", imageUrl: "", optionA: "", optionB: "", optionC: "", optionD: "", correctAnswer: "A" }] }));
      } else {
        notify("error", data.error || "تعذر إنشاء الواجب");
      }
    } finally { setSaving(false); }
  };

  const deleteHw = async (hwId: string) => {
    const res = await fetch("/api/admin/homework", {
      method: "DELETE",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ homeworkId: hwId }),
    });
    if (res.ok) { notify("success", "تم حذف الواجب"); void fetchHomeworks(); }
    else notify("error", "تعذر حذف الواجب");
  };

  const togglePublish = async (hw: any) => {
    const res = await fetch("/api/admin/homework", {
      method: "PATCH",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ homeworkId: hw.id, isPublished: !hw.isPublished }),
    });
    if (res.ok) { notify("success", hw.isPublished ? "تم إخفاء الواجب" : "تم نشر الواجب ✅"); void fetchHomeworks(); }
    else notify("error", "تعذر تحديث حالة الواجب");
  };

  const TYPE_LABELS: Record<string, string> = {
    link: "🔗 رابط خارجي",
    exam: "📝 اختبار MCQ",
    terminal: "💻 كود / Terminal",
    upload: "📎 رفع ملف",
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between gap-3">
        <h2 className="text-lg font-black text-[var(--ink)]">📚 إدارة الواجبات</h2>
        <button onClick={() => setShowForm(s => !s)} className={btn}>
          {showForm ? "إلغاء" : "+ واجب جديد"}
        </button>
      </div>

      {/* Course context hint */}
      {selectedCourse && (
        <div className="text-xs text-[var(--ink-muted)] bg-sky-500/8 border border-sky-500/20 rounded-xl px-4 py-2.5">
          الكورس المختار حالياً: <strong className="text-sky-500">{selectedCourse.title}</strong>
        </div>
      )}

      {/* Create Form */}
      {showForm && (
        <form onSubmit={submit} className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-5 space-y-4">
          <h3 className="font-bold text-[var(--ink)]">واجب جديد</h3>

          {/* Type selector */}
          <div>
            <label className={label}>نوع الواجب</label>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              {(["exam","terminal","upload","link"] as const).map(t => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setForm(f => ({ ...f, type: t }))}
                  className={`py-2 px-3 rounded-xl text-xs font-bold border-2 transition-colors text-center ${form.type === t ? "border-sky-500 bg-sky-500/10 text-sky-500" : "border-[var(--border)] text-[var(--ink-muted)] hover:border-sky-400/40"}`}
                >
                  {TYPE_LABELS[t]}
                </button>
              ))}
            </div>
          </div>

          {/* Course & Lesson Selectors */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className={label}>الكورس التابع له الواجب</label>
              <select
                value={form.courseId}
                onChange={e => setForm(f => ({ ...f, courseId: e.target.value, videoId: "" }))}
                className={input}
              >
                <option value="">— اختر الكورس —</option>
                {courses.map(c => (
                  <option key={c.id} value={c.id}>{c.title}</option>
                ))}
              </select>
            </div>

            <div>
              <label className={label}>ربط بدرس محدد (اختياري)</label>
              <select
                value={form.videoId}
                onChange={e => setForm(f => ({ ...f, videoId: e.target.value }))}
                className={input}
                disabled={!form.courseId || loadingFolders}
              >
                {!form.courseId ? (
                  <option value="">اختر الكورس أولاً</option>
                ) : loadingFolders ? (
                  <option value="">جارٍ تحميل الدروس...</option>
                ) : allVideos.length === 0 ? (
                  <option value="">لا توجد دروس في هذا الكورس بعد</option>
                ) : (
                  <>
                    <option value="">— الكورس ككل (بدون تحديد درس) —</option>
                    {allVideos.map(v => (
                      <option key={v.id} value={v.id}>
                        📁 {v.folderName} ← 🎥 {v.title}
                      </option>
                    ))}
                  </>
                )}
              </select>
            </div>
          </div>

          <div>
            <label className={label}>عنوان الواجب *</label>
            <input required value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} className={input} placeholder="مثال: واجب الدرس الأول" />
          </div>

          <div>
            <label className={label}>وصف (اختياري)</label>
            <textarea rows={2} value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} className={`${input} resize-none`} />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className={label}>تاريخ التسليم</label>
              <input type="datetime-local" value={form.dueAt} onChange={e => setForm(f => ({ ...f, dueAt: e.target.value }))} className={input} dir="ltr" />
            </div>
            <div>
              <label className={label}>مدة الاختبار (دقيقة)</label>
              <input type="number" min={1} max={300} value={form.timeLimitMinutes} onChange={e => setForm(f => ({ ...f, timeLimitMinutes: Number(e.target.value) || 30 }))} className={input} dir="ltr" />
            </div>
          </div>

          {/* Type-specific fields */}
          {form.type === "link" && (
            <div>
              <label className={label}>الرابط الخارجي *</label>
              <input required type="url" value={form.linkUrl} onChange={e => setForm(f => ({ ...f, linkUrl: e.target.value }))} className={input} dir="ltr" placeholder="https://…" />
            </div>
          )}

          {form.type === "terminal" && (
            <>
              <div>
                <label className={label}>لغة البرمجة</label>
                <select value={form.codeLanguage} onChange={e => setForm(f => ({ ...f, codeLanguage: e.target.value }))} className={input}>
                  <option value="python">Python</option>
                  <option value="javascript">JavaScript</option>
                  <option value="cpp">C++</option>
                  <option value="java">Java</option>
                  <option value="other">أخرى</option>
                </select>
              </div>
              <div>
                <label className={label}>الناتج المتوقع (expected output) *</label>
                <textarea required rows={4} value={form.expectedOutput} onChange={e => setForm(f => ({ ...f, expectedOutput: e.target.value }))} className={`${input} font-mono resize-y`} dir="ltr" placeholder="Hello World&#10;Sum = 15" />
                <p className="text-[10px] text-[var(--ink-muted)] mt-1">الفراغات وتغيير السطر لا تؤثر في التصحيح التلقائي</p>
              </div>
              <div>
                <label className={label}>كود بدئي للطالب (اختياري)</label>
                <textarea rows={4} value={form.codeTemplate} onChange={e => setForm(f => ({ ...f, codeTemplate: e.target.value }))} className={`${input} font-mono resize-y`} dir="ltr" placeholder="# أكمل الكود هنا&#10;name = input()" />
              </div>
            </>
          )}

          {form.type === "upload" && (
            <div>
              <label className={label}>أنواع الملفات المسموحة</label>
              <input value={form.allowedFileTypes} onChange={e => setForm(f => ({ ...f, allowedFileTypes: e.target.value }))} className={input} dir="ltr" placeholder="pdf,py,js,zip" />
              <p className="text-[10px] text-[var(--ink-muted)] mt-1">افصل بفاصلة، اتركه فارغاً للسماح بأي نوع</p>
            </div>
          )}

          {form.type === "exam" && (
            <div className="space-y-3">
              <label className={label}>الأسئلة</label>
              {form.questions.map((q, qi) => (
                <div key={qi} className="border border-[var(--border)] rounded-xl p-4 space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-[var(--ink-muted)]">سؤال {qi + 1}</span>
                    {form.questions.length > 1 && (
                      <button type="button" onClick={() => setForm(f => ({ ...f, questions: f.questions.filter((_, i) => i !== qi) }))} className="text-xs text-red-500 hover:underline">حذف</button>
                    )}
                  </div>
                  <input required value={q.question} onChange={e => { const qs = [...form.questions]; qs[qi] = { ...qs[qi], question: e.target.value }; setForm(f => ({ ...f, questions: qs })); }} className={input} placeholder="نص السؤال *" />
                  <input value={q.imageUrl} onChange={e => { const qs = [...form.questions]; qs[qi] = { ...qs[qi], imageUrl: e.target.value }; setForm(f => ({ ...f, questions: qs })); }} className={input} placeholder="رابط صورة (اختياري)" dir="ltr" />
                  <div className="grid grid-cols-2 gap-2">
                    {(["A","B","C","D"] as const).map(opt => (
                      <div key={opt} className="flex gap-1.5 items-center">
                        <button
                          type="button"
                          onClick={() => { const qs = [...form.questions]; qs[qi] = { ...qs[qi], correctAnswer: opt }; setForm(f => ({ ...f, questions: qs })); }}
                          className={`w-6 h-6 rounded-full text-xs font-black shrink-0 transition-colors ${q.correctAnswer === opt ? "bg-emerald-500 text-white" : "bg-[var(--border)] text-[var(--ink-muted)] hover:bg-emerald-500/30"}`}
                        >{opt}</button>
                        <input required value={q[`option${opt}` as keyof typeof q] as string} onChange={e => { const qs = [...form.questions]; (qs[qi] as any)[`option${opt}`] = e.target.value; setForm(f => ({ ...f, questions: qs })); }} className={`${input} flex-1`} placeholder={`الخيار ${opt}`} />
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              <button type="button" onClick={() => setForm(f => ({ ...f, questions: [...f.questions, { question: "", imageUrl: "", optionA: "", optionB: "", optionC: "", optionD: "", correctAnswer: "A" }] }))} className="text-sm text-sky-500 hover:underline">+ إضافة سؤال</button>
            </div>
          )}

          <div className="flex items-center gap-3 pt-2">
            <label className="flex items-center gap-2 cursor-pointer select-none">
              <input type="checkbox" checked={form.isPublished} onChange={e => setForm(f => ({ ...f, isPublished: e.target.checked }))} className="w-4 h-4 rounded" />
              <span className="text-sm font-semibold text-[var(--ink)]">نشر فور الإنشاء</span>
            </label>
          </div>

          <button type="submit" disabled={saving} className={`${btn} w-full`}>
            {saving ? "جارٍ الحفظ..." : "إنشاء الواجب"}
          </button>
        </form>
      )}

      {/* Homeworks List */}
      <div className="space-y-2">
        <h3 className="text-sm font-bold text-[var(--ink-muted)]">الواجبات الحالية ({homeworks.length})</h3>
        {loadingHw ? (
          <div className="text-center py-8 text-[var(--ink-muted)] text-sm">جارٍ التحميل...</div>
        ) : homeworks.length === 0 ? (
          <div className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-10 text-center text-[var(--ink-muted)] text-sm">
            لا توجد واجبات بعد — أنشئ واجباً أولاً
          </div>
        ) : (
          homeworks.map(hw => (
            <div key={hw.id} className="bg-[var(--surface)] border border-[var(--border)] rounded-2xl p-4 flex items-center justify-between gap-3">
              <div className="min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <p className="font-bold text-[var(--ink)] truncate">{hw.title}</p>
                  <span className="text-xs bg-sky-500/10 text-sky-500 px-2 py-0.5 rounded-full font-bold">{TYPE_LABELS[hw.type] ?? hw.type}</span>
                  {(hw.reviewQueueCount ?? 0) > 0 && (
                    <span className="text-xs bg-amber-500/15 text-amber-500 px-2 py-0.5 rounded-full font-bold">🔍 {hw.reviewQueueCount} معلق</span>
                  )}
                </div>
                <p className="text-xs text-[var(--ink-muted)] mt-0.5">
                  {hw._count?.submissions ?? 0} تسليم · {hw.video?.title ?? "الكورس كله"}
                </p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <button
                  onClick={() => togglePublish(hw)}
                  className={`px-2.5 py-1.5 rounded-lg text-xs font-bold transition-colors ${hw.isPublished ? "text-emerald-500 bg-emerald-500/10 hover:bg-emerald-500/20" : "text-[var(--ink-muted)] bg-[var(--border)] hover:bg-[var(--border)]/70"}`}
                >
                  {hw.isPublished ? "✅ منشور" : "إخفاء"}
                </button>
                <button onClick={() => deleteHw(hw.id)} className="px-2.5 py-1.5 rounded-lg text-xs font-bold text-red-500 hover:bg-red-500/10 transition-colors">
                  حذف
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { ViewsAreaChart, HBarList, DistBars } from "./Charts";
import {
  IconUsers, IconEye, IconVideo, IconClipboard, IconPlus, IconBook,
  IconTicket, IconChat, IconShield, IconFile, IconChart,
} from "./AdminIcons";

// ─── Types (mirror /api/admin/analytics) ──────────────────────────────────────
type Kpi = { value: number; deltaPct: number; newThisPeriod?: number };
type Issue = { kind: string; severity: "high" | "med" | "low"; title: string; detail: string; at: string | null };
type Analytics = {
  teacherName: string;
  period: string;
  empty: boolean;
  kpis: { students: Kpi; views: Kpi; completions: Kpi; avgQuizScore: Kpi } | null;
  series: { date: string; views: number; enrollments: number }[];
  topVideos: { id: string; title: string; course: string; views: number }[];
  lowVideos: { id: string; title: string; course: string; views: number }[];
  courseBreakdown: { id: string; title: string; students: number; views: number }[];
  quizBuckets: { label: string; count: number }[];
  issues: Issue[];
  totals?: { courses: number; videos: number };
};

const PERIODS: { id: string; label: string }[] = [
  { id: "7d", label: "7 أيام" },
  { id: "30d", label: "30 يوم" },
  { id: "90d", label: "90 يوم" },
  { id: "all", label: "الكل" },
];

const card = "bg-[var(--surface)] rounded-2xl border border-[var(--border)]";
const cardPad = `${card} p-5`;

function timeAgo(iso: string | null) {
  if (!iso) return "";
  const diff = Date.now() - new Date(iso).getTime();
  const h = Math.floor(diff / 3600000);
  if (h < 1) return "منذ قليل";
  if (h < 24) return `منذ ${h} ساعة`;
  const d = Math.floor(h / 24);
  return `منذ ${d} يوم`;
}

function Delta({ pct, suffix }: { pct: number; suffix?: string }) {
  const up = pct > 0, down = pct < 0;
  const cls = up ? "text-emerald-500 bg-emerald-500/10" : down ? "text-rose-500 bg-rose-500/10" : "text-[var(--ink-muted)] bg-[var(--border)]";
  return (
    <span className={`inline-flex items-center gap-1 text-[11px] font-bold px-1.5 py-0.5 rounded-md ${cls}`} dir="ltr">
      <span>{up ? "▲" : down ? "▼" : "—"}</span>
      <span>{Math.abs(pct)}%{suffix ? ` ${suffix}` : ""}</span>
    </span>
  );
}

const ISSUE_ICON: Record<string, (p: { className?: string }) => React.ReactElement> = {
  ticket: IconTicket, feedback: IconChat, error: IconShield, health: IconFile,
};
const SEV_DOT: Record<string, string> = { high: "bg-rose-500", med: "bg-amber-500", low: "bg-slate-400" };

export function TeacherOverview({
  courses, onCreateCourse, loadingCourses, onGoToMyPage,
}: {
  courses: { id: string; title: string }[];
  onCreateCourse: () => void;
  loadingCourses: boolean;
  onGoToMyPage?: () => void;
}) {
  const [period, setPeriod] = useState("30d");
  const [courseId, setCourseId] = useState("");
  const [data, setData] = useState<Analytics | null>(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const qs = new URLSearchParams({ period });
      if (courseId) qs.set("courseId", courseId);
      const res = await fetch(`/api/admin/analytics?${qs}`, { credentials: "include" });
      if (res.ok) setData(await res.json());
    } catch { /* keep last data */ }
    finally { setLoading(false); }
  }, [period, courseId]);

  useEffect(() => { void load(); }, [load]);

  const firstName = data?.teacherName?.replace(/^(مستر|مس|د\.|أ\.|أستاذة?|دكتور)\s*/u, "").split(" ")[0] || data?.teacherName;

  // ── Empty (no courses at all) ──
  if (!loading && data?.empty) {
    return (
      <div className={`${cardPad} py-16 text-center`}>
        <div className="mx-auto mb-4 w-14 h-14 rounded-2xl border border-[var(--border)] bg-[var(--bg)] text-[var(--ink-muted)] flex items-center justify-center">
          <IconBook className="w-7 h-7" />
        </div>
        <p className="font-bold text-[var(--ink)] text-lg">أهلاً بك في Code-UP{firstName ? `، ${firstName}` : ""} 👋</p>
        <p className="text-sm text-[var(--ink-muted)] mt-1.5 max-w-sm mx-auto leading-6">ابدأ بإنشاء كورسك الأول، وستظهر هنا كل إحصائياتك ومخططاتك مباشرة.</p>
        <div className="flex items-center justify-center gap-3 mt-5">
          <button onClick={onCreateCourse} className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-sky-500 hover:bg-sky-400 text-white text-sm font-bold transition-colors">
            <IconPlus className="w-4 h-4" /> إنشاء كورس
          </button>
          {onGoToMyPage && (
            <button onClick={onGoToMyPage} className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl border border-[var(--border)] text-[var(--ink)] text-sm font-bold transition-colors hover:bg-[var(--surface-2)]">
              إضافة صورة شخصية 📸
            </button>
          )}
        </div>
      </div>
    );
  }

  const kpiDefs = data?.kpis ? [
    { key: "students", label: "إجمالي المتعلمين", Icon: IconUsers, kpi: data.kpis.students, extra: data.kpis.students.newThisPeriod != null ? `+${data.kpis.students.newThisPeriod} هذه الفترة` : undefined },
    { key: "views", label: "المشاهدات", Icon: IconEye, kpi: data.kpis.views },
    { key: "completions", label: "محاضرات مكتملة", Icon: IconVideo, kpi: data.kpis.completions },
    { key: "quiz", label: "متوسط درجات الاختبارات", Icon: IconClipboard, kpi: data.kpis.avgQuizScore, suffix: "٪" },
  ] : [];

  return (
    <div className="space-y-5">
      {/* ── Welcome + filters ── */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div className="min-w-0 flex items-center gap-3">
          {onGoToMyPage && (
            <button
              onClick={onGoToMyPage}
              className="relative group shrink-0 w-12 h-12 rounded-full bg-sky-500/10 border border-sky-500/30 overflow-hidden flex items-center justify-center transition-transform hover:scale-105"
              title="تعديل الصورة الشخصية"
            >
              <span className="text-sm font-black text-sky-500">{(firstName || "م")[0]}</span>
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-xs transition-opacity">📷</div>
            </button>
          )}
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-[var(--ink)] truncate">
              أهلاً، {firstName || "أستاذنا"} <span className="inline-block">👋</span>
            </h2>
            <p className="text-sm text-[var(--ink-muted)] mt-0.5">نظرة سريعة على أداء كورساتك وتفاعل طلابك.</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2 shrink-0">
          {/* course filter */}
          <select
            value={courseId}
            onChange={(e) => setCourseId(e.target.value)}
            className="px-3 py-2 rounded-xl border border-[var(--border)] bg-[var(--surface)] text-[var(--ink)] text-sm font-semibold focus:outline-none focus:border-sky-400/60 cursor-pointer max-w-[180px] truncate"
            aria-label="تصفية حسب الكورس"
          >
            <option value="">كل الكورسات</option>
            {courses.map((c) => <option key={c.id} value={c.id}>{c.title}</option>)}
          </select>
          {/* period chips */}
          <div className="flex items-center gap-1 p-1 rounded-xl bg-[var(--surface)] border border-[var(--border)]">
            {PERIODS.map((p) => (
              <button
                key={p.id}
                onClick={() => setPeriod(p.id)}
                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${period === p.id ? "bg-sky-500 text-white" : "text-[var(--ink-muted)] hover:text-[var(--ink)]"}`}
              >
                {p.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* ── KPI cards ── */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        {(loading && !data ? Array.from({ length: 4 }) : kpiDefs).map((k, i) =>
          (loading && !data) ? (
            <div key={i} className="h-28 rounded-2xl skeleton" />
          ) : (
            <div key={(k as typeof kpiDefs[number]).key} className={`${cardPad} flex flex-col gap-3`}>
              <div className="flex items-center justify-between">
                <span className="w-10 h-10 rounded-xl bg-sky-500/12 text-sky-500 dark:text-sky-300 flex items-center justify-center">
                  {(() => { const Icon = (k as typeof kpiDefs[number]).Icon; return <Icon className="w-5 h-5" />; })()}
                </span>
                <Delta pct={(k as typeof kpiDefs[number]).kpi.deltaPct} />
              </div>
              <div>
                <div className="text-2xl sm:text-3xl font-black text-[var(--ink)] tabular-nums leading-none">
                  {(k as typeof kpiDefs[number]).kpi.value}{(k as typeof kpiDefs[number]).suffix ?? ""}
                </div>
                <div className="text-[var(--ink-muted)] text-xs mt-1.5">{(k as typeof kpiDefs[number]).label}</div>
                {(k as typeof kpiDefs[number]).extra && (
                  <div className="text-[11px] text-emerald-500 font-semibold mt-0.5">{(k as typeof kpiDefs[number]).extra}</div>
                )}
              </div>
            </div>
          )
        )}
      </div>

      {/* ── Main chart ── */}
      <div className={cardPad}>
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-[var(--ink)] flex items-center gap-2"><IconChart className="w-4 h-4 text-sky-500" /> المشاهدات والاشتراكات عبر الزمن</h3>
        </div>
        {loading && !data ? <div className="h-64 rounded-xl skeleton" /> : data && <ViewsAreaChart series={data.series} />}
      </div>

      {/* ── Top / low videos ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        <div className={cardPad}>
          <h3 className="font-bold text-[var(--ink)] mb-4 flex items-center gap-2"><IconEye className="w-4 h-4 text-sky-500" /> الأكثر مشاهدة</h3>
          {data && <HBarList items={data.topVideos.map((v) => ({ label: v.title, value: v.views, sub: v.course }))} color="#38bdf8" />}
        </div>
        <div className={cardPad}>
          <h3 className="font-bold text-[var(--ink)] mb-1 flex items-center gap-2"><IconVideo className="w-4 h-4 text-amber-500" /> تحتاج اهتمامك — الأقل مشاهدة</h3>
          <p className="text-[11px] text-[var(--ink-muted)] mb-4">فيديوهات بمشاهدات منخفضة قد تحتاج مراجعة العنوان أو الترتيب.</p>
          {data && <HBarList items={data.lowVideos.map((v) => ({ label: v.title, value: v.views, sub: v.course }))} color="#f59e0b" />}
        </div>
      </div>

      {/* ── Course breakdown + quiz distribution ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        <div className={cardPad}>
          <h3 className="font-bold text-[var(--ink)] mb-4 flex items-center gap-2"><IconBook className="w-4 h-4 text-sky-500" /> أداء الكورسات (مشاهدات)</h3>
          {data && <HBarList items={data.courseBreakdown.map((c) => ({ label: c.title, value: c.views, sub: `${c.students} طالب` }))} color="#6366f1" />}
        </div>
        <div className={cardPad}>
          <h3 className="font-bold text-[var(--ink)] mb-4 flex items-center gap-2"><IconClipboard className="w-4 h-4 text-indigo-400" /> توزيع درجات الاختبارات</h3>
          {data && <DistBars buckets={data.quizBuckets} />}
        </div>
      </div>

      {/* ── Issues feed ── */}
      <div className={card}>
        <div className="px-5 py-4 border-b border-[var(--border)] flex items-center justify-between">
          <h3 className="font-bold text-[var(--ink)] flex items-center gap-2"><IconShield className="w-4 h-4 text-rose-500" /> ما يحتاج انتباهك</h3>
          {data && <span className="text-xs text-[var(--ink-muted)]">{data.issues.length} عنصر</span>}
        </div>
        {data && data.issues.length === 0 ? (
          <div className="py-10 text-center">
            <p className="text-sm font-bold text-emerald-500">كل شيء على ما يُرام ✓</p>
            <p className="text-xs text-[var(--ink-muted)] mt-1">لا توجد مشاكل أو شكاوى أو تنبيهات حالياً.</p>
          </div>
        ) : (
          <ul className="divide-y divide-[var(--border)]">
            {data?.issues.map((it, i) => {
              const Icon = ISSUE_ICON[it.kind] ?? IconFile;
              return (
                <li key={i} className="px-5 py-3.5 flex items-start gap-3">
                  <span className={`mt-1.5 w-2 h-2 rounded-full shrink-0 ${SEV_DOT[it.severity]}`} aria-hidden />
                  <span className="shrink-0 w-8 h-8 rounded-lg bg-[var(--border)] text-[var(--ink-muted)] flex items-center justify-center">
                    <Icon className="w-4 h-4" />
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold text-[var(--ink)]">{it.title}</p>
                    <p className="text-xs text-[var(--ink-muted)] truncate">{it.detail}</p>
                  </div>
                  {it.at && <span className="text-[11px] text-[var(--ink-muted)] shrink-0">{timeAgo(it.at)}</span>}
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {!loadingCourses && courses.length > 0 && (
        <p className="text-center text-[11px] text-[var(--ink-muted)]">
          {data?.totals ? `${data.totals.courses} كورس · ${data.totals.videos} فيديو` : ""}
        </p>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useToast } from "@/components/ui/Toast";
import { IconGlobe, IconEye, IconLink, IconBook } from "@/components/admin/AdminIcons";

type Profile = {
  slug: string;
  displayName: string | null;
  bio: string | null;
  photoUrl: string | null;
  bannerUrl: string | null;
  navColor: string | null;
  accentColor: string | null;
  socials: string | null; // JSON
  featuredCourseId: string | null;
  isPublished: boolean;
  bookingEnabled: boolean;
  arabicEnabled: boolean;
  languagesEnabled: boolean;
  priceMonthly1: number | null;
  priceMonthly3: number | null;
  priceMonthly6: number | null;
  originalMonthly3: number | null;
  originalMonthly6: number | null;
  langSurcharge1: number | null;
  langSurcharge3: number | null;
  langSurcharge6: number | null;
  enableMonthly1: boolean;
  enableMonthly3: boolean;
  enableMonthly6: boolean;
  priceMonthly: number | null;
  priceTermly: number | null;
  priceYearly: number | null;
  discountMonthly: number | null;
  discountTermly: number | null;
  discountYearly: number | null;
  courseStartDate: string | null;
  bookingContactUrl: string | null;
};

type Socials = { facebook?: string; youtube?: string; tiktok?: string };

const input =
  "w-full px-3.5 py-2.5 rounded-xl border border-[var(--border)] bg-[var(--bg)] text-[var(--ink)] text-sm placeholder:text-[var(--ink-muted)] focus:outline-none focus:border-sky-400/60 focus:shadow-[0_0_0_3px_rgba(59,130,246,0.15)] transition-all";
const label = "block text-xs font-semibold text-[var(--ink-muted)] mb-1.5";
const card = "bg-[var(--surface)] rounded-2xl border border-[var(--border)] p-5 sm:p-6";
const primaryBtn =
  "inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-sky-500 hover:bg-sky-400 text-white text-sm font-bold transition-colors disabled:opacity-50 disabled:cursor-not-allowed";
const ghostBtn =
  "inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl border border-[var(--border)] text-[var(--ink-muted)] hover:text-[var(--ink)] hover:border-[var(--ink-muted)]/40 text-sm font-semibold transition-colors";

function fileToResizedDataUrl(file: File, max = 512): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = document.createElement("img") as HTMLImageElement;
      img.onload = () => {
        const scale = Math.min(1, max / Math.max(img.width, img.height));
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        if (!ctx) return reject(new Error("no ctx"));
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", 0.82));
      };
      img.onerror = reject;
      img.src = reader.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export function TeacherPublicProfile() {
  const { success: toastSuccess, error: toastError } = useToast();
  const [p, setP] = useState<Profile | null>(null);
  const [socials, setSocials] = useState<Socials>({});
  const [courses, setCourses] = useState<{ id: string; title: string }[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [origin, setOrigin] = useState("");
  const [slugState, setSlugState] = useState<"idle" | "checking" | "ok" | "taken" | "invalid">("idle");
  const photoInput = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setOrigin(window.location.origin);
    Promise.all([
      fetch("/api/admin/profile", { credentials: "include" }).then((r) => r.json()),
      fetch("/api/admin/courses", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
    ]).then(([prof, crs]) => {
      if (prof?.profile) {
        setP({
          bookingEnabled: true,
          arabicEnabled: true,
          languagesEnabled: true,
          enableMonthly1: true,
          enableMonthly3: true,
          enableMonthly6: true,
          priceMonthly1: 200,
          priceMonthly3: 500,
          priceMonthly6: 1000,
          originalMonthly3: 600,
          originalMonthly6: 1200,
          langSurcharge1: 50,
          langSurcharge3: 150,
          langSurcharge6: 300,
          ...prof.profile,
        });
        try { setSocials(prof.profile.socials ? JSON.parse(prof.profile.socials) : {}); } catch { setSocials({}); }
      }
      setCourses((crs?.courses ?? []).map((c: { id: string; title: string }) => ({ id: c.id, title: c.title })));
    }).finally(() => setLoading(false));
  }, []);

  const set = <K extends keyof Profile>(k: K, v: Profile[K]) => setP((prev) => (prev ? { ...prev, [k]: v } : prev));

  const checkSlug = useCallback((slug: string) => {
    if (!slug || slug.length < 2) { setSlugState("invalid"); return; }
    setSlugState("checking");
    fetch(`/api/admin/profile/slug-check?slug=${encodeURIComponent(slug)}`, { credentials: "include" })
      .then((r) => r.json())
      .then((d) => setSlugState(d.available ? "ok" : d.reason === "invalid" ? "invalid" : "taken"))
      .catch(() => setSlugState("idle"));
  }, []);

  useEffect(() => {
    if (!p?.slug) return;
    const t = setTimeout(() => checkSlug(p.slug), 450);
    return () => clearTimeout(t);
  }, [p?.slug, checkSlug]);

  const onPhoto = async (file: File | undefined) => {
    if (!file) return;
    try {
      const dataUrl = await fileToResizedDataUrl(file, 512);
      set("photoUrl", dataUrl);
    } catch { toastError("تعذر معالجة الصورة"); }
  };

  const save = async () => {
    if (!p) return;
    if (slugState === "taken" || slugState === "invalid") { toastError("الرابط غير صالح أو مستخدم"); return; }
    setSaving(true);
    try {
      const res = await fetch("/api/admin/profile", {
        method: "PUT",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...p, socials: JSON.stringify(socials) }),
      });
      const data = await res.json();
      if (res.ok) { setP((prev) => ({ ...prev, ...data.profile })); toastSuccess("تم حفظ صفحتك وإعدادات الحجز بنجاح"); }
      else toastError(data.error || "تعذر الحفظ");
    } catch { toastError("تعذر الحفظ"); }
    finally { setSaving(false); }
  };

  const copyLink = () => {
    navigator.clipboard.writeText(`${origin}/${p?.slug}`).then(
      () => toastSuccess("تم نسخ الرابط"),
      () => toastError("تعذر النسخ"),
    );
  };

  if (loading) return <div className="space-y-4"><div className="h-40 rounded-2xl skeleton" /><div className="h-64 rounded-2xl skeleton" /></div>;
  if (!p) return <div className={card}><p className="text-[var(--ink-muted)] text-sm">تعذر تحميل بيانات الصفحة.</p></div>;

  const slugMsg = {
    idle: "", checking: "جارٍ التحقق…", ok: "متاح ✓", taken: "مستخدم بالفعل", invalid: "غير صالح",
  }[slugState];
  const slugColor = slugState === "ok" ? "text-emerald-500" : slugState === "checking" ? "text-[var(--ink-muted)]" : "text-rose-500";

  return (
    <div className="space-y-5 max-w-3xl" dir="rtl">
      {/* Header / publish + actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h2 className="text-xl font-black text-[var(--ink)] flex items-center gap-2"><IconGlobe className="w-5 h-5 text-sky-500" /> صفحتي العامة</h2>
          <p className="text-sm text-[var(--ink-muted)] mt-0.5">صفحتك الشخصية التي تشاركها مع طلابك — صورتك، نبذتك، وكل كورساتك.</p>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <a href={`/${p.slug}`} target="_blank" rel="noreferrer" className={ghostBtn}><IconEye className="w-4 h-4" /> معاينة</a>
          <button onClick={copyLink} className={ghostBtn}><IconLink className="w-4 h-4" /> نسخ الرابط</button>
        </div>
      </div>

      {/* Publish toggle */}
      <div className={`${card} flex items-center justify-between gap-3`}>
        <div>
          <p className="font-bold text-[var(--ink)]">{p.isPublished ? "الصفحة منشورة" : "الصفحة مسودة (غير منشورة)"}</p>
          <p className="text-xs text-[var(--ink-muted)] mt-0.5">{p.isPublished ? "أي شخص يملك الرابط يمكنه رؤيتها." : "لن تظهر للطلاب حتى تنشرها."}</p>
        </div>
        <button
          onClick={() => set("isPublished", !p.isPublished)}
          role="switch"
          aria-checked={p.isPublished}
          className={`relative w-12 h-7 rounded-full transition-colors shrink-0 ${p.isPublished ? "bg-emerald-500" : "bg-[var(--border)]"}`}
        >
          <span className={`absolute top-1 w-5 h-5 rounded-full bg-white transition-all ${p.isPublished ? "left-1" : "left-6"}`} />
        </button>
      </div>

      {/* Identity & Photo Section */}
      <div className={`${card} space-y-5`}>
        <div className="p-4 rounded-xl bg-sky-500/10 border border-sky-500/20 flex flex-col sm:flex-row items-center gap-4 justify-between">
          <div className="flex items-center gap-4">
            <div className="relative w-20 h-20 rounded-full bg-[var(--bg)] border-2 border-sky-500/40 overflow-hidden flex items-center justify-center shrink-0 shadow-md">
              {p.photoUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={p.photoUrl} alt="صورة المدرس" className="w-full h-full object-cover" />
              ) : (
                <span className="text-2xl font-black text-sky-500">{(p.displayName || "؟")[0]}</span>
              )}
            </div>
            <div>
              <h3 className="font-bold text-[var(--ink)] text-base">الصورة الشخصية للمدرس 📸</h3>
              <p className="text-xs text-[var(--ink-muted)] mt-0.5">
                تظهر للطلاب في صفحة الكورسات وقائمة المدرسين.
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <input ref={photoInput} type="file" accept="image/*" className="hidden" onChange={(e) => onPhoto(e.target.files?.[0])} />
            <button onClick={() => photoInput.current?.click()} className={primaryBtn}>
              {p.photoUrl ? "تغيير الصورة" : "إضافة صورة شخصية"}
            </button>
            {p.photoUrl && (
              <button onClick={() => set("photoUrl", null)} className="px-3 py-2 text-xs text-rose-500 hover:text-rose-400 font-bold transition-colors">
                حذف الصورة
              </button>
            )}
          </div>
        </div>

        <div>
          <label className={label}>الاسم المعروض</label>
          <input className={input} value={p.displayName ?? ""} onChange={(e) => set("displayName", e.target.value)} placeholder="مثال: مستر أحمد" />
        </div>
        <div>
          <label className={label}>نبذة تعريفية</label>
          <textarea rows={3} className={`${input} resize-none`} value={p.bio ?? ""} onChange={(e) => set("bio", e.target.value)} placeholder="خبرة في تدريس البرمجة والذكاء الاصطناعي…" />
        </div>

        {/* Slug */}
        <div>
          <label className={label}>رابط الصفحة</label>
          <div className="flex items-center gap-2">
            <span className="text-xs text-[var(--ink-muted)] shrink-0 font-mono" dir="ltr">{origin}/</span>
            <input className={`${input} font-mono`} dir="ltr" value={p.slug} onChange={(e) => set("slug", e.target.value)} placeholder="MR-AHMED" />
          </div>
          {slugMsg && <p className={`text-[11px] mt-1.5 font-semibold ${slugColor}`}>{slugMsg}</p>}
        </div>
      </div>

      {/* Theme colors */}
      <div className={`${card} space-y-4`}>
        <h3 className="font-bold text-[var(--ink)]">ألوان الصفحة</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {([
            { key: "navColor", label: "لون الشريط العلوي", fallback: "#0b0f19" },
            { key: "accentColor", label: "لون الأزرار والتمييز", fallback: "#6366f1" },
          ] as const).map(({ key, label: lbl, fallback }) => (
            <div key={key}>
              <label className={label}>{lbl}</label>
              <div className="flex items-center gap-2">
                <input type="color" value={p[key] ?? fallback} onChange={(e) => set(key, e.target.value)} className="w-10 h-10 rounded-lg border border-[var(--border)] bg-transparent cursor-pointer shrink-0" />
                <input className={`${input} font-mono`} dir="ltr" value={p[key] ?? fallback} onChange={(e) => set(key, e.target.value)} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Featured course + socials */}
      <div className={`${card} space-y-4`}>
        <div>
          <label className={label}><IconBook className="w-3.5 h-3.5 inline -mt-0.5 me-1" />الكورس المميّز (يظهر أولاً)</label>
          <select className={input} value={p.featuredCourseId ?? ""} onChange={(e) => set("featuredCourseId", e.target.value || null)}>
            <option value="">بدون</option>
            {courses.map((c) => <option key={c.id} value={c.id}>{c.title}</option>)}
          </select>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {([
            { key: "facebook", label: "Facebook" },
            { key: "youtube", label: "YouTube" },
            { key: "tiktok", label: "TikTok" },
          ] as const).map(({ key, label: lbl }) => (
            <div key={key}>
              <label className={label}>{lbl}</label>
              <input className={`${input} font-mono`} dir="ltr" value={socials[key] ?? ""} onChange={(e) => setSocials((s) => ({ ...s, [key]: e.target.value }))} placeholder="https://…" />
            </div>
          ))}
        </div>
      </div>

      {/* ── NEW: Comprehensive Booking & Subscription Settings ── */}
      <div className={`${card} space-y-6`}>
        <div className="flex items-center justify-between border-b border-[var(--border)] pb-4">
          <div>
            <h3 className="font-bold text-[var(--ink)] flex items-center gap-2 text-base">
              <svg className="w-5 h-5 text-emerald-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              إعدادات الحجز والاشتراك 💳
            </h3>
            <p className="text-xs text-[var(--ink-muted)] mt-1">تحديد تفعيل الحجز، لغات التدريس المتاحة، وأسعار خطط 1 شهر، 3 شهور، و 6 شهور.</p>
          </div>

          {/* Booking ON/OFF Switch */}
          <div className="flex items-center gap-3 bg-[var(--bg)] p-2.5 rounded-xl border border-[var(--border)]">
            <span className="text-xs font-bold text-[var(--ink)]">
              {p.bookingEnabled ? "الحجز مفعل ✅" : "الحجز مغلق 🔒"}
            </span>
            <button
              type="button"
              onClick={() => set("bookingEnabled", !p.bookingEnabled)}
              role="switch"
              aria-checked={p.bookingEnabled}
              className={`relative w-12 h-6 rounded-full transition-colors shrink-0 ${p.bookingEnabled ? "bg-emerald-500" : "bg-[var(--border)]"}`}
            >
              <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all ${p.bookingEnabled ? "left-1" : "left-6"}`} />
            </button>
          </div>
        </div>

        {/* Language Availability Options */}
        <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--bg)] space-y-3">
          <h4 className="font-bold text-xs text-[var(--ink)]">🌐 لغات الشرح والتدريس المتاحة للطلاب:</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <label className="flex items-center gap-2.5 p-3 rounded-lg border border-[var(--border)] bg-[var(--surface)] cursor-pointer hover:border-emerald-500/50">
              <input
                type="checkbox"
                checked={p.arabicEnabled}
                onChange={(e) => set("arabicEnabled", e.target.checked)}
                className="w-4 h-4 rounded text-emerald-500 focus:ring-emerald-500"
              />
              <div>
                <span className="font-bold text-xs text-[var(--ink)]">متاح بالحجز عربي 🇪🇬</span>
                <p className="text-[10px] text-[var(--ink-muted)]">إمكانية اختيار المسار العربي</p>
              </div>
            </label>

            <label className="flex items-center gap-2.5 p-3 rounded-lg border border-[var(--border)] bg-[var(--surface)] cursor-pointer hover:border-emerald-500/50">
              <input
                type="checkbox"
                checked={p.languagesEnabled}
                onChange={(e) => set("languagesEnabled", e.target.checked)}
                className="w-4 h-4 rounded text-emerald-500 focus:ring-emerald-500"
              />
              <div>
                <span className="font-bold text-xs text-[var(--ink)]">متاح بالحجز لغات 🇬🇧</span>
                <p className="text-[10px] text-[var(--ink-muted)]">إمكانية اختيار مسار اللغات</p>
              </div>
            </label>
          </div>
          {!p.languagesEnabled && (
            <p className="text-[11px] text-amber-400 font-semibold px-1">
              سيظهر للطلاب نص: "متاح للحجز باللغة العربية فقط (This teacher teaches Arabic only)"
            </p>
          )}
        </div>

        {/* 1 Month, 3 Months, 6 Months Subscription Plans */}
        <div className="space-y-4">
          {/* 1 Month Plan */}
          <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--bg)] space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-bold text-sm text-[var(--ink)] flex items-center gap-2">
                <span>⚡</span> اشتراك شهر واحد (1 Month)
              </h4>
              <label className="flex items-center gap-2 text-xs font-semibold text-[var(--ink-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={p.enableMonthly1}
                  onChange={(e) => set("enableMonthly1", e.target.checked)}
                  className="w-4 h-4 rounded text-emerald-500"
                />
                تفعيل الخطة
              </label>
            </div>
            {p.enableMonthly1 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className={label}>سعر العربي (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.priceMonthly1 ?? 200}
                    onChange={(e) => set("priceMonthly1", e.target.value ? Number(e.target.value) : null)}
                    placeholder="200"
                  />
                </div>
                <div>
                  <label className={label}>إضافة سعر اللغات (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.langSurcharge1 ?? 50}
                    onChange={(e) => set("langSurcharge1", e.target.value ? Number(e.target.value) : null)}
                    placeholder="+50"
                  />
                </div>
              </div>
            )}
          </div>

          {/* 3 Months Plan */}
          <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--bg)] space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-bold text-sm text-[var(--ink)] flex items-center gap-2">
                <span>📚</span> اشتراك 3 شهور (3 Months)
              </h4>
              <label className="flex items-center gap-2 text-xs font-semibold text-[var(--ink-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={p.enableMonthly3}
                  onChange={(e) => set("enableMonthly3", e.target.checked)}
                  className="w-4 h-4 rounded text-emerald-500"
                />
                تفعيل الخطة
              </label>
            </div>
            {p.enableMonthly3 && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className={label}>سعر العربي الساري (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.priceMonthly3 ?? 500}
                    onChange={(e) => set("priceMonthly3", e.target.value ? Number(e.target.value) : null)}
                    placeholder="500"
                  />
                </div>
                <div>
                  <label className={label}>السعر العربي قبل الخصم (مشطوب)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.originalMonthly3 ?? 600}
                    onChange={(e) => set("originalMonthly3", e.target.value ? Number(e.target.value) : null)}
                    placeholder="600"
                  />
                </div>
                <div>
                  <label className={label}>إضافة سعر اللغات (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.langSurcharge3 ?? 150}
                    onChange={(e) => set("langSurcharge3", e.target.value ? Number(e.target.value) : null)}
                    placeholder="+150"
                  />
                </div>
              </div>
            )}
          </div>

          {/* 6 Months Plan */}
          <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--bg)] space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-bold text-sm text-[var(--ink)] flex items-center gap-2">
                <span>🎓</span> اشتراك 6 شهور (6 Months)
              </h4>
              <label className="flex items-center gap-2 text-xs font-semibold text-[var(--ink-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={p.enableMonthly6}
                  onChange={(e) => set("enableMonthly6", e.target.checked)}
                  className="w-4 h-4 rounded text-emerald-500"
                />
                تفعيل الخطة
              </label>
            </div>
            {p.enableMonthly6 && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className={label}>سعر العربي الساري (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.priceMonthly6 ?? 1000}
                    onChange={(e) => set("priceMonthly6", e.target.value ? Number(e.target.value) : null)}
                    placeholder="1000"
                  />
                </div>
                <div>
                  <label className={label}>السعر العربي قبل الخصم (مشطوب)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.originalMonthly6 ?? 1200}
                    onChange={(e) => set("originalMonthly6", e.target.value ? Number(e.target.value) : null)}
                    placeholder="1200"
                  />
                </div>
                <div>
                  <label className={label}>إضافة سعر اللغات (جنيه)</label>
                  <input
                    type="number"
                    min="0"
                    className={input}
                    value={p.langSurcharge6 ?? 300}
                    onChange={(e) => set("langSurcharge6", e.target.value ? Number(e.target.value) : null)}
                    placeholder="+300"
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
          <div>
            <label className={label}>📅 تاريخ بدء أول كورس</label>
            <input
              type="date"
              className={input}
              value={p.courseStartDate ? p.courseStartDate.slice(0, 10) : ""}
              onChange={(e) => set("courseStartDate", e.target.value ? new Date(e.target.value).toISOString() : null)}
            />
          </div>
          <div>
            <label className={label}>🔗 رابط التواصل / الحجز (واتساب)</label>
            <input
              className={`${input} font-mono`}
              dir="ltr"
              value={p.bookingContactUrl ?? ""}
              onChange={(e) => set("bookingContactUrl", e.target.value || null)}
              placeholder="https://wa.me/201234567890"
            />
            <p className="text-[10px] text-[var(--ink-muted)] mt-1">رابط واتساب أو رقم الهاتف المخصص لتلقي طلبات الحجز المباشرة.</p>
          </div>
        </div>
      </div>

      <button onClick={save} disabled={saving} className={`${primaryBtn} w-full py-3 text-base`}>
        {saving ? "جارٍ حفظ إعداداتك…" : "حفظ بيانات الصفحة وإعدادات الحجز 💾"}
      </button>
    </div>
  );
}

