"use client";

import { useState, useEffect } from "react";
import { useToast } from "@/components/ui/Toast";

export function PlanLinksTab({ planId }: { planId: string }) {
  const { success, error: toastError } = useToast();
  const [links, setLinks] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    courseId: "",
    folderId: "",
    startIndex: "",
    endIndex: ""
  });

  const fetchData = async () => {
    setLoading(true);
    try {
      const [linksRes, coursesRes] = await Promise.all([
        fetch(`/api/admin/superadmin/plans/${planId}/course-links`),
        fetch("/api/admin/superadmin/courses")
      ]);

      const linksData = await linksRes.json();
      const coursesData = await coursesRes.json();

      if (linksRes.ok) setLinks(linksData.links || []);
      if (coursesRes.ok) setCourses(coursesData.courses || []);
    } catch (err) {
      toastError("تعذر جلب البيانات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [planId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.courseId) {
      toastError("يرجى اختيار الدورة");
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch(`/api/admin/superadmin/plans/${planId}/course-links`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          courseId: formData.courseId,
          folderId: formData.folderId.trim() || null,
          startIndex: formData.startIndex !== "" ? Number(formData.startIndex) : null,
          endIndex: formData.endIndex !== "" ? Number(formData.endIndex) : null,
        })
      });

      const data = await res.json();
      if (res.ok) {
        success("تم ربط الدورة بنجاح وجاري مزامنة الفيديوهات");
        setFormData({ courseId: "", folderId: "", startIndex: "", endIndex: "" });
        fetchData();
      } else {
        toastError(data.error || "فشل ربط الدورة");
      }
    } catch {
      toastError("حدث خطأ أثناء ربط الدورة");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (linkId: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا الارتباط؟ سيتم إبقاء الفيديوهات الحالية ولكن لن يتم مزامنة الفيديوهات الجديدة.")) {
      return;
    }

    try {
      const res = await fetch(`/api/admin/superadmin/plans/${planId}/course-links/${linkId}`, {
        method: "DELETE"
      });
      if (res.ok) {
        success("تم حذف الارتباط بنجاح");
        fetchData();
      } else {
        const data = await res.json().catch(() => ({}));
        toastError(data.error || "فشل الحذف");
      }
    } catch {
      toastError("حدث خطأ أثناء الحذف");
    }
  };

  if (loading) return <div className="text-center py-10">جاري التحميل...</div>;

  return (
    <div className="space-y-6" dir="rtl">
      {/* Link Form */}
      <form onSubmit={handleSubmit} className="p-5 border rounded-2xl bg-[var(--surface-2)] space-y-4" style={{ borderColor: "var(--border)" }}>
        <h4 className="font-bold text-base text-[var(--ink)]">ربط دورة جديدة بالخطة</h4>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold mb-1 text-[var(--ink)]">الدورة الدراسية</label>
            <select
              value={formData.courseId}
              onChange={e => setFormData({ ...formData, courseId: e.target.value })}
              className="w-full p-2 border rounded bg-[var(--surface)] text-[var(--ink)] text-sm"
              style={{ borderColor: "var(--border)" }}
              required
            >
              <option value="">-- اختر الدورة --</option>
              {courses.map(c => (
                <option key={c.id} value={c.id}>
                  {c.title} ({c.teacher?.name || "معلم غير معروف"})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-bold mb-1 text-[var(--ink)]">معرف المجلد (اختياري - للمزامنة من مجلد محدد)</label>
            <input
              type="text"
              placeholder="مثال: clq12345..."
              value={formData.folderId}
              onChange={e => setFormData({ ...formData, folderId: e.target.value })}
              className="w-full p-2 border rounded bg-[var(--surface)] text-[var(--ink)] text-sm"
              style={{ borderColor: "var(--border)" }}
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold mb-1 text-[var(--ink)]">فهرس البداية (اختياري)</label>
            <input
              type="number"
              min="0"
              placeholder="مثال: 0"
              value={formData.startIndex}
              onChange={e => setFormData({ ...formData, startIndex: e.target.value })}
              className="w-full p-2 border rounded bg-[var(--surface)] text-[var(--ink)] text-sm"
              style={{ borderColor: "var(--border)" }}
            />
          </div>

          <div>
            <label className="block text-xs font-bold mb-1 text-[var(--ink)]">فهرس النهاية (اختياري)</label>
            <input
              type="number"
              min="0"
              placeholder="مثال: 5"
              value={formData.endIndex}
              onChange={e => setFormData({ ...formData, endIndex: e.target.value })}
              className="w-full p-2 border rounded bg-[var(--surface)] text-[var(--ink)] text-sm"
              style={{ borderColor: "var(--border)" }}
            />
          </div>
        </div>

        <button
          type="submit"
          disabled={submitting}
          className="px-5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-sm border-none cursor-pointer disabled:opacity-50"
        >
          {submitting ? "جاري الحفظ والربط..." : "ربط الدورة الآن"}
        </button>
      </form>

      {/* Linked Courses List */}
      <div className="space-y-4">
        <h4 className="font-bold text-base text-[var(--ink)]">الدورات المرتبطة حالياً ({links.length})</h4>
        
        {links.length === 0 ? (
          <div className="text-center py-10 text-gray-500 bg-gray-50/50 dark:bg-gray-900/10 rounded-xl border border-dashed" style={{ borderColor: "var(--border)" }}>
            لا توجد دورات مرتبطة بهذه الخطة بعد.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-right text-sm border-collapse">
              <thead>
                <tr className="border-b" style={{ borderColor: "var(--border)" }}>
                  <th className="pb-3 pt-2 font-bold text-[var(--ink)]">الدورة</th>
                  <th className="pb-3 pt-2 font-bold text-[var(--ink)]">المعلم</th>
                  <th className="pb-3 pt-2 font-bold text-[var(--ink)]">التصفية / التقسيم</th>
                  <th className="pb-3 pt-2 font-bold text-[var(--ink)]">الإجراءات</th>
                </tr>
              </thead>
              <tbody>
                {links.map(link => (
                  <tr key={link.id} className="border-b hover:bg-gray-50/40 dark:hover:bg-gray-800/10" style={{ borderColor: "var(--border)" }}>
                    <td className="py-3 font-semibold text-[var(--ink)]">{link.course?.title}</td>
                    <td className="py-3 text-[var(--ink-2)]">{link.course?.teacher?.name || "—"}</td>
                    <td className="py-3 text-[var(--ink-2)] text-xs">
                      {link.folderId ? `مجلد: ${link.folderId}` : "كل المجلدات"}
                      {link.startIndex !== null || link.endIndex !== null ? (
                        <span className="mr-2 bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded text-[10px]">
                          الفهارس: [{link.startIndex ?? 0} إلى {link.endIndex ?? "نهاية"}]
                        </span>
                      ) : null}
                    </td>
                    <td className="py-3">
                      <button
                        onClick={() => handleDelete(link.id)}
                        className="text-red-500 hover:text-red-700 bg-transparent border-none cursor-pointer font-bold text-xs"
                      >
                        حذف الارتباط
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useToast } from "@/components/ui/Toast";
import { IconPlus, IconFolder, IconBook } from "@/components/admin/AdminIcons";

export function PlanList({ onSelectPlan }: { onSelectPlan: (id: string) => void }) {
  const { success, error } = useToast();
  const [plans, setPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [stageFilter, setStageFilter] = useState("");
  const [showCreateModal, setShowCreateModal] = useState(false);

  // Form State for creating a new plan
  const [newPlan, setNewPlan] = useState({
    title: "",
    description: "",
    educationalStage: "sec_1",
    monthIndex: 1,
    price: 0,
    durationDays: 30,
    chatEnabled: true,
    gradingAIEnabled: true
  });

  const fetchPlans = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/admin/superadmin/plans${stageFilter ? `?stage=${stageFilter}` : ""}`);
      const data = await res.json();
      if (res.ok) setPlans(data.plans || []);
      else error(data.error);
    } catch {
      error("تعذر جلب الخطط");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPlans();
  }, [stageFilter]);

  const STAGES = [
    { value: "", label: "الكل" },
    { value: "sec_1", label: "أولى بكالوريا" },
    { value: "sec_2", label: "ثانية بكالوريا" },
  ];

  const getStageLabel = (stage: string) => {
    const s = STAGES.find(x => x.value === stage);
    return s ? s.label : stage;
  };

  const handleCreatePlan = async (e: React.FormEvent) => {
    e.preventDefault();
    const points = newPlan.description.split("\n").map(p => p.trim()).filter(Boolean);
    const serializedDesc = JSON.stringify(points);
    try {
      const res = await fetch("/api/admin/superadmin/plans", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...newPlan,
          description: serializedDesc,
          monthIndex: Number(newPlan.monthIndex),
          price: Number(newPlan.price),
          durationDays: Number(newPlan.durationDays)
        })
      });

      const data = await res.json();
      if (res.ok) {
        success("تم إنشاء الخطة بنجاح");
        setShowCreateModal(false);
        setNewPlan({
          title: "",
          description: "",
          educationalStage: "sec_1",
          monthIndex: 1,
          price: 0,
          durationDays: 30,
          chatEnabled: true,
          gradingAIEnabled: true
        });
        fetchPlans();
      } else {
        error(data.error || "فشل إنشاء الخطة");
      }
    } catch {
      error("حدث خطأ أثناء الإنشاء");
    }
  };

  return (
    <div className="space-y-4" dir="rtl">
      <div className="flex items-center justify-between">
        <select
          value={stageFilter}
          onChange={(e) => setStageFilter(e.target.value)}
          className="px-4 py-2 rounded-lg border outline-none text-sm font-bold"
          style={{ background: "var(--surface)", borderColor: "var(--border)", color: "var(--ink)" }}
        >
          {STAGES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
        </select>

        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 text-white font-bold rounded-lg transition-opacity hover:opacity-90 cursor-pointer border-none text-sm"
          style={{ background: "var(--brand)" }}
        >
          <IconPlus className="w-4 h-4" />
          إنشاء خطة جديدة
        </button>
      </div>

      {loading ? (
        <div className="p-10 text-center animate-pulse" style={{ color: "var(--ink-3)" }}>جارٍ التحميل...</div>
      ) : plans.length === 0 ? (
        <div className="p-10 text-center" style={{ color: "var(--ink-3)" }}>لا توجد خطط دراسية</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {plans.map(plan => (
            <div
              key={plan.id}
              onClick={() => onSelectPlan(plan.id)}
              className="rounded-xl p-5 cursor-pointer transition-all hover:-translate-y-1"
              style={{ background: "var(--surface)", border: "1px solid var(--border)", boxShadow: "var(--shadow-sm)" }}
            >
              <div className="flex justify-between items-start mb-4">
                <span className={`px-2 py-1 text-xs font-bold rounded-full ${
                  plan.status === "published" ? "bg-green-100 text-green-700" :
                  plan.status === "archived" ? "bg-gray-100 text-gray-700" :
                  "bg-amber-100 text-amber-700"
                }`}>
                  {plan.status === "published" ? "منشورة" : plan.status === "archived" ? "مؤرشفة" : "مسودة"}
                </span>
                <span className="text-xs font-semibold" style={{ color: "var(--brand)" }}>
                  {plan.price.toLocaleString("ar-EG")} ج.م
                </span>
              </div>
              
              <h3 className="font-bold text-lg mb-1" style={{ color: "var(--ink)" }}>{plan.title}</h3>
              
              {/* Display Educational Stage and Month Index */}
              <div className="flex gap-2 my-2">
                <span className="bg-purple-50 text-purple-700 px-2 py-0.5 rounded text-[11px] font-bold">
                  {getStageLabel(plan.educationalStage)}
                </span>
                <span className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-[11px] font-bold">
                  الشهر {plan.monthIndex}
                </span>
              </div>

              <p className="text-sm line-clamp-2 mb-4" style={{ color: "var(--ink-2)" }}>{plan.description}</p>
              
              <div className="flex items-center gap-4 text-xs font-semibold" style={{ color: "var(--ink-3)" }}>
                <span className="flex items-center gap-1">
                  <IconBook className="w-4 h-4" />
                  {plan._count?.lessons || 0} درس
                </span>
                <span className="flex items-center gap-1">
                  <IconFolder className="w-4 h-4" />
                  {plan._count?.enrollments || 0} طالب
                </span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Plan Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="w-full max-w-lg bg-[var(--surface)] border border-[var(--border)] rounded-2xl shadow-xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-5 border-b border-[var(--border)] flex justify-between items-center bg-slate-50 dark:bg-slate-900/50">
              <h3 className="text-lg font-black text-[var(--ink)]">إنشاء خطة دراسية جديدة</h3>
              <button 
                onClick={() => setShowCreateModal(false)}
                className="text-gray-400 hover:text-gray-600 bg-transparent border-none cursor-pointer text-xl font-bold"
              >
                &times;
              </button>
            </div>
            
            <form onSubmit={handleCreatePlan} className="p-6 overflow-y-auto space-y-4 flex-1">
              <div>
                <label className="block text-sm font-bold mb-1 text-[var(--ink)]">المرحلة الدراسية</label>
                <select
                  value={newPlan.educationalStage}
                  onChange={e => setNewPlan({...newPlan, educationalStage: e.target.value})}
                  className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                  style={{ borderColor: "var(--border)" }}
                >
                  {STAGES.filter(s => s.value !== "").map(s => (
                    <option key={s.value} value={s.value}>{s.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-bold mb-1 text-[var(--ink)]">مؤشر الشهر</label>
                <input 
                  type="number"
                  min="1"
                  max="12"
                  value={newPlan.monthIndex}
                  onChange={e => setNewPlan({...newPlan, monthIndex: Number(e.target.value)})}
                  className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                  style={{ borderColor: "var(--border)" }}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-bold mb-1 text-[var(--ink)]">عنوان الخطة</label>
                <input 
                  type="text"
                  value={newPlan.title}
                  onChange={e => setNewPlan({...newPlan, title: e.target.value})}
                  className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                  style={{ borderColor: "var(--border)" }}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-bold mb-1 text-[var(--ink)]">الوصف</label>
                <textarea 
                  value={newPlan.description}
                  onChange={e => setNewPlan({...newPlan, description: e.target.value})}
                  className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                  style={{ borderColor: "var(--border)" }}
                  rows={3}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold mb-1 text-[var(--ink)]">السعر (جنيه)</label>
                  <input 
                    type="number"
                    min="0"
                    value={newPlan.price}
                    onChange={e => setNewPlan({...newPlan, price: Number(e.target.value)})}
                    className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                    style={{ borderColor: "var(--border)" }}
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold mb-1 text-[var(--ink)]">المدة (بالأيام)</label>
                  <input 
                    type="number"
                    min="1"
                    value={newPlan.durationDays}
                    onChange={e => setNewPlan({...newPlan, durationDays: Number(e.target.value)})}
                    className="w-full p-2 border rounded bg-[var(--surface-2)] text-[var(--ink)]"
                    style={{ borderColor: "var(--border)" }}
                    required
                  />
                </div>
              </div>

              <div className="flex flex-col gap-2 pt-2">
                <label className="flex items-center gap-2 text-sm font-bold text-[var(--ink)] cursor-pointer">
                  <input 
                    type="checkbox"
                    checked={newPlan.chatEnabled}
                    onChange={e => setNewPlan({...newPlan, chatEnabled: e.target.checked})}
                    className="w-4 h-4 rounded text-indigo-600"
                  />
                  تفعيل شات المساعد الذكي
                </label>
                <label className="flex items-center gap-2 text-sm font-bold text-[var(--ink)] cursor-pointer">
                  <input 
                    type="checkbox"
                    checked={newPlan.gradingAIEnabled}
                    onChange={e => setNewPlan({...newPlan, gradingAIEnabled: e.target.checked})}
                    className="w-4 h-4 rounded text-indigo-600"
                  />
                  تفعيل تقييم المشاريع بالذكاء الاصطناعي
                </label>
              </div>

              <div className="flex gap-3 pt-4 border-t border-[var(--border)]">
                <button
                  type="submit"
                  className="flex-1 py-2 text-white font-bold rounded-xl border-none cursor-pointer text-sm"
                  style={{ background: "var(--brand)" }}
                >
                  حفظ الخطة
                </button>
                <button
                  type="button"
                  onClick={() => setShowCreateModal(false)}
                  className="flex-1 py-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-800 dark:hover:bg-gray-700 text-[var(--ink-2)] font-bold rounded-xl border-none cursor-pointer text-sm"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useToast } from "@/components/ui/Toast";

export function UnmatchedQueue() {
  const { error } = useToast();
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchItems = async () => {
      try {
        const res = await fetch("/api/admin/superadmin/plans/unmatched-content");
        const data = await res.json();
        if (res.ok) setItems(data.items || []);
        else error(data.error);
      } catch {
        error("تعذر جلب المحتوى غير المطابق");
      } finally {
        setLoading(false);
      }
    };
    fetchItems();
  }, [error]);

  if (loading) return <div className="p-10 text-center text-[var(--ink-3)] animate-pulse">جارٍ التحميل...</div>;
  if (items.length === 0) return <div className="p-10 text-center text-[var(--ink-3)]">لا يوجد محتوى غير مطابق يحتاج لتدخل</div>;

  return (
    <div className="space-y-4">
      {items.map(item => (
        <div key={item.id} className="p-4 rounded-xl" style={{ background: "var(--surface)", border: "1px solid var(--border)" }}>
          <p className="font-bold text-[var(--ink)]">{item.video?.title || "فيديو بدون عنوان"}</p>
          <p className="text-sm text-[var(--ink-2)] mt-1">{item.reason}</p>
          <div className="mt-4 flex gap-2">
            <button className="px-4 py-2 text-sm font-bold text-white bg-brand rounded-lg">تعيين إلى درس</button>
            <button className="px-4 py-2 text-sm font-bold text-[var(--ink-2)] bg-[var(--surface-2)] rounded-lg">تجاهل</button>
          </div>
        </div>
      ))}
    </div>
  );
}

