/**
 * Semantically compare student terminal output to teacher's expected output.
 * Handles cases where a different function/method produces the same result.
 *
 * @returns { passed: boolean, explanation: string }
 */
export async function evaluateTerminalWithAI(
  codeTemplate: string,
  submittedOutput: string,
  expectedOutput: string,
  language: string
): Promise<{ passed: boolean; explanation: string }> {
  const { primary, backup } = await resolvePlanProviders();

  const systemPrompt = `You are a strict programming teacher evaluating a student's terminal output.
Your job: compare the student's actual output to the expected output and decide if they are semantically equivalent.
Rules:
- Ignore whitespace, newlines, and letter casing differences.
- If the student achieved the CORRECT result using a DIFFERENT function, loop, or approach, they should still PASS.
- Only fail if the output is factually incorrect or the logic is fundamentally wrong.
Respond with ONLY valid JSON: { "passed": true/false, "explanation": "brief Arabic explanation" }`;

  const userPrompt = `Language: ${language}
Code template given to student:
${codeTemplate || "(none)"}

Expected output:
${expectedOutput}

Student's submitted output:
${submittedOutput}

Does the student's output match or is semantically equivalent to the expected output?`;

  async function callForVerdict(provider: ResolvedProvider): Promise<{ passed: boolean; explanation: string } | null> {
    try {
      const base = provider.baseUrl.replace(/\/+$/, "");
      let text = "";

      if (provider.kind === "anthropic") {
        const res = await fetch(base, {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-api-key": provider.key, "anthropic-version": "2023-06-01" },
          body: JSON.stringify({ model: provider.model, max_tokens: 256, system: systemPrompt, messages: [{ role: "user", content: userPrompt }] }),
          signal: AbortSignal.timeout(20000),
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const d = await res.json() as { content?: Array<{ text?: string }> };
        text = d.content?.[0]?.text || "";
      } else if (provider.kind === "gemini") {
        const geminiBase = base.endsWith("/models") ? base : `${base}/models`;
        const res = await fetch(`${geminiBase}/${provider.model}:generateContent?key=${provider.key}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ contents: [{ parts: [{ text: `${systemPrompt}\n\n${userPrompt}` }] }], generationConfig: { maxOutputTokens: 256 } }),
          signal: AbortSignal.timeout(20000),
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const d = await res.json() as { candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }> };
        text = d.candidates?.[0]?.content?.parts?.[0]?.text || "";
      } else {
        // OpenAI-compatible
        const res = await fetch(`${base}/chat/completions`, {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${provider.key}` },
          body: JSON.stringify({ model: provider.model, max_tokens: 256, messages: [{ role: "system", content: systemPrompt }, { role: "user", content: userPrompt }] }),
          signal: AbortSignal.timeout(20000),
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const d = await res.json() as { choices?: Array<{ message?: { content?: string } }> };
        text = d.choices?.[0]?.message?.content || "";
      }

      // Extract JSON from response
      const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
      const candidate = (fenced ? fenced[1] : text).trim();
      const start = candidate.indexOf("{");
      const end = candidate.lastIndexOf("}");
      const parsed = JSON.parse(candidate.slice(start, end + 1)) as { passed: boolean; explanation: string };
      if (typeof parsed.passed !== "boolean") throw new Error("Invalid verdict format");
      return parsed;
    } catch (err) {
      console.error(`Terminal AI evaluator error (${provider.name}):`, err instanceof Error ? err.message : err);
      return null;
    }
  }

  if (primary) {
    const result = await callForVerdict(primary);
    if (result) return result;
  }
  if (backup) {
    const result = await callForVerdict(backup);
    if (result) return result;
  }

  // Both providers failed — cannot safely determine; trigger human review
  throw new Error("AI evaluation unavailable");
}

const EGYPT_MOBILE_REGEX = /^01[0-9]{9}$/;

export function normalizeEgyptPhone(input: string) {
  const raw = String(input || "").trim();
  try {
    console.log("normalizeEgyptPhone raw:", JSON.stringify(raw), "codes:", Array.from(raw).map((c) => c.charCodeAt(0)));
  } catch (e) {
    console.log("normalizeEgyptPhone raw (stringify failed)");
  }
  // convert Arabic-Indic numerals to ASCII digits
  const arabicMap: Record<string, string> = {
    '\u0660': '0', '\u0661': '1', '\u0662': '2', '\u0663': '3', '\u0664': '4', '\u0665': '5', '\u0666': '6', '\u0667': '7', '\u0668': '8', '\u0669': '9',
    '\u06F0': '0', '\u06F1': '1', '\u06F2': '2', '\u06F3': '3', '\u06F4': '4', '\u06F5': '5', '\u06F6': '6', '\u06F7': '7', '\u06F8': '8', '\u06F9': '9',
  };
  let cleaned = raw.replace(/[\u0660-\u0669\u06F0-\u06F9]/g, (d) => arabicMap[d] || d);
  // remove international 00 prefix -> +
  cleaned = cleaned.replace(/^00/, "+");
  // If the input is already E.164 (starts with +), accept as-is to support non-Egyptian E.164 numbers
  if (cleaned.startsWith("+")) {
    const digitsOnly = cleaned.replace(/\D/g, "");
    // If it's an Egyptian E.164 return normalized +20... format
    if (digitsOnly.startsWith("20") && digitsOnly.length === 12) {
      return `+${digitsOnly}`;
    }
    // Otherwise assume caller provided a valid E.164 number (e.g., TWILIO_FROM_NUMBER)
    return cleaned;
  }
  const digits = cleaned.replace(/\D/g, "");

  // +20XXXXXXXXXX or 20XXXXXXXXXX
  if ((digits.startsWith("20") || digits.startsWith("2")) && digits.length === 12) {
    return `+${digits}`;
  }

  // local 01XXXXXXXXX
  if (EGYPT_MOBILE_REGEX.test(digits)) {
    return `+20${digits.slice(1)}`;
  }

  // Fallback: if the digits string contains an occurrence of 01XXXXXXXXX, extract it
  const found = digits.match(/01[0-9]{9}/);
  if (found) {
    const m = found[0];
    return `+20${m.slice(1)}`;
  }

  throw new Error("رقم الهاتف غير صالح. استخدم رقم مصري يبدأ بـ 01");
}

export function formatDisplayPhone(input: string) {
  const digits = input.replace(/\D/g, "");
  if (digits.startsWith("0")) {
    return digits;
  }
  if (digits.startsWith("20") && digits.length === 12) {
    return `0${digits.slice(2)}`;
  }
  if (digits.startsWith("2") && digits.length === 12) {
    return `0${digits.slice(2)}`;
  }
  return input;
}

import { prisma } from "./prisma";
import { acquireAdvisoryLock } from "./distributed-lock";
import { withDbRetry } from "./db-retry";

// 1. Normalization helpers
export function normalizeTitle(title: string): string {
  let s = title.trim();
  // Strip Arabic diacritics (tashkeel)
  s = s.replace(/[\u0617-\u061A\u064B-\u0652]/g, "");
  // Convert Arabic-Indic digits to ASCII (٠١٢٣٤٥٦٧٨٩ -> 0123456789)
  s = s.replace(/[٠-٩]/g, (d) => String.fromCharCode(d.charCodeAt(0) - 0x0660 + 48));
  
  // Replace common Arabic ordinals with digits
  const ordinals: Record<string, string> = {
    "الاول": "1", "الأول": "1", "الاولى": "1", "الأولى": "1",
    "الثاني": "2", "الثانيه": "2", "الثانية": "2",
    "الثالث": "3", "الثالثه": "3", "الثالثة": "3",
    "الرابع": "4", "الرابعه": "4", "الرابعة": "4",
    "الخامس": "5", "الخامسه": "5", "الخامسة": "5",
    "السادس": "6", "السادسه": "6", "السادسة": "6",
    "السابع": "7", "السابعه": "7", "السابعة": "7",
    "الثامن": "8", "الثامنه": "8", "الثامنة": "8",
    "التاسع": "9", "التاسعه": "9", "التاسعة": "9",
    "العاشر": "10", "العاشره": "10", "العاشرة": "10",
  };
  
  for (const [word, digit] of Object.entries(ordinals)) {
    const regex = new RegExp(`\\b${word}\\b`, 'g');
    s = s.replace(regex, digit);
  }
  
  return s;
}

export function extractNumber(title: string): number | null {
  const normalized = normalizeTitle(title);
  const match = normalized.match(/\d+/);
  if (match) return parseInt(match[0], 10);
  return null;
}

/**
 * Triggered when a video is created, edited, or deleted.
 * Finds all plans linked to this video's course and re-syncs them.
 */
export async function triggerPlanSyncForCourse(courseId: string) {
  const links = await prisma.planCourseLink.findMany({
    where: { courseId },
    select: { planId: true },
  });

  // Sync each plan sequentially to avoid massive concurrent load
  for (const link of links) {
    await syncCourseToPlan(link.planId, courseId).catch(err => {
      console.error(`Failed to sync course ${courseId} to plan ${link.planId}`, err);
    });
  }
}

/**
 * The core auto-matching engine.
 * Serialized per plan using advisory locks.
 */
export async function syncCourseToPlan(planId: string, courseId: string) {
  return withDbRetry(async () => {
    return prisma.$transaction(async (tx) => {
      // 1. Acquire distributed lock to prevent concurrent sync races for this plan
      await acquireAdvisoryLock(`plan-sync-${planId}`, tx);

      const plan = await tx.plan.findUnique({
        where: { id: planId },
        include: { lessons: { orderBy: { order: "asc" } } },
      });
      if (!plan || plan.lessons.length === 0) return;

      const link = await tx.planCourseLink.findFirst({
        where: { planId, courseId },
      });
      if (!link) return;

      const course = await tx.course.findUnique({
        where: { id: courseId },
        include: {
          folders: {
            where: link.folderId ? { id: link.folderId } : undefined,
            orderBy: { order: "asc" },
            include: {
              videos: { orderBy: { order: "asc" } }
            }
          }
        }
      });
      if (!course) return;

      // Collect all videos in order
      const allVideos: { videoId: string; folderId: string; videoTitle: string; teacherId: string; monthIndex: number | null; lessonIndexInMonth: number | null }[] = [];
      
      for (const folder of course.folders) {
        // Auto-extract month index if not manual
        let mIndex = folder.monthIndex;
        if (!folder.monthIndexIsManual) {
          const parsed = extractNumber(folder.name);
          if (parsed !== null) mIndex = parsed;
        }

        for (const video of folder.videos) {
          // Auto-extract lesson index if not manual
          let lIndex = video.lessonIndexInMonth;
          if (!video.lessonIndexIsManual) {
            const parsed = extractNumber(video.title);
            if (parsed !== null) lIndex = parsed;
          }

          allVideos.push({
            videoId: video.id,
            folderId: folder.id,
            videoTitle: video.title,
            teacherId: course.teacherId,
            monthIndex: mIndex,
            lessonIndexInMonth: lIndex
          });
        }
      }

      // Filter to videos matching the plan's month index
      const monthVideos = allVideos.filter(v => v.monthIndex === null || v.monthIndex === plan.monthIndex);

      // Sort by auto-extracted lesson index, fallback to natural order
      monthVideos.sort((a, b) => {
        if (a.lessonIndexInMonth !== null && b.lessonIndexInMonth !== null) {
          if (a.lessonIndexInMonth !== b.lessonIndexInMonth) return a.lessonIndexInMonth - b.lessonIndexInMonth;
        }
        return 0; // maintain natural order if indices missing/equal
      });

      // Apply slicing if specified in the link
      let slicedVideos = monthVideos;
      if (link.startIndex !== null || link.endIndex !== null) {
        const start = link.startIndex ?? 0;
        const end = link.endIndex !== null ? link.endIndex : slicedVideos.length - 1;
        slicedVideos = slicedVideos.slice(start, end + 1);
      }

      // Map to available lessons
      const lessonsToUpdate = Math.min(slicedVideos.length, plan.lessons.length);
      
      for (let i = 0; i < slicedVideos.length; i++) {
        const video = slicedVideos[i];
        
        if (i < plan.lessons.length) {
          const targetLesson = plan.lessons[i];
          
          // Check if this video is already a source
          const existingSource = await tx.planLessonSource.findFirst({
            where: { planLessonId: targetLesson.id, videoId: video.videoId }
          });

          if (!existingSource) {
            await tx.planLessonSource.create({
              data: {
                planLessonId: targetLesson.id,
                videoId: video.videoId,
                teacherId: video.teacherId,
                isDefault: false, // Let admin choose the default
                isManual: false
              }
            });
          }
          
          // Optionally resolve unmatched content if it existed
          await tx.unmatchedPlanContent.updateMany({
            where: { videoId: video.videoId, resolvedAt: null },
            data: { resolvedAt: new Date() }
          });
          
        } else {
          // Unmatched (plan doesn't have enough lessons)
          const existingUnmatched = await tx.unmatchedPlanContent.findFirst({
            where: { videoId: video.videoId, courseId, resolvedAt: null }
          });
          if (!existingUnmatched) {
            await tx.unmatchedPlanContent.create({
              data: {
                teacherId: video.teacherId,
                videoId: video.videoId,
                courseId,
                title: video.videoTitle,
                reason: "لا يوجد عدد كافي من الدروس في الخطة لاستيعاب هذا الفيديو"
              }
            });
          }
        }
      }
    });
  });
}

