// Key index tracked client-side (mirrors server-side _keyIndex in ai-caller.ts)
let _clientKeyIndex = 0;
export function rotateClientKey() { _clientKeyIndex = (_clientKeyIndex + 1) % 2; }
export function getClientKeyIndex() { return _clientKeyIndex; }

interface QuotaState {
  date: string;
  // Tracks per-key usage: key1 and key2
  usage: Partial<Record<string, { requests: number; tokens: number }>>;
}

/** Build a composite storage key that includes which API key was used */
function modelKey(model: ModelId, keyIndex = 0): string {
  return `${model}:k${keyIndex}`;
}

function todayKey(): string {
  return new Date().toISOString().split("T")[0];
}

export function getQuotaState(): QuotaState {
  if (typeof window === "undefined") return { date: todayKey(), usage: {} };
  try {
    const raw = localStorage.getItem(QUOTA_KEY);
    if (!raw) return { date: todayKey(), usage: {} };
    const parsed = JSON.parse(raw) as QuotaState;
    // Daily reset
    if (parsed.date !== todayKey()) return { date: todayKey(), usage: {} };
    return parsed;
  } catch {
    return { date: todayKey(), usage: {} };
  }
}

function saveQuotaState(state: QuotaState) {
  if (typeof window === "undefined") return;
  localStorage.setItem(QUOTA_KEY, JSON.stringify(state));
}

function getModelUsage(model: ModelId) {
  const state = getQuotaState();
  return state.usage[model] ?? { requests: 0, tokens: 0 };
}

// ── Select the best available model for a task ─────────────────────────────
export function selectModel(task: TaskType): ModelId {
  const candidates = TASK_ROUTING[task];

  for (const model of candidates) {
    const limit = QUOTA_LIMITS[model];
    if (limit.rpd === null) return model; // ∞ — always use
    const usage = getModelUsage(model);
    const safeLimit = Math.floor(limit.rpd * 0.9); // 10% emergency buffer
    if (usage.requests < safeLimit) return model;
    console.warn(`[Quota] ${model} near limit (${usage.requests}/${limit.rpd}), trying fallback`);
  }

  console.error("[Quota] All preferred models near limit, falling back to flash-lite");
  return "gemini-2.0-flash-lite";
}

// ── Record usage after every API call ─────────────────────────────────────
export function recordUsage(model: ModelId, tokensUsed: number) {
  const state = getQuotaState();
  const cur = state.usage[model] ?? { requests: 0, tokens: 0 };
  state.usage[model] = { requests: cur.requests + 1, tokens: cur.tokens + tokensUsed };
  saveQuotaState(state);
}

// ── Read remaining quota (for dashboard / admin) ───────────────────────────
export function getRemainingQuota(model: ModelId): {
  requestsUsed: number;
  requestsLeft: number | "∞";
  tokensUsed: number;
  percentage: number;
} {
  const limit = QUOTA_LIMITS[model];
  const usage = getModelUsage(model);
  if (limit.rpd === null) {
    return { requestsUsed: usage.requests, requestsLeft: "∞", tokensUsed: usage.tokens, percentage: 0 };
  }
  return {
    requestsUsed: usage.requests,
    requestsLeft: Math.max(0, limit.rpd - usage.requests),
    tokensUsed:   usage.tokens,
    percentage:   Math.round((usage.requests / limit.rpd) * 100),
  };
}

// ── Guard for expensive models ─────────────────────────────────────────────
export function canUseModel(model: ModelId, minRemaining = 2): boolean {
  const { requestsLeft } = getRemainingQuota(model);
  if (requestsLeft === "∞") return true;
  return requestsLeft >= minRemaining;
}

// ── Summary for admin panel ────────────────────────────────────────────────
export function getAllQuotaSummary() {
  return (Object.keys(QUOTA_LIMITS) as ModelId[]).map(model => ({
    model,
    ...getRemainingQuota(model),
    limit: QUOTA_LIMITS[model].rpd ?? "∞",
  }));
}

import { prisma } from "@/lib/prisma";
import { POINTS } from "@/lib/points";

export type ReferralStatus = "PENDING" | "QUALIFIED" | "REWARDED" | "INVALID";

export class ReferralService {
  /**
   * Registers a new PENDING referral link when student B signs up using Student A's referral code.
   * Does NOT award any points on raw signup to prevent bot farming.
   */
  public static async registerPendingReferral(
    inviterId: string,
    invitedId: string
  ): Promise<boolean> {
    if (inviterId === invitedId) {
      console.warn(`[ReferralService] Rejected self-referral for user ${inviterId}`);
      return false;
    }

    try {
      await prisma.referral.create({
        data: {
          inviterId,
          invitedId,
          status: "PENDING",
        },
      });
      return true;
    } catch (err) {
      // Handles UNIQUE(invitedId) constraint if user was already referred
      console.warn(`[ReferralService] User ${invitedId} already has a referral record.`);
      return false;
    }
  }

  /**
   * Qualifies and awards referral rewards (POINTS.REFERRAL to inviter & invited student)
   * upon a valid paid course purchase or access code redemption.
   * 
   * Atomically transitions status PENDING -> QUALIFIED -> REWARDED inside a transaction.
   */
  public static async qualifyAndRewardReferral(
    invitedStudentId: string,
    qualifyingPurchaseId: string
  ): Promise<{ rewarded: boolean; pointsAwarded: number }> {
    return await prisma.$transaction(async (tx) => {
      const referral = await tx.referral.findUnique({
        where: { invitedId: invitedStudentId },
      });

      if (!referral) {
        return { rewarded: false, pointsAwarded: 0 };
      }

      // Must be in PENDING status and not previously rewarded
      if (referral.status !== "PENDING") {
        return { rewarded: false, pointsAwarded: 0 };
      }

      // Transition to REWARDED state atomically
      await tx.referral.update({
        where: { id: referral.id },
        data: {
          status: "REWARDED",
          qualifyingPurchaseId,
          rewardedAt: new Date(),
        },
      });

      // Award POINTS.REFERRAL (+50 XP) to inviter & invited student
      const rewardPoints = POINTS.REFERRAL ?? 50;
      await tx.user.update({
        where: { id: referral.inviterId },
        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
      });

      await tx.user.update({
        where: { id: referral.invitedId },
        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
      });

      // Audit Log
      await tx.auditLog.create({
        data: {
          userId: referral.invitedId,
          action: "REFERRAL_REWARDED",
          ip: "127.0.0.1",
          metadata: JSON.stringify({
            inviterId: referral.inviterId,
            invitedId: referral.invitedId,
            qualifyingPurchaseId,
            rewardPoints,
          }),
        },
      }).catch(() => {});

      console.log(`[ReferralService] Successfully rewarded ${rewardPoints} XP to inviter ${referral.inviterId} and invited ${referral.invitedId}`);

      return { rewarded: true, pointsAwarded: rewardPoints };
    });
  }

  /**
   * Retrieves summary telemetry of referrals for admin security dashboard.
   */
  public static async getReferralTelemetry(): Promise<{
    pending: number;
    qualified: number;
    rewarded: number;
    invalid: number;
    total: number;
  }> {
    const [pending, qualified, rewarded, invalid, total] = await Promise.all([
      prisma.referral.count({ where: { status: "PENDING" } }),
      prisma.referral.count({ where: { status: "QUALIFIED" } }),
      prisma.referral.count({ where: { status: "REWARDED" } }),
      prisma.referral.count({ where: { status: "INVALID" } }),
      prisma.referral.count(),
    ]);

    return { pending, qualified, rewarded, invalid, total };
  }
}
